import type {
  EUDSettings,
  MerchantConfig,
  MemberInfo,
  EUDSettingsResponse,
  MemberInfoResponse,
  FetchEUDSettingsParams,
  FetchMemberInfoParams
} from './eud-dashboard.types';

export class EUDDashboardService {
  private static getApiBaseUrl(): string {
    return window.API_BASE_URL || 'https://api.zinrelo.com';
  }

  private static async apiRequest<T>(
    url: string,
    partnerId: string,
    accessToken?: string
  ): Promise<T> {
    const headers: Record<string, string> = {
      'partner-id': partnerId,
      Accept: 'application/json',
      'Cache-Control': 'no-cache',
      Pragma: 'no-cache'
    };

    if (accessToken) {
      headers['access-token'] = accessToken;
    }

    const response = await fetch(url, { headers });

    if (!response.ok) {
      throw new Error(`API request failed: ${response.status} ${response.statusText}`);
    }

    const text = await response.text();

    if (!text || text.trim() === '') {
      throw new Error('Empty response body from API');
    }

    try {
      const json = JSON.parse(text);
      return json;
    } catch (parseError) {
      throw new Error(`Failed to parse JSON: ${parseError.message}`);
    }
  }

  static async loadEUDSettings(params: FetchEUDSettingsParams): Promise<{
    eudSettings: EUDSettings;
    merchantConfig: MerchantConfig;
  }> {
    const {
      partnerId,
      language = 'english',
      templateId = 'zinspiration',
      themeId = 'default'
    } = params;

    return this.fetchEUDSettings({
      partnerId,
      language,
      templateId,
      themeId
    });
  }

  static async loadMemberInfo(params: FetchMemberInfoParams): Promise<MemberInfo> {
    const { partnerId, accessToken } = params;

    return this.fetchMemberInfo({ partnerId, accessToken });
  }

  static async fetchEUDSettings(params: FetchEUDSettingsParams): Promise<{
    eudSettings: EUDSettings;
    merchantConfig: MerchantConfig;
  }> {
    const {
      partnerId,
      language = 'english',
      templateId = 'zinspiration',
      themeId = 'default'
    } = params;

    const baseUrl = this.getApiBaseUrl();
    const timestamp = Date.now();
    const url = `${baseUrl}/v2/loyalty-storefront/eud-template/${templateId}/theme/${themeId}/settings?language=${language}&_t=${timestamp}`;

    const result = await this.apiRequest<EUDSettingsResponse>(url, partnerId);

    if (!result.data) {
      throw new Error('Invalid response format - missing data');
    }

    return {
      eudSettings: result.data.eud_settings || {
        theme_settings: {},
        content_settings: {},
        embed_page_url_patterns: [],
        custom_css: ''
      },
      merchantConfig: result.data.merchant_config || {}
    };
  }

  static async fetchMemberInfo(params: FetchMemberInfoParams): Promise<MemberInfo> {
    const { partnerId, accessToken } = params;

    if (!accessToken) {
      return {};
    }

    const baseUrl = this.getApiBaseUrl();
    const timestamp = Date.now();
    const url = `${baseUrl}/v2/loyalty-storefront/member?_t=${timestamp}`;

    const result = await this.apiRequest<MemberInfoResponse>(url, partnerId, accessToken);

    if (!result.data) {
      throw new Error('Invalid response format - missing data');
    }

    return result.data;
  }
}
