import { Page } from '@trueloyal-engineering/react-ui';
import { useAppNavigation } from '@root/hooks/useAppNavigation';
import { EUDSettings, MerchantConfig } from '@root/core/config';
import { usePage } from '@root/hooks';
import { replaceLabels } from '@root/core/utils/textUtils';
import { sanitizeHTML } from '@root/core/utils/htmlUtils';

export function DefaultTermsPage() {
  const {
    embed_page_url_patterns: embedURLPatterns,
    content_settings: {
      navigation_back_text: navigationBackText,
      navigation_home_text: navigationHomeText,
      program_details_program_name: programName,
      terms_label: pageTitle,
      terms_text: pageText
    }
  } = EUDSettings.getInstance();

  const termsText = replaceLabels(pageText, {
    '{{MERCHANT_REWARD_PROGRAM}}': programName,
    '{{MERCHANT_NAME}}': MerchantConfig.getInstance().name
  });

  const { back } = useAppNavigation();
  const { getBreadcrumbs } = usePage();

  const showAppBar = embedURLPatterns.length < 1;

  return (
    <Page showAppBar={showAppBar} className="terms-page">
      <Page.Header
        title={pageTitle}
        prevPageTitle={navigationHomeText}
        onBack={back}
        breadcrumbs={getBreadcrumbs()}
        backBtnLabel={navigationBackText}
      />
      <Page.Body>
        {/* eslint-disable-next-line react/no-danger */}
        <div
          className="terms-text zrl-typography_base"
          dangerouslySetInnerHTML={{ __html: sanitizeHTML(termsText) }}
        />
      </Page.Body>
    </Page>
  );
}
