import { ZinreloApi } from '@root/ZinreloApi'
import { GetAllRewardsQueryParams, GetRewardsQueryParams, RewardsDataResponse } from './types'
import { MethodArgsWithoutData } from '@root/types'

export class RewardsApi {
  private readonly apiClient: ZinreloApi

  constructor(apiClient: ZinreloApi) {
    this.apiClient = apiClient
  }

  private get url(): string {
    return `${this.apiClient.client.getApiUrl()}`
  }

  public async getRewards(input?: MethodArgsWithoutData<GetAllRewardsQueryParams>): Promise<RewardsDataResponse> {
    const endpoint = `${this.url}/rewards`

    return this.apiClient.client.execute({
      method: 'get',
      url: endpoint,
      params: input?.queryParams,
    })
  }

  public async getEligibleRewards(input?: MethodArgsWithoutData<GetRewardsQueryParams>): Promise<RewardsDataResponse> {
    const endpoint = `${this.url}/eligible-rewards`
    const params = {
      ignore_allowed_redeem_points: true,
      ...input?.queryParams,
    }
    return this.apiClient.client.execute({
      method: 'get',
      url: endpoint,
      passToken: true,
      params,
    })
  }
}
