import { Typography } from '@trueloyal-engineering/react-ui';
import { ChevronRight } from '@root/icons';
import { useAppNavigation } from '@root/hooks';
import { EUDSettings } from '@root/core/config';
import { PointsExpirationSchedule } from '@trueloyal-engineering/ui-api-sdk';
import { replaceLabels } from '@root/core/utils/textUtils';
import { LabelHelpers } from '@root/core/helpers';
import styles from './member-points-expiration-banner.module.css';

export interface MemberPointsExpirationBannerProps {
  pointsExpirationSchedule: PointsExpirationSchedule[];
  isClickable: boolean;
}

// TODO: Banner can we generic component in component library with danger, success, info variants
export function MemberPointsExpirationBanner({
  pointsExpirationSchedule,
  isClickable
}: MemberPointsExpirationBannerProps) {
  const { gotoMemberPointsExpiry } = useAppNavigation();
  const { member_profile_page_points_expiry_alert_text: pointsExpiryAlertText } =
    EUDSettings.getInstance().content_settings;

  const pointsExpiryReplaceables =
    LabelHelpers.getPointsExpirationReplaceable(pointsExpirationSchedule);

  const alertText = replaceLabels(pointsExpiryAlertText, pointsExpiryReplaceables);
  return (
    <div
      className={styles['member-points-expiration-banner']}
      onClick={isClickable ? gotoMemberPointsExpiry : undefined}
      onKeyDown={isClickable ? gotoMemberPointsExpiry : undefined}
      role="button"
      tabIndex={0}
    >
      <Typography className={styles['member-points-expiration-banner__message']} fontWeight="thin">
        {alertText}
      </Typography>
      {isClickable && (
        <ChevronRight width="24" height="24" className="zrl-icon zrl-icon--flip-on-rtl" />
      )}
    </div>
  );
}
