/* eslint-disable no-param-reassign */
import { PayloadAction, createAsyncThunk, createSlice } from '@reduxjs/toolkit';
import { ApiClient } from '@root/core/api';
import { Tier } from '@trueloyal-engineering/ui-api-sdk';
import { EUDSettings } from '@root/core/config';
import { LabelHelpers } from '@root/core/helpers';
import { CommonThunkError, CommonState } from '../types';

export interface TierState extends CommonState {
  tiers: Tier[] | undefined;
}

export const fetchAllTiers = createAsyncThunk<
  Tier[] | undefined,
  void,
  { rejectValue: CommonThunkError }
>('tier/fetchAllTiers', async (_, { rejectWithValue }) => {
  try {
    const apiClient = ApiClient.getInstance();
    const response = await apiClient.tiers.getTiers();
    if (!response.success) {
      return rejectWithValue({
        errorMessage: EUDSettings.getInstance().content_settings.tier_section_error_state_message
      });
    }
    return LabelHelpers.replaceVariables(response.data.tiers, 'tier') as Tier[];
  } catch (error) {
    return rejectWithValue({
      errorMessage: EUDSettings.getInstance().content_settings.tier_section_error_state_message
    });
  }
});

const initialState: TierState = {
  tiers: undefined,
  status: 'idle',
  errorMessage: ''
};

export const tierSlice = createSlice({
  name: 'tier',
  initialState,
  reducers: {
    setTiers: (state, action: PayloadAction<Tier[]>) => {
      state.tiers = action.payload;
    }
  },
  extraReducers: (builder) => {
    builder.addCase(fetchAllTiers.fulfilled, (state, action) => {
      state.status = 'succeeded';
      state.tiers = action.payload as Tier[];
    });
    builder.addCase(fetchAllTiers.rejected, (state, action) => {
      state.status = 'failed';
      state.errorMessage = action.payload?.errorMessage ?? 'Unknown Error';
    });
    builder.addCase(fetchAllTiers.pending, (state, _) => {
      state.status = 'pending';
    });
  }
});

// Action creators are generated for each case reducer function
export const { setTiers } = tierSlice.actions;

export default tierSlice.reducer;
