import { ActivityHelper } from '@root/core/helpers';
import { ErrorHandler } from '@root/core/helpers/error';
import { UIHelpers } from '@root/core/helpers/ui';
import { ShareNetwork } from '@root/core/types';
import { useAppSelector } from '@root/store';
import { Activity } from '@trueloyal-engineering/ui-api-sdk';
import { useState } from 'react';
import { toast } from 'react-toastify';

export interface UseReferralActivityProps {
  activity: Activity;
}

export function useReferralActivity({ activity }: UseReferralActivityProps) {
  const [loading, setLoading] = useState(false);
  const [showCongratulation, setShowCongratulation] = useState(false);

  const referralURL = useAppSelector((state) => state.member.memberDetails?.referral_URL);

  const referViaEmail = async (emails: string) => {
    try {
      setLoading(true);
      const response = await ActivityHelper.performReferral('mail', emails);
      if (response.success) {
        setShowCongratulation(true);
      }
    } catch (error) {
      const errorMessage = ErrorHandler.resolveActivityErrorMessage(activity, error);
      toast.error(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  const onPopupClose = async (shareNetwork: ShareNetwork) => {
    try {
      setLoading(true);
      const response = await ActivityHelper.performReferral(shareNetwork, '');
      if (response.success) {
        setShowCongratulation(true);
      }
    } catch (error) {
      const errorMessage = ErrorHandler.resolveActivityErrorMessage(activity, error);
      toast.error(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  const referViaSocials = async (shareNetwork: ShareNetwork) => {
    if (!referralURL) {
      return;
    }
    try {
      setLoading(true);
      const shareURL = ActivityHelper.getShareURLForReferral(
        shareNetwork,
        referralURL,
        activity?.extra_config ?? {}
      );

      UIHelpers.openPopup(
        shareURL,
        'share-dialog',
        'width=800,height=600',
        onPopupClose.bind(null, shareNetwork)
      );
    } catch (error) {
      const errorMessage = ErrorHandler.resolveActivityErrorMessage(activity, error);
      toast.error(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  return {
    referralURL,
    referViaSocials,
    referViaEmail,
    loading,
    showCongratulation
  };
}
