import {
  AnniversaryActivity,
  BirthdayActivity,
  EnterCodeActivity,
  GenericActivity,
  InstagramFollowActivity,
  ReferralActivity,
  SocialShareActivity,
  GatsbySocialShareActivity,
  SubmitReceiptActivity,
  EnterHandleActivity,
  UploadPhotoActivity,
  FormActivity,
  DateActivity
} from '@root/containers';
import { EUDSettings } from '@root/core/config';
import { ACTIVITY_IDS } from '@root/core/constants/activity.constants';
import { useAppNavigation, usePage } from '@root/hooks';
import { ACTIVITIES_BASE_PATH, MEMBER_BASE_PATH } from '@root/router/paths';
import { useAppSelector } from '@root/store';
import { selectActivity } from '@root/store/slices/activitySlice';
import { Button, Page } from '@trueloyal-engineering/react-ui';
import { Navigate, useParams } from 'react-router-dom';

export function DefaultActivityDetailsPage() {
  const { id } = useParams();
  const activity = useAppSelector((state) => selectActivity(state, id));
  const {
    embed_page_url_patterns: embedURLPatterns,
    content_settings: {
      navigation_home_text: navigationHomeText,
      navigation_back_text: navigationBackText
    }
  } = EUDSettings.getInstance();

  const { back } = useAppNavigation();
  const { getBreadcrumbs } = usePage();

  if (!activity) {
    // if selected activity not present redirect to activities listing page
    return <Navigate to={`${MEMBER_BASE_PATH}/${ACTIVITIES_BASE_PATH}`} replace />;
  }

  const renderActivity = () => {
    if (activity.activity_id.endsWith('form_activity')) {
      return <FormActivity activity={activity} />;
    }
    if (activity.activity_id.endsWith('date_activity')) {
      return <DateActivity activity={activity} />;
    }

    switch (activity.activity_id) {
      case ACTIVITY_IDS.ZRL_BIRTHDAY_BONUS:
        return <BirthdayActivity activity={activity} />;
      case ACTIVITY_IDS.ZRL_ANNIVERSARY_BONUS:
        return <AnniversaryActivity activity={activity} />;
      case ACTIVITY_IDS.ZRL_SHARE_ON_FACEBOOK:
      case ACTIVITY_IDS.ZRL_SHARE_ON_INSTAGRAM:
      case ACTIVITY_IDS.ZRL_SHARE_ON_PINTEREST:
      case ACTIVITY_IDS.ZRL_SHARE_ON_TWITTER:
        return <SocialShareActivity activity={activity} />;
      case ACTIVITY_IDS.ZRL_MENTION_ON_INSTAGRAM_POST:
      case ACTIVITY_IDS.ZRL_MENTION_ON_INSTAGRAM_STORY:
      case ACTIVITY_IDS.ZRL_MENTION_ON_INSTAGRAM_REEL:
      case ACTIVITY_IDS.ZRL_TAG_ON_INSTAGRAM_POST:
      case ACTIVITY_IDS.ZRL_TAG_ON_INSTAGRAM_REEL:
      case ACTIVITY_IDS.ZRL_TAG_ON_TIKTOK:
      case ACTIVITY_IDS.ZRL_FOLLOW_ON_INSTAGRAM_V2:
      case ACTIVITY_IDS.ZRL_DM_ON_INSTAGRAM:
        return <GatsbySocialShareActivity activity={activity} />;
      case ACTIVITY_IDS.ZRL_CODE_SUBMISSION_ACTIVITY:
        return <EnterCodeActivity activity={activity} />;
      case ACTIVITY_IDS.ZRL_REFERRAL_ACTIVITY:
        return <ReferralActivity activity={activity} />;
      case ACTIVITY_IDS.ZRL_UPLOAD_PHOTO_ACTIVITY_ID:
        return <UploadPhotoActivity activity={activity} />;
      case ACTIVITY_IDS.ZRL_SUBMIT_RECEIPT:
        return <SubmitReceiptActivity activity={activity} />;
      case ACTIVITY_IDS.ZRL_FOLLOW_ON_INSTAGRAM:
        return <InstagramFollowActivity activity={activity} />;
      case ACTIVITY_IDS.ZRL_ENTER_INSTAGRAM_HANDLE:
      case ACTIVITY_IDS.ZRL_ENTER_TIKTOK_HANDLE:
        return <EnterHandleActivity activity={activity} />;
      default:
        return <GenericActivity activity={activity} />;
    }
  };

  const showAppBar = embedURLPatterns.length < 1;
  const breadcrumbs = [
    ...getBreadcrumbs(),
    <Button mono disabled>
      {activity.activity_name}
    </Button>
  ];

  return (
    <Page showAppBar={showAppBar} className="activity-details-page">
      <Page.Header
        prevPageTitle={navigationHomeText}
        onBack={back}
        title={activity.activity_name}
        backBtnLabel={navigationBackText}
        breadcrumbs={breadcrumbs}
      />
      <Page.Body data-activity_id={activity.activity_id}>{renderActivity()}</Page.Body>
    </Page>
  );
}
