/* eslint-disable no-param-reassign */
import { createAsyncThunk, createSlice, PayloadAction } from '@reduxjs/toolkit';
import { fetchData } from '@root/store/slices/mockApi/perkLog.api';
import { EUDSettings } from '@root/core/config';
import { RootState } from '@root/store';
import { CommonThunkError, CommonState } from '../types';
import { ListQueryParams } from './types';

export interface PerkLog {
  id: string;
  reward_id: string;
  coupon_code: string;
  reward_log_status: string;
  linked_schema_record_id: string;
  linked_schema_slug: string;
  created_at: string;
}

type ApiResponse<T> = {
  data: T;
};

export interface PerkLogState extends CommonState {
  perkLogs: Record<string, PerkLog[]> | undefined;
}

const initialState: PerkLogState = {
  perkLogs: undefined,
  status: 'idle',
  errorMessage: ''
};

export const fetchPerkLogs = createAsyncThunk<
  Record<string, Array<PerkLog>> | undefined,
  ListQueryParams,
  { rejectValue: CommonThunkError }
>('perkLogs/fetch', async (queryParams, { rejectWithValue }) => {
  try {
    const response = await fetchData<ApiResponse<PerkLog[]>>(queryParams);
    const rewardPerkLogMapping: Record<string, Array<PerkLog>> = {};
    const perkLogs = response?.data ?? [];
    perkLogs.forEach((perkLog) => {
      if (rewardPerkLogMapping[perkLog.reward_id]) {
        rewardPerkLogMapping[perkLog.reward_id].push(perkLog);
      } else {
        rewardPerkLogMapping[perkLog.reward_id] = [perkLog];
      }
    });
    return rewardPerkLogMapping;
  } catch (error) {
    return rejectWithValue({
      errorMessage: EUDSettings.getInstance().content_settings.streak_section_error_state_message
    });
  }
});

export const perkLogSlice = createSlice({
  name: 'perk',
  initialState,
  reducers: {
    setPerkLog(state, action: PayloadAction<PerkLog>) {
      const perkLog = action.payload;
      const perkId = perkLog.reward_id;
      if (!state.perkLogs) {
        state.perkLogs = {};
      }
      if (!state.perkLogs[perkId]) {
        state.perkLogs[perkId] = [];
      }
      // Check if it already exists and replace or append
      const existingIndex = state.perkLogs[perkId].findIndex((log) => log.id === perkLog.id);
      if (existingIndex >= 0) {
        state.perkLogs[perkId][existingIndex] = perkLog;
      } else {
        state.perkLogs[perkId].push(perkLog);
      }
    }
  },
  extraReducers: (builder) => {
    builder.addCase(fetchPerkLogs.fulfilled, (state, action) => {
      state.perkLogs = {
        ...state.perkLogs,
        ...action.payload
      };
      state.status = 'succeeded';
    });
    builder.addCase(fetchPerkLogs.rejected, (state) => {
      state.status = 'failed';
    });
    builder.addCase(fetchPerkLogs.pending, (state) => {
      state.status = 'pending';
    });
  }
});

export const { setPerkLog } = perkLogSlice.actions;

export const selectPerkLogs = (state: RootState, perkId: string | undefined) => {
  if (!perkId) return null;
  const perkLogs: PerkLog[] | undefined = state.perkLogs.perkLogs?.[perkId];
  return perkLogs;
};

export const selectPerkLog = (
  state: RootState,
  perkId: string | undefined,
  perkLogId: string | undefined
) => {
  if (!perkLogId || !perkId) return null;
  const perkLogs: PerkLog[] | undefined = state.perkLogs.perkLogs?.[perkId];
  const filteredPerkLogs = perkLogs?.filter((perkLog: PerkLog) => perkLog.id === perkLogId);
  if (filteredPerkLogs) {
    return filteredPerkLogs[0];
  }
  return null;
};

export default perkLogSlice.reducer;
