import React from 'react';
import { PopoverCommonProps } from '../../types';

export interface PopoverTriggerProps extends PopoverCommonProps {
  children: React.ReactElement;
}

export function PopoverTrigger({ children, _state, _triggerRef }: PopoverTriggerProps) {
  if (!_triggerRef || !_state) {
    return null;
  }
  const togglePopover = () => _state.toggle();
  return React.cloneElement(children as React.ReactElement, {
    ref: _triggerRef,
    onClick: togglePopover
  });
}
