import { ImageCarousel } from '@trueloyal-engineering/react-ui';
import { ImageWithPlaceholder } from '@root/components';
import styles from './view-image.module.css';

export interface ViewImageProps {
  imageUrl: string | string[];
}

export function ViewImage({ imageUrl }: ViewImageProps) {
  const renderMedia = (url: string, containerStyle: string) => {
    return (
      <div className={styles[containerStyle]}>
        {url.endsWith('.pdf') ? (
          <iframe title="PDF Viewer " src={url} className={styles['view-image__iframe']} />
        ) : (
          <ImageWithPlaceholder src={url} />
        )}
      </div>
    );
  };

  const shouldRenderSingleImage =
    typeof imageUrl === 'string' || (Array.isArray(imageUrl) && imageUrl.length === 1);

  if (shouldRenderSingleImage) {
    const url = Array.isArray(imageUrl) ? imageUrl[0] : imageUrl;
    return renderMedia(url, 'view-image__container');
  }

  return (
    <ImageCarousel>
      <ImageCarousel.Header />
      <ImageCarousel.Slides>
        {imageUrl.map((url) => (
          <div key={url}>{renderMedia(url, 'view-image-slides__container')}</div>
        ))}
      </ImageCarousel.Slides>
    </ImageCarousel>
  );
}
