import { useAppSelector } from '@root/store';
import { useEffect } from 'react';

export interface UseHandleReduxError {
  errorHandler: (errorMessage: string) => void;
}

export function useHandleReduxErrors({ errorHandler }: UseHandleReduxError) {
  const activityErrorMessage = useAppSelector((state) => state.activity.errorMessage);
  const rewardErrorMessage = useAppSelector((state) => state.reward.errorMessage);
  const memberErrorMessage = useAppSelector((state) => state.member.errorMessage);
  const tierErrorMessage = useAppSelector((state) => state.activity.errorMessage);
  const transactionErrorMessage = useAppSelector((state) => state.transaction.errorMessage);

  useEffect(() => {
    if (activityErrorMessage) {
      errorHandler(activityErrorMessage);
    }
  }, [activityErrorMessage]);

  useEffect(() => {
    if (rewardErrorMessage) {
      errorHandler(rewardErrorMessage);
    }
  }, [rewardErrorMessage]);

  useEffect(() => {
    if (memberErrorMessage) {
      errorHandler(memberErrorMessage);
    }
  }, [memberErrorMessage]);

  useEffect(() => {
    if (tierErrorMessage) {
      errorHandler(tierErrorMessage);
    }
  }, [tierErrorMessage]);

  useEffect(() => {
    if (transactionErrorMessage) {
      errorHandler(transactionErrorMessage);
    }
  }, [transactionErrorMessage]);
}
