/* eslint-disable no-param-reassign */
import { PayloadAction, createAsyncThunk, createSlice, isAnyOf } from '@reduxjs/toolkit';
import { ApiClient } from '@root/core/api';
import { RootState } from '@root/store';
import { Activity, GetActivitiesQueryParams } from '@trueloyal-engineering/ui-api-sdk';
import { CommonState, CommonThunkError } from '@root/store/types';
import { EUDSettings } from '@root/core/config';
import { LabelHelpers } from '@root/core/helpers';

export interface ActivityState extends CommonState {
  activities: Activity[] | undefined;
  eligibleActivities: Activity[] | undefined;
}

export const fetchAllActivities = createAsyncThunk<
  Activity[] | undefined,
  GetActivitiesQueryParams,
  { rejectValue: CommonThunkError }
>('activity/fetchAllActivities', async (queryParams, { rejectWithValue }) => {
  try {
    const apiClient = ApiClient.getInstance();
    const input = {
      queryParams
    };
    const response = await apiClient.activities.getActivities(input);
    if (!response.success) {
      return rejectWithValue({
        errorMessage:
          EUDSettings.getInstance().content_settings.activity_section_error_state_message
      });
    }
    const activities = LabelHelpers.replaceVariables(
      response.data.activities,
      'activity'
    ) as Activity[];
    return activities;
  } catch (error) {
    return rejectWithValue({
      errorMessage: EUDSettings.getInstance().content_settings.activity_section_error_state_message
    });
  }
});

export const fetchEligibleActivities = createAsyncThunk<
  Activity[] | undefined,
  GetActivitiesQueryParams,
  { rejectValue: CommonThunkError }
>('activity/fetchEligibleActivities', async (queryParams, { rejectWithValue }) => {
  try {
    const apiClient = ApiClient.getInstance();
    const input = {
      queryParams
    };
    const response = await apiClient.activities.getEligibleActivities(input);
    if (!response.success) {
      return rejectWithValue({
        errorMessage:
          EUDSettings.getInstance().content_settings.activity_section_error_state_message
      });
    }
    const activities = LabelHelpers.replaceVariables(
      response.data.activities,
      'activity'
    ) as Activity[];
    return activities;
  } catch (error) {
    return rejectWithValue({
      errorMessage: EUDSettings.getInstance().content_settings.activity_section_error_state_message
    });
  }
});

const initialState: ActivityState = {
  activities: undefined,
  eligibleActivities: undefined,
  status: 'idle',
  errorMessage: ''
};

export const activitySlice = createSlice({
  name: 'activity',
  initialState,
  reducers: {
    setActivities: (state, action: PayloadAction<Activity[]>) => {
      state.activities = action.payload;
    }
  },
  extraReducers: (builder) => {
    builder.addCase(fetchAllActivities.fulfilled, (state, action) => {
      state.status = 'succeeded';
      state.activities = action.payload as Activity[];
    });
    builder.addCase(fetchEligibleActivities.fulfilled, (state, action) => {
      state.status = 'succeeded';
      state.eligibleActivities = action.payload as Activity[];
    });
    builder.addMatcher(
      isAnyOf(fetchAllActivities.pending, fetchEligibleActivities.pending),
      (state, _) => {
        state.status = 'pending';
      }
    );
    builder.addMatcher(
      isAnyOf(fetchAllActivities.rejected, fetchEligibleActivities.rejected),
      (state, action) => {
        state.status = 'failed';
        state.errorMessage = action.payload?.errorMessage ?? 'Unknown Error';
      }
    );
  }
});

// Action creators are generated for each case reducer function
export const { setActivities } = activitySlice.actions;

export const selectActivities = (
  state: RootState,
  from: string | undefined
): Activity[] | undefined => {
  switch (from) {
    case 'guest':
      return state.activity.activities;
    case 'member':
      return state.activity.eligibleActivities;
    default:
      return [];
  }
};

export const selectActivity = (state: RootState, activityId: string | undefined) => {
  if (!activityId) return null;
  const filteredActivities = state.activity.eligibleActivities?.filter(
    (activity) => activity.activity_id === activityId
  );
  if (filteredActivities) {
    return filteredActivities[0];
  }
  return null;
};

export default activitySlice.reducer;
