import { ActivityHeader, DatePicker, LoadMask, Select } from '@root/components';
import { Button, Stack, Layout } from '@trueloyal-engineering/react-ui';
import { Activity } from '@trueloyal-engineering/ui-api-sdk';
import { AuthConfig, EUDSettings } from '@root/core/config';
import { useDateActivity } from '@root/hooks';
import { MONTH_OPTIONS } from '@root/core/constants/activity.constants';
import styles from './anniversary-activity.module.css';

export interface AnniversaryActivityProps {
  activity: Activity;
}

export function AnniversaryActivity({ activity }: AnniversaryActivityProps) {
  const { input_date_format: inputDateFormat } = EUDSettings.getInstance();
  const {
    enduser_activity_short_description: shortDescription,
    extra_config: extraConfig,
    earnpoints_button_label: tagLabel
  } = activity;

  const {
    loading,
    isActivityCompleted,
    date: anniversary,
    setDate: setAnniversary,
    addDate: addAnniversary,
    onMonthChange,
    onDayChange,
    getDaysOptions,
    month,
    day
  } = useDateActivity({
    dateFormat: inputDateFormat,
    eligibleFieldKey: 'anniversary_date',
    activity
  });

  const instructionText = extraConfig?.reward_text;
  const saveButtonText = extraConfig?.save_button_text;
  const thankYouText = extraConfig?.thank_you_text;

  // FIXME: Disable user action when previewing
  // Ideally we should handle this using mock apis and return success response
  const isPreview = AuthConfig.isPreview();
  const isYearRequired = extraConfig?.is_year_required;

  const isSaveDisabled = isYearRequired ? !anniversary : !month || !day;

  return (
    <Layout className="anniversary-activity">
      {loading && <LoadMask />}
      <Layout.Content>
        <Stack>
          <ActivityHeader
            tagLabel={tagLabel}
            title={shortDescription}
            description={isActivityCompleted ? thankYouText : instructionText}
          />
          {isYearRequired ? (
            <DatePicker
              placeholder="mm/dd/yyyy"
              value={anniversary}
              onChange={setAnniversary}
              className={styles['anniversary-activity__date-picker']}
              disabled={isActivityCompleted}
            />
          ) : (
            <Stack orientation="horizontal" gap={1}>
              <Select
                className={styles['anniversary-activity__month-picker']}
                options={MONTH_OPTIONS}
                placeholder="month"
                ariaLabel="Anniversary month"
                onOptionChange={onMonthChange}
                selectedOption={month}
                disabled={isActivityCompleted}
              />
              <Select
                className={styles['anniversary-activity__day-picker']}
                options={getDaysOptions()}
                selectedOption={day}
                placeholder="day"
                ariaLabel="Anniversary day"
                onOptionChange={onDayChange}
                disabled={isActivityCompleted || !month}
              />
            </Stack>
          )}
        </Stack>
      </Layout.Content>
      <Layout.Footer>
        {!isActivityCompleted && (
          <Button
            id="add-anniversary-btn"
            fullWidthOnDeviceType="sm"
            primary
            onClick={!isPreview ? addAnniversary : undefined}
            btnSize="large"
            disabled={isSaveDisabled}
          >
            {saveButtonText}
          </Button>
        )}
      </Layout.Footer>
    </Layout>
  );
}
