import { ApiClientType, ZinreloApi } from '@trueloyal-engineering/ui-api-sdk';

export class ApiClient {
  private static instance: ZinreloApi;

  private constructor() {
    // Private constructor to prevent instantiation.
  }

  public static initialize(clientConfig: ApiClientType): void {
    ApiClient.instance = new ZinreloApi({ ...clientConfig });
  }

  public static getInstance(): ZinreloApi {
    if (!ApiClient.instance) {
      throw new Error('ApiClient has not been initialized. Call initialize first.');
    }

    return ApiClient.instance;
  }
}
