import { EUDSettings } from '@root/core/config';
import { ACTIVITY_IDS } from '@root/core/constants/activity.constants';
import { formatNumber, pluralize } from '@root/core/utils/textUtils';
import { useAppNavigation } from '@root/hooks';
import { useAppSelector } from '@root/store';
import { Button, Stack, Tag, Typography } from '@trueloyal-engineering/react-ui';
import Skeleton from 'react-loading-skeleton';

export function SignUpSection() {
  const { openURL } = useAppNavigation();

  const { activities, status } = useAppSelector((state) => state.activity);
  const loading = ['pending', 'idle'].includes(status);
  if (loading) {
    return (
      <div>
        <Skeleton count={3} />
      </div>
    );
  }

  const {
    program_details_currency_plural_text: currencyPlural,
    program_details_currency_singular_text: currencySingular,
    auth_section_signup_button_label: signUpButtonLabel,
    auth_section_login_link_label: logInLinkText,
    auth_section_log_in_message: logInMessage,
    auth_section_sign_up_message: signUpMessage,
    auth_section_login_url: loginURL,
    auth_section_signup_url: signUpURL
  } = EUDSettings.getInstance().content_settings;

  const currency = {
    plural: currencyPlural,
    singular: currencySingular
  };

  const signUpBonus =
    activities &&
    activities.find(
      (activity) =>
        activity.activity_id === ACTIVITY_IDS.ZRL_CREATED_AN_ACCOUNT &&
        activity.points_config.points
    )?.points_config.points;

  // TODO: Find Better way of doing this
  const signUpMessageJSX =
    signUpBonus &&
    signUpMessage.split('{{WELCOME_POINTS_TAG}}').map((text, index) => {
      if (index === 1) {
        return [
          <Tag
            label={`${formatNumber(signUpBonus)} ${pluralize(
              signUpBonus,
              currency.singular,
              currency.plural
            )}`}
            primary
          />,
          text
        ];
      }
      return text;
    });

  return (
    <Stack align="center" className="signup-section">
      {signUpBonus && (
        <Typography titled fontWeight="thin">
          {signUpMessageJSX}
        </Typography>
      )}
      <Button
        id="signup-btn"
        fullWidthOnDeviceType="sm"
        primary
        onClick={() => openURL(signUpURL)}
        relaxed
      >
        {signUpButtonLabel}
      </Button>
      <Typography align="center" as="h6" fontWeight="thin" muted>
        {logInMessage}{' '}
        <Button link onClick={() => openURL(loginURL)} id="login-btn">
          {logInLinkText}
        </Button>
      </Typography>
    </Stack>
  );
}
