import {
  ActivityExtraConfig,
  ActivityTypes,
  GetTrackingCodeActivities,
  MethodArgsWithoutQueryParams,
  PerformActivityInputData,
  PointsConfig
} from '@trueloyal-engineering/ui-api-sdk';
import { ApiClient } from '../api';
import { ShareNetwork } from '../types';
import { MerchantConfig } from '../config';

export class ActivityHelper {
  public static getActivityPoints(pointsConfig: PointsConfig) {
    return pointsConfig.points_computation_type === 'multiplier_based'
      ? pointsConfig.multiplier
      : pointsConfig.points;
  }

  public static async performUploadPhotoActivity(file: File) {
    try {
      const { members, utils } = ApiClient.getInstance();
      const fileBase64 = await utils.readFileAsBase64(file);

      const input: MethodArgsWithoutQueryParams<PerformActivityInputData> = {
        data: {
          activity_id: 'upload_photo',
          transaction_attributes: {
            image_file: fileBase64
          }
        }
      };
      const response = await members.performActivity(input);
      return response;
    } catch (error) {
      // eslint-disable-next-line no-console
      console.error(error);
      throw error;
    }
  }

  public static async performSubmitReceiptActivity(files: File[]) {
    try {
      const { members, utils } = ApiClient.getInstance();
      const filesBase64Promises = [];
      // eslint-disable-next-line no-plusplus
      for (let index = 0; index < files.length; index++) {
        filesBase64Promises.push(utils.readFileAsBase64(files[index]));
      }
      const filesBase64 = await Promise.all(filesBase64Promises);
      const input: MethodArgsWithoutQueryParams<PerformActivityInputData> = {
        data: {
          activity_id: 'submit_a_receipt',
          transaction_attributes: {
            receipt_files: filesBase64
          }
        }
      };
      const response = await members.performActivity(input);
      return response;
    } catch (error) {
      // eslint-disable-next-line no-console
      console.error(error);
      throw error;
    }
  }

  public static async performSocialShare(activityId: ActivityTypes, trackCode: string) {
    try {
      const { members } = ApiClient.getInstance();

      const input: MethodArgsWithoutQueryParams<PerformActivityInputData> = {
        data: {
          activity_id: activityId,
          transaction_attributes: {
            track_code: trackCode
          }
        }
      };
      const response = await members.performActivity(input);
      return response;
    } catch (error) {
      // eslint-disable-next-line no-console
      console.error(error);
      throw error;
    }
  }

  public static async performCodeSubmission(code: string) {
    try {
      const { members } = ApiClient.getInstance();

      const input: MethodArgsWithoutQueryParams<PerformActivityInputData> = {
        data: {
          activity_id: 'code_submission',
          transaction_attributes: {
            code: code.trim()
          }
        }
      };
      const response = await members.performActivity(input);
      return response;
    } catch (error) {
      // eslint-disable-next-line no-console
      console.error(error);
      throw error;
    }
  }

  public static async performFollowInstagram() {
    try {
      const { members } = ApiClient.getInstance();

      const input: MethodArgsWithoutQueryParams<PerformActivityInputData> = {
        data: {
          activity_id: 'follow_on_instagram'
        }
      };
      const response = await members.performActivity(input);
      return response;
    } catch (error) {
      // eslint-disable-next-line no-console
      console.error(error);
      throw error;
    }
  }

  public static async performReferral(shareNetwork: string, emails: string) {
    try {
      const { members } = ApiClient.getInstance();

      const input: MethodArgsWithoutQueryParams<PerformActivityInputData> = {
        data: {
          activity_id: 'referral',
          transaction_attributes: {
            share_network: shareNetwork,
            to_addresses: emails.split(',').map((email) => email.trim())
          }
        }
      };
      const response = await members.performActivity(input);
      return response;
    } catch (error) {
      // eslint-disable-next-line no-console
      console.error(error);
      throw error;
    }
  }

  public static async getShareDetails(
    activityId: GetTrackingCodeActivities,
    extraConfig: ActivityExtraConfig | undefined
  ) {
    try {
      const { activities, utils } = ApiClient.getInstance();
      const response = await activities.getActivityTrackCode({
        queryParams: {
          activity_id: activityId
        }
      });
      const trackCode = response.data.track_code;

      const baseURL =
        extraConfig?.share_current_page_url && window.currentPageUrl
          ? window.currentPageUrl
          : MerchantConfig.getInstance().webURL;

      const shareURL = utils.getShareUrl({
        activity_id: activityId,
        track_code: trackCode,
        base_share_url: baseURL,
        extra_config: extraConfig
      });
      return [shareURL, trackCode];
    } catch (error) {
      // eslint-disable-next-line no-console
      console.error(error);
      throw error;
    }
  }

  public static getShareURLForReferral(
    shareNetwork: ShareNetwork,
    shareURL: string,
    activityExtraConfig: ActivityExtraConfig
  ) {
    const { utils } = ApiClient.getInstance();
    return utils.getShareURLForReferral({
      shareNetwork,
      shareURL,
      extraConfig: activityExtraConfig
    });
  }

  public static getInstagramProfileURL(instagramHandle: string) {
    const { utils } = ApiClient.getInstance();
    return utils.getInstagramProfileURL(instagramHandle);
  }
}
