import { CSSProperties, ImgHTMLAttributes, useState } from 'react';
import { classNames } from '@trueloyal-engineering/react-ui';
import { LoadMask } from '@root/components';
import styles from './image-with-placeholder.module.css';

export interface ImageWithPlaceholderProps extends ImgHTMLAttributes<HTMLImageElement> {
  src: string;
}

export function ImageWithPlaceholder({
  src,
  className,
  style,
  ...props
}: ImageWithPlaceholderProps) {
  const isHeicImageUrl = (imageUrl: string) => {
    return (
      imageUrl.endsWith('.heic') ||
      imageUrl.endsWith('.HEIC') ||
      imageUrl.endsWith('.heif') ||
      imageUrl.endsWith('.HEIF')
    );
  };
  const heicImageUrl = isHeicImageUrl(src);
  const [loaded, setLoaded] = useState(heicImageUrl);
  const classes = classNames(styles['image-with-placeholder__img'], className);
  const inlineStyles: CSSProperties = {
    ...style,
    display: !loaded ? 'none' : style?.display
  };

  const handleImageLoaded = () => {
    setLoaded(true);
  };

  return (
    <>
      {!loaded && <LoadMask />}
      {heicImageUrl ? (
        <p>Generating preview, please retry after some time.</p>
      ) : (
        <img
          {...props}
          src={src}
          alt="slide"
          className={classes}
          style={inlineStyles}
          onLoad={handleImageLoaded}
        />
      )}
    </>
  );
}
