import React from 'react';
import { createRoot } from 'react-dom/client';
import { Provider } from 'react-redux';
import indexCssString from '@root/index.css?raw';
import { AppRouter } from '../src/router';
import { OverlayContainerContext } from '../src/components/OverlayContainer';
import { createStore } from '../src/store';
import { initApp } from '../src/initApp';
import { EUDDashboardService } from '../src/core/api/eud-dashboard.service';
import { getTintUrls } from '../src/core/helpers/tint';
import { injectFonts, applyThemeStyles } from './utils/themeUtils';
import { STYLE_ATTRIBUTES } from './constants/styleConstants';
import {
  getMountContainer,
  convertMediaToContainer,
  convertViewportWidthToContainer
} from './utils/mountContainer';

import 'react-toastify/dist/ReactToastify.css';

export interface DashboardConfig {
  element: HTMLElement | ShadowRoot;
  accessToken: string;
  partnerId?: string;
  version: string;
  language: string;
  templateId?: string;
  themeId?: string;
}

const showError = (element: HTMLElement | ShadowRoot, message: string, details?: string) => {
  const isShadowRoot = element instanceof ShadowRoot;
  const shadowRoot = isShadowRoot ? element : undefined;

  if (shadowRoot) {
    const loader = shadowRoot.querySelector(`[${STYLE_ATTRIBUTES.LOADER}]`);
    if (loader) {
      loader.remove();
    }
  }

  const errorHtml = `
    <div style="
      padding: 2rem;
      text-align: center;
      color: #dc3545;
      background: #f8d7da;
      border: 1px solid #f5c6cb;
      border-radius: 4px;
      margin: 1rem;
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    ">
      <strong>Error:</strong> ${message}
      ${
        details
          ? `<div style="margin-top: 0.5rem; font-size: 0.875rem; opacity: 0.8;">${details}</div>`
          : ''
      }
    </div>
  `;

  const container =
    element instanceof ShadowRoot
      ? element.querySelector(`[${STYLE_ATTRIBUTES.DASHBOARD_ROOT}]`)
      : element;

  if (container) {
    container.innerHTML = errorHtml;
  }
};

export const renderDashboard = async (config: DashboardConfig) => {
  const { element } = config;

  if (!element) {
    return;
  }

  const [eudSettingsResult, memberInfoResult] = await Promise.allSettled([
    EUDDashboardService.loadEUDSettings({
      partnerId: config.partnerId,
      language: config.language,
      templateId: config.templateId,
      themeId: config.themeId
    }),
    EUDDashboardService.loadMemberInfo({
      partnerId: config.partnerId,
      accessToken: config.accessToken
    })
  ]);

  if (eudSettingsResult.status === 'rejected') {
    const error = eudSettingsResult.reason;
    const errorMessage = error?.message || 'Failed to load dashboard settings';
    const statusCode = error?.response?.status;
    const details = statusCode ? `HTTP ${statusCode}` : undefined;

    showError(element, errorMessage, details);
    return;
  }

  const { eudSettings, merchantConfig } = eudSettingsResult.value;
  const memberInfo = memberInfoResult.status === 'fulfilled' ? memberInfoResult.value : {};

  const container = getMountContainer(element, indexCssString, eudSettings.custom_css);

  const isShadowRoot = element instanceof ShadowRoot;
  const shadowRoot = isShadowRoot ? element : undefined;
  const styleHost = isShadowRoot ? ((element as ShadowRoot).host as HTMLElement) : undefined;

  if (styleHost) {
    styleHost.setAttribute(STYLE_ATTRIBUTES.PARTNER_ID, config.partnerId);
  }

  injectFonts(eudSettings, shadowRoot, config.partnerId);
  applyThemeStyles(eudSettings, styleHost);

  if (merchantConfig.tintTeamId) {
    // eslint-disable-next-line no-underscore-dangle
    if (!(window as any)._env_ || typeof (window as any)._env_ !== 'object') {
      // eslint-disable-next-line no-underscore-dangle
      (window as any)._env_ = {};
    }

    // eslint-disable-next-line no-underscore-dangle
    const env = (window as any)._env_;
    const tintUrls = getTintUrls(merchantConfig);
    if (!env.BASE_URL) {
      env.BASE_URL = tintUrls.appUrl;
    }
    if (!env.API_URL) {
      env.API_URL = tintUrls.apiUrl;
    }

    // Don't load tint.js if eud-wrapper already loaded it
    if (!(window as any).TrueLoyal?.eudWrapperLoaded) {
      const tintJsUrl = tintUrls.jsUrl;
      const existingScript = document.querySelector(`script[src="${tintJsUrl}"]`);

      if (!existingScript) {
        const script = document.createElement('script');
        script.src = tintJsUrl;
        script.async = true;
        document.head.appendChild(script);
      }
    }
  }

  initApp({
    apiBaseURL: window.API_BASE_URL,
    partnerId: config.partnerId,
    accessToken: config.accessToken,
    language: config.language,
    isPreview: window.isPreview,
    eudSettings,
    merchantConfig,
    memberInfo,
    integrationSettings: window.integrationSettings
  });

  const componentStore = createStore(memberInfo);

  const root = createRoot(container);

  root.render(
    <Provider store={componentStore}>
      <OverlayContainerContext.Provider value={container}>
        <AppRouter />
      </OverlayContainerContext.Provider>
    </Provider>
  );

  if (shadowRoot) {
    document.fonts.ready.then(() => {
      const loader = shadowRoot.querySelector(`[${STYLE_ATTRIBUTES.LOADER}]`);
      if (loader) {
        loader.remove();
      }
    });

    setTimeout(() => {
      // Convert @media to @container in shadow root
      convertMediaToContainer(shadowRoot);
      convertViewportWidthToContainer(shadowRoot);
      // Also convert in document.head for styles injected by webpack
      convertMediaToContainer(document);
    }, 100);
  }
};
