import { Button, Stack } from '@trueloyal-engineering/react-ui';
import { TransactionFilter, TransactionFiltersConfig } from '../../types';
import styles from './transaction-filters.module.css';

export interface TransactionFiltersProps {
  filters: TransactionFiltersConfig;
  onFilterChange: (value: TransactionFilter) => void;
  selectedFilterValue: string;
}

export function TransactionFilters({
  filters,
  onFilterChange,
  selectedFilterValue
}: TransactionFiltersProps) {
  return (
    <Stack orientation="horizontal" className="transaction-filters">
      {filters.map((filter) => {
        return (
          <Button
            id={`transaction-filter-${filter.value}-btn`}
            key={filter.value}
            primary={selectedFilterValue === filter.value}
            onClick={() => onFilterChange(filter.value)}
            className={styles['transaction-filters__chip']}
          >
            {filter.text}
          </Button>
        );
      })}
    </Stack>
  );
}
