import { NavigationCard } from '@root/components/NavigationCard';
import { Stack, Image, Typography } from '@trueloyal-engineering/react-ui';
import { EUDSettings } from '@root/core/config';
import { MemberHelper } from '@root/core/helpers';
import { useAppSelector } from '@root/store';
import { useAppNavigation } from '@root/hooks';
import { Close as CloseIcon, History as HistoryIcon } from '@root/icons';
import { formatDateString } from '@root/core/utils/dateUtils';
import { MemberPointsExpirationBanner } from '@root/containers';
import { replaceLabels } from '@root/core/utils/textUtils';
import { ACTIVITY_IDS } from '@root/core/constants/activity.constants';
import { selectActivity } from '@root/store/slices/activitySlice';
import { Icon } from '@root/components';
import styles from './member-profile.module.css';

export function MemberProfile() {
  const member = useAppSelector((state) => state.member.memberDetails);
  const referralActivity = useAppSelector((state) =>
    selectActivity(state, ACTIVITY_IDS.ZRL_REFERRAL_ACTIVITY)
  );
  const {
    gotoMemberOptOut,
    gotoTermsPage,
    gotoMemberPointsHistory,
    gotoMemberPointsExpiry,
    gotoMemberActivity
  } = useAppNavigation();
  const {
    content_settings: {
      member_profile_page_age_text: memberSinceText,
      member_profile_page_view_points_history_text: viewPointsHistoryText,
      member_profile_page_cancel_membership_text: viewCancelMembershipText,
      member_profile_page_view_points_expiry_text: viewPointsExpirationText,
      program_details_currency_plural_text: currencyPlural,
      terms_label: termsLabel
    },
    display_date_format: displayDateFormat,
    avatar_url: avatar
  } = EUDSettings.getInstance();

  const memberFullName = MemberHelper.getFullName(member);
  const memberSinceMessage =
    member?.enrollment_date &&
    replaceLabels(memberSinceText, {
      '{{ENROLLMENT_DATE}}': formatDateString(member.enrollment_date, displayDateFormat)
    });
  const viewPointsHistory = replaceLabels(viewPointsHistoryText, {
    '{{POINTS_LABEL}}': currencyPlural
  });
  const viewPointsExpiration = replaceLabels(viewPointsExpirationText, {
    '{{POINTS_LABEL}}': currencyPlural
  });

  const shouldShowExpiryBanner =
    member && MemberHelper.isExpiryNearThreshold(member.points_expiration_schedule);

  return (
    <div className={styles['member-profile']}>
      <Stack
        align="center"
        justify="center"
        gap={1.2}
        className={styles['member-profile__details']}
      >
        <Image className={styles['member-profile__avatar']} circular src={avatar} />
        <Stack gap={0.1} align="center" justify="center">
          <Typography fontWeight="bold" align="center" variant="bodyLg">
            {memberFullName}
          </Typography>
          <Typography variant="bodySm" fontWeight="thin" muted align="center">
            {memberSinceMessage}
          </Typography>
        </Stack>
      </Stack>
      <Stack className={styles['member-profile__nav']}>
        {member && member.points_expiration_schedule.length > 0 && (
          <NavigationCard
            id="view-expiration-btn"
            icon={<Icon name="stars" size={24} />}
            title={viewPointsExpiration}
            onClick={gotoMemberPointsExpiry}
            banner={
              shouldShowExpiryBanner && (
                <MemberPointsExpirationBanner
                  pointsExpirationSchedule={member.points_expiration_schedule}
                  isClickable={false}
                />
              )
            }
          />
        )}
        {termsLabel && (
          <NavigationCard
            id="view-terms-btn"
            icon={<Icon name="terms" size={24} />}
            title={termsLabel}
            onClick={gotoTermsPage}
          />
        )}

        {referralActivity && (
          <NavigationCard
            id="view-refer-and-earn-btn"
            icon={<Icon name="campaign" size={24} />}
            title={referralActivity.activity_name}
            onClick={() => gotoMemberActivity(referralActivity.activity_id)}
          />
        )}
        <NavigationCard
          id="view-points-history-btn"
          icon={<HistoryIcon width="24" height="24" className="zrl-icon" />}
          title={viewPointsHistory}
          onClick={gotoMemberPointsHistory}
        />
        <NavigationCard
          id="view-cancel-membership-btn"
          icon={<CloseIcon width="24" height="24" />}
          title={viewCancelMembershipText}
          onClick={gotoMemberOptOut}
        />
      </Stack>
    </div>
  );
}
