import { RewardCard } from '@root/core/presets';
import { useAppNavigation } from '@root/hooks';
import { useAppSelector } from '@root/store';
import { Stack, StackProps, classNames } from '@trueloyal-engineering/react-ui';
import { EUDSettings } from '@root/core/config';
import { selectRewards } from '@root/store/slices/rewardSlice';
import styles from './reward-list.module.css';

export interface RewardListProps extends StackProps {
  isGuest: boolean;
  className?: string;
}

export function RewardList({ isGuest, className, ...props }: RewardListProps) {
  const requestRewardsFor = isGuest ? 'guest' : 'member';

  const rewards = useAppSelector((state) => selectRewards(state, requestRewardsFor));
  const availablePoints =
    useAppSelector((state) => state.member.memberDetails?.available_points) ?? 0;

  const { gotoMemberReward } = useAppNavigation();

  const {
    reward_section_loggedin_empty_state_message: noRewardsLoggedInMessage,
    reward_section_guest_empty_state_message: noRewardsGuestMessage
  } = EUDSettings.getInstance().content_settings;

  const noRewardsMessage = isGuest ? noRewardsGuestMessage : noRewardsLoggedInMessage;

  const classes = classNames('reward-list', className);
  return (
    <Stack orientation="horizontal" wrapped justify="center" className={classes} {...props}>
      {rewards && rewards.length > 0
        ? rewards.map((reward) => {
            return (
              <RewardCard
                key={reward.reward_id}
                reward={reward}
                className={styles['reward-list__reward-card']}
                readOnly={isGuest}
                availablePoints={availablePoints}
                onAction={() => gotoMemberReward(reward.reward_id)}
              />
            );
          })
        : noRewardsMessage}
    </Stack>
  );
}
