import { Button, Stack, Image, Typography, Layout } from '@trueloyal-engineering/react-ui';
import { Activity } from '@trueloyal-engineering/ui-api-sdk';
import { EUDSettings } from '@root/core/config';
import { useAppNavigation } from '@root/hooks';
import styles from './activity-success.module.css';

export function ActivitySuccess({ activity }: { activity: Activity }) {
  const { gotoHome, gotoMemberActivities } = useAppNavigation();

  const {
    content_settings: {
      activity_details_page_congratulations_text: congratulationText,
      activity_details_page_goto_home_button_label: gotoHomeButtonLabel,
      activity_details_page_earn_more_points_button_label: earnMorePointsButtonLabel
    },
    activity_details_page_congratulations_image_url: congratulationImageURL,
    congratulations_confetti_url: confettiImageURL
  } = EUDSettings.getInstance();

  const { extra_config: extraConfig } = activity;
  const placeholderThankyouText =
    extraConfig?.thank_you_text ??
    extraConfig?.thank_you_html ??
    extraConfig?.referral_post_share_text;

  return (
    <Layout className="activity-success">
      <Layout.Content centered className={styles['activity-success__content']}>
        <Stack justify="center" align="center" gap={0.5}>
          <Image
            src={congratulationImageURL}
            role="presentation"
            className={styles['activity-success__image']}
          />
          <Typography as="h1" variant="header3xl" fontWeight="bold" align="center">
            {congratulationText}
          </Typography>
          <Typography muted fontWeight="thin" align="center">
            {placeholderThankyouText}
          </Typography>
        </Stack>
        <img
          className={styles['activity-success__confetti']}
          src={confettiImageURL}
          alt="confetti"
          role="presentation"
        />
      </Layout.Content>
      <Layout.Footer>
        <Stack justify="center" align="center">
          <Button
            id="earn-more-points-btn"
            fullWidthOnDeviceType="sm"
            primary
            relaxed
            onClick={gotoMemberActivities}
            btnSize="large"
          >
            {earnMorePointsButtonLabel}
          </Button>
          <Button
            id="goto-home-btn"
            fullWidthOnDeviceType="sm"
            relaxed
            onClick={gotoHome}
            btnSize="large"
          >
            {gotoHomeButtonLabel}
          </Button>
        </Stack>
      </Layout.Footer>
    </Layout>
  );
}
