import { Stack, Button, Layout, Typography, Image } from '@trueloyal-engineering/react-ui';
import { Activity } from '@trueloyal-engineering/ui-api-sdk';
import { ActivityHeader, CopyToClipboardInput } from '@root/components';
import { useGatsbySocialShareActivity } from '@root/hooks/useGatsbySocialShareActivity';
import { AddEditHandleModal, getActivityIcons, getButtonIcon, LineSeparator } from './components';
import styles from './gatsby-share-activity.module.css';
import { ActivitySuccess } from '../ActivitySuccess';

export interface GatsbySocialShareActivityProps {
  activity: Activity;
}

export function GatsbySocialShareActivity({ activity }: GatsbySocialShareActivityProps) {
  const {
    handles,
    isModalOpen,
    userHandle,
    userHasHandle,
    setModalOpen,
    showCongratsAfterVisit,
    handleCopy,
    handleSocialAction
  } = useGatsbySocialShareActivity({ activity });

  const {
    enduser_activity_short_description: title,
    earnpoints_button_label: tagLabel,
    extra_config: extraConfig,
    activity_id: activityId
  } = activity;

  const {
    reward_instruction_text: description,
    activity_start_button_text: activityStartButtonText,
    personal_handle_input_text: personalHandleInputText,
    personal_handle_edit_button_text: personalHandleEditText,
    business_handle_display_text: businessHandleDisplayText
  } = extraConfig || {};

  const userHandleIcon = getActivityIcons(activityId);
  const buttonIcon = getButtonIcon(activityId);

  if (showCongratsAfterVisit) {
    return <ActivitySuccess activity={activity} />;
  }

  return (
    <Layout className="social-share-activity">
      <Layout.Content className={styles['social-layout-container']}>
        <Stack>
          <ActivityHeader tagLabel={tagLabel} title={title} description={description} />
          <Typography variant="bodyLg" fontWeight="thin" muted>
            {businessHandleDisplayText}
          </Typography>
          {handles.map((handle) => (
            <CopyToClipboardInput
              id={handle.id}
              value={handle.value}
              textAlign="start"
              borderStyle="dotted"
              onCopy={handleCopy}
            />
          ))}
        </Stack>
      </Layout.Content>
      <Layout.Footer className="footer-main-container">
        <Stack className={styles['footer-container']}>
          <LineSeparator />
          <Stack wrapped orientation="vertical" gap={0}>
            <Stack
              orientation="horizontal"
              gap={0.3}
              wrapped
              className={styles['footer-handle__container']}
            >
              <Image src={userHandleIcon} className={styles['footer-user-handle__icon']} />
              <Typography className={styles['footer-handle__text']}>{userHandle}</Typography>
              <Button
                link
                onClick={() => setModalOpen(true)}
                className={styles['social-share-activity__edit-button']}
              >
                {personalHandleEditText}
              </Button>
              <Stack className={styles['footer-display-text__wrapper']}>
                <Typography variant="bodySm" fontWeight="thin" muted>
                  {personalHandleInputText}
                </Typography>
              </Stack>
            </Stack>
          </Stack>
          <Button
            id="share-btn"
            fullWidthOnDeviceType="sm"
            primary
            icon={buttonIcon}
            onClick={handleSocialAction}
            btnSize="large"
            relaxed
          >
            {activityStartButtonText}
          </Button>
        </Stack>
      </Layout.Footer>
      <AddEditHandleModal
        className={styles['gatsby-social-activity__edit-modal']}
        isOpen={isModalOpen}
        closeModal={() => setModalOpen(false)}
        activity={activity}
        userHasHandle={userHasHandle}
        currentHandle={userHandle}
      />
    </Layout>
  );
}
