import React from 'react';
import { AriaModalOverlayProps, Overlay, useModalOverlay } from '@react-aria/overlays';
import { classNames } from '@trueloyal-engineering/react-ui';
import { ModalCommonProps } from '../../types';
import { useOverlayContainer } from '../../../OverlayContainer';
import styles from './modal-body.module.css';

export interface ModalBodyProps extends ModalCommonProps, AriaModalOverlayProps {
  children: React.ReactElement;
}

export function ModalBody({ children, _state, ...props }: ModalBodyProps) {
  if (!_state) return null;
  const modalRef = React.useRef(null);
  const overlayContainer = useOverlayContainer();
  const { modalProps, underlayProps } = useModalOverlay(props, _state, modalRef);
  const classes = classNames(styles['modal-body'], modalProps.className);

  if (_state?.isOpen) {
    return (
      <Overlay portalContainer={overlayContainer}>
        <div className={styles['modal-underlay']} {...underlayProps}>
          <div {...modalProps} className={classes} ref={modalRef} aria-label="Modal">
            {children}
          </div>
        </div>
      </Overlay>
    );
  }

  return null;
}
