import { EUDSettings } from '@root/core/config';
import { useAppNavigation } from '@root/hooks';
import { Button, Stack, Typography } from '@trueloyal-engineering/react-ui';

export function TermsSection() {
  const { gotoGuestTerms } = useAppNavigation();

  const { terms_label: termsLabel, terms_guest_instructions_text: termsGuestInstructionText } =
    EUDSettings.getInstance().content_settings;

  if (!termsGuestInstructionText && !termsLabel) {
    return null;
  }

  return (
    <Stack align="center" className="terms-section">
      <Typography align="center" as="h6" fontWeight="thin" muted>
        {termsGuestInstructionText}{' '}
        <Button link onClick={() => gotoGuestTerms()} id="login-btn">
          {termsLabel}
        </Button>
      </Typography>
    </Stack>
  );
}
