import { InputField } from '@trueloyal-engineering/react-ui';
import { formatCalenderDates } from '@root/core/utils/dateUtils';
import { Popover, StyledCalendar } from '@root/components';
import { DEFAULT_INPUT_DATEFORMAT } from '@root/core/constants/date.constants';
import { CalendarDateInput } from '../StyledCalendar/types';

export interface DatePickerProps {
  value: CalendarDateInput;
  onChange: (value: CalendarDateInput) => void;
  className?: string;
  label?: string;
  placeholder?: string;
  dateFormat?: string;
  disabled?: boolean;
}

export function DatePicker({
  value,
  onChange,
  className,
  label,
  placeholder,
  disabled = false,
  dateFormat = DEFAULT_INPUT_DATEFORMAT
}: DatePickerProps) {
  return (
    <Popover>
      <Popover.Trigger>
        <InputField
          value={formatCalenderDates(value, dateFormat)}
          className={className}
          label={label}
          placeholder={placeholder}
          aria-label="Select date"
          aria-haspopup="dialog"
          readOnly
          disabled={disabled}
        />
      </Popover.Trigger>
      <Popover.Body placement="bottom start">
        <StyledCalendar value={value} onChange={onChange} />
      </Popover.Body>
    </Popover>
  );
}
