import { usePagination } from '@root/hooks';
import { useAppDispatch, useAppSelector } from '@root/store';
import { fetchTransactions, resetTransactionState } from '@root/store/slices/transactionSlice';
import { Stack, Button, Typography } from '@trueloyal-engineering/react-ui';
import {
  CommonQueryParams,
  GetTransactionsQueryParams,
  Transaction,
  TransactionPointStatus
} from '@trueloyal-engineering/ui-api-sdk';
import { EUDSettings } from '@root/core/config';
import { useEffect, useState } from 'react';
import { LoadMask } from '@root/components';
import { INCLUDE_TRANSACTION_IN_ALL_FILTER } from '@root/core/constants/transaction.constants';
import {
  TransactionDivider,
  TransactionFilters,
  TransactionRow,
  TransactionYearRow
} from './components';
import { TransactionFilter, TransactionFiltersConfig } from './types';

export function TransactionList() {
  const [transactionFilter, setTransactionFilter] = useState<TransactionFilter>('all');

  const dispatch = useAppDispatch();
  const { transactions, status, more, totalTransactions, nextCursor } = useAppSelector(
    (state) => state.transaction
  );

  const {
    visibleSlice,
    more: moreVisibleTransactions,
    showMore,
    loading,
    changeFilters
  } = usePagination<Transaction, CommonQueryParams<GetTransactionsQueryParams>>({
    data: transactions,
    more,
    status,
    totalCount: totalTransactions,
    nextCursor,
    fetchData(dataFilters) {
      dispatch(fetchTransactions(dataFilters));
    }
  });

  const handleFilterChange = (filter: TransactionFilter) => {
    setTransactionFilter(filter);
    dispatch(resetTransactionState());
    if (filter === 'all') {
      changeFilters({
        points_status: {
          in: INCLUDE_TRANSACTION_IN_ALL_FILTER.join(',') as TransactionPointStatus
        }
      });
      return;
    }
    changeFilters({ points_status: { eq: filter } });
  };

  const {
    points_history_page_filter_all_button_label: filterAllButtonLabel,
    points_history_page_filter_earned_button_label: filterEarnedButtonLabel,
    points_history_page_filter_spent_button_label: filterSpentButtonLabel,
    points_history_page_pagination_button_label: showMoreButtonLabel,
    points_history_page_empty_state_message: noTransactionsMessage
  } = EUDSettings.getInstance().content_settings;

  const filtersText = {
    all: filterAllButtonLabel,
    earned: filterEarnedButtonLabel,
    spent: filterSpentButtonLabel
  };

  const filtersConfig: TransactionFiltersConfig = [
    { text: filtersText.all, value: 'all' },
    { text: filtersText.earned, value: 'approved' },
    { text: filtersText.spent, value: 'redeemed' }
  ];

  let currentYear: number | null = null;

  useEffect(() => {
    // reset to all view when coming back to this page
    handleFilterChange('all');
  }, []);

  return (
    <Stack gap={1.5} className="transaction-list">
      {loading && <LoadMask />}
      <TransactionFilters
        filters={filtersConfig}
        onFilterChange={handleFilterChange}
        selectedFilterValue={transactionFilter}
      />
      <Stack gap={0}>
        {!loading && visibleSlice.length < 1 && (
          <Typography muted>{noTransactionsMessage}</Typography>
        )}
        {visibleSlice?.map((transaction) => {
          const transactionYear = new Date(transaction.created_date).getFullYear();
          if (transactionYear !== currentYear) {
            currentYear = transactionYear;
            return (
              <>
                <TransactionYearRow year={transactionYear} />
                <TransactionRow key={transaction.id} transaction={transaction} />
              </>
            );
          }
          return (
            <>
              <TransactionDivider />
              <TransactionRow key={transaction.id} transaction={transaction} />
            </>
          );
        })}
      </Stack>
      {moreVisibleTransactions && (
        <Button link onClick={showMore} id="show-more-transaction-btn">
          {showMoreButtonLabel}
        </Button>
      )}
    </Stack>
  );
}
