import React from 'react';
import { Overlay, Placement, usePopover } from '@react-aria/overlays';
import { classNames } from '@trueloyal-engineering/react-ui';
import { PopoverCommonProps } from '../../types';
import { useOverlayContainer } from '../../../OverlayContainer';

export interface PopoverBodyProps extends PopoverCommonProps {
  className?: string;
  children: React.ReactElement;
  placement?: Placement;
}

export function PopoverBody({
  className,
  children,
  _state,
  _triggerRef,
  placement = 'bottom'
}: PopoverBodyProps) {
  if (!_triggerRef || !_state) {
    return null;
  }
  const classes = classNames('popover', className);
  const popoverRef = React.useRef(null);
  const overlayContainer = useOverlayContainer();
  const { popoverProps, underlayProps } = usePopover(
    {
      placement,
      offset: 8,
      triggerRef: _triggerRef,
      popoverRef
    },
    _state
  );

  const popoverPropsOverride = {
    ...popoverProps,
    style: {
      ...popoverProps.style,
      maxWidth: '95cqw'
    }
  };

  if (_state?.isOpen) {
    return (
      <Overlay portalContainer={overlayContainer}>
        <div {...underlayProps} className="underlay" />
        <div {...popoverPropsOverride} ref={popoverRef} className={classes}>
          {children}
        </div>
      </Overlay>
    );
  }

  return null;
}
