import React from 'react';
import { useOverlayTriggerState } from 'react-stately';
import { OverlayTriggerProps } from '@react-types/overlays';

import { ModalCommonProps } from './types';
import { ModalBody, ModalTrigger } from './components';

export interface ModalProps extends OverlayTriggerProps {
  children: React.ReactNode;
}

export function Modal({ children, ...props }: ModalProps) {
  const state = useOverlayTriggerState(props);
  const commonProps: ModalCommonProps = {
    _state: state
  };
  return (
    <>
      {React.Children.map(children, (child, _) =>
        React.cloneElement(child as React.ReactElement, {
          ...commonProps
        })
      )}
    </>
  );
}

Modal.Trigger = ModalTrigger;
Modal.Body = ModalBody;
