import { AuthConfig, MerchantConfig } from '@root/core/config';
import { Streak } from '@root/store/slices/streakSlice';
import { StreakUserProgress } from '@root/store/slices/streakUserProgressSlice';
import { Member } from '@trueloyal-engineering/ui-api-sdk';

export const shouldFetchStreakUserProgress = (
  member?: Member,
  streaks?: Streak[],
  streakUserProgress?: Record<string, StreakUserProgress[]>
) => {
  const { enableStreaks } = MerchantConfig.getInstance();
  const isPreview = AuthConfig.isPreview();
  return (
    enableStreaks && !isPreview && member && streaks && streaks.length > 0 && !streakUserProgress
  );
};
