// Type-only: the progress slice imports StreakHelper, so a value import would be a cycle.
import type { Streak } from '@root/store/slices/streakSlice';
import type { StreakUserProgress } from '@root/store/slices/streakUserProgressSlice';
import type { PerkLog } from '@root/store/slices/perkLogSlice';
import { MerchantConfig } from '@root/core/config';
import { formatDateString } from '@root/core/utils/dateUtils';
import { replaceLabels } from '../utils/textUtils';

export class StreakHelper {
  public static getStreakLabels(streak: Streak, userProgress: number) {
    const nameHeader = replaceLabels(streak.eud_headline, {
      '{{STREAK_COUNT}}': streak.eud_streak_completion_count,
      '{{USER_STREAK_COUNT}}': userProgress,
      '{{STREAK_INTERVAL}}': streak.eud_streak_unit
    });
    const streakValidity = replaceLabels(streak.eud_validity, {
      '{{STREAK_END_DATE}}': streak.end_at
        ? formatDateString(streak.end_at, "MMM d, yyyy 'at' h:mm a")
        : ''
    });
    const userProgressText = replaceLabels(streak.eud_user_progress_text, {
      '{{USER_STREAK_COUNT}}': userProgress,
      '{{STREAK_INTERVAL}}': streak.eud_streak_unit
    });
    const streakBrokenText = replaceLabels(streak.eud_streak_broken_text, {
      '{{STREAK_COUNT}}': streak.eud_streak_completion_count,
      '{{USER_STREAK_COUNT}}': userProgress,
      '{{STREAK_INTERVAL}}': streak.eud_streak_unit
    });
    const streakCompletionText = replaceLabels(streak.eud_streak_completion_text, {
      '{{STREAK_COUNT}}': streak.eud_streak_completion_count,
      '{{USER_STREAK_COUNT}}': userProgress,
      '{{STREAK_INTERVAL}}': streak.eud_streak_unit
    });
    return {
      nameHeader,
      streakValidity,
      userProgressText,
      streakBrokenText,
      streakCompletionText
    };
  }

  public static get isStreakRunsEnabled(): boolean {
    return Boolean(MerchantConfig.getInstance().enableStreakRuns);
  }

  public static sortedRuns(runs: StreakUserProgress[] | undefined): StreakUserProgress[] {
    if (!runs?.length) return [];
    return [...runs].sort((a, b) => Date.parse(b.created_at) - Date.parse(a.created_at));
  }

  public static currentRun(runs: StreakUserProgress[] | undefined): StreakUserProgress | undefined {
    if (!runs?.length) return undefined;
    if (!StreakHelper.isStreakRunsEnabled) return runs[runs.length - 1];
    return StreakHelper.sortedRuns(runs)[0];
  }

  public static runWindow(runs: StreakUserProgress[], run: StreakUserProgress) {
    const index = runs.findIndex((candidate) => candidate.id === run.id);
    const nextRun = index > 0 ? runs[index - 1] : undefined;
    return {
      startedAt: Date.parse(run.created_at),
      endedAt: nextRun ? Date.parse(nextRun.created_at) : undefined
    };
  }

  /**
   * Reward logs earned during one run. A log records its streak but not its run, so it is
   * attributed by time. Lower bound is inclusive: a reward unlocked in the transaction that
   * started the run shares its `created_at`.
   */
  public static perkLogsForRun(
    perkLogs: PerkLog[] | undefined,
    runs: StreakUserProgress[] | undefined,
    run: StreakUserProgress | undefined
  ): PerkLog[] {
    if (!perkLogs?.length) return [];
    if (!run || !runs?.length) return perkLogs;
    const { startedAt, endedAt } = StreakHelper.runWindow(runs, run);
    return perkLogs.filter((perkLog) => {
      const earnedAt = Date.parse(perkLog.created_at);
      if (Number.isNaN(earnedAt)) return false;
      return earnedAt >= startedAt && (endedAt === undefined || earnedAt < endedAt);
    });
  }
}
