import { ActivityHelper } from '@root/core/helpers';
import { ErrorHandler } from '@root/core/helpers/error';
import { UIHelpers } from '@root/core/helpers/ui';
import { useAppDispatch } from '@root/store';
import { fetchMember } from '@root/store/slices/memberSlice';
import { Activity } from '@trueloyal-engineering/ui-api-sdk';
import { useState } from 'react';
import { toast } from 'react-toastify';

export interface UseInstagramActivityProps {
  activity: Activity;
}

export function useInstagramActivity({ activity }: UseInstagramActivityProps) {
  const instagramUsername = activity.extra_config?.business_instagram_username;
  const [loading, setLoading] = useState(false);
  const [showCongratulation, setShowCongratulation] = useState(false);
  const dispatch = useAppDispatch();

  const onPopupClose = async () => {
    try {
      setLoading(true);
      const response = await ActivityHelper.performFollowInstagram();
      if (response.success) {
        setShowCongratulation(true);
        dispatch(fetchMember());
      }
    } catch (error) {
      const errorMessage = ErrorHandler.resolveActivityErrorMessage(activity, error);
      toast.error(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  const onFollow = async () => {
    try {
      setLoading(true);
      const shareURL = await ActivityHelper.getInstagramProfileURL(instagramUsername ?? '');
      UIHelpers.openPopup(shareURL, 'share-dialog', '', onPopupClose);
    } catch (error) {
      toast.error(error.message);
    } finally {
      setLoading(false);
    }
  };

  return {
    loading,
    showCongratulation,
    onFollow
  };
}
