export interface MerchantConfig {
  partnerId: string;
  webURL: string;
  signUpURL: string;
  loginURL: string;
  name: string;
  decimalPlacesCount: number;
  enableStreaks: boolean;
  enableChallenges: boolean;
  storeCurrencySymbol: string;
  tierQualificationCriteria: string | undefined;
  tintTeamId?: string;
  tintJsUrl?: string;
  tintAppUrl?: string;
  tintApiUrl?: string;
  enableFormBuilderPoweredRewards?: string;
  showRedeemReason?: boolean;
  enableFormBuilderPoweredActivities?: string;
  tintLocaleMapping?: Record<string, string>;
  negativePointsAllowed?: boolean;
  /** `eud_streak_runs` */
  enableStreakRuns?: boolean;
}

export class MerchantConfig {
  private static instance: MerchantConfig;

  private constructor() {
    // Private constructor to prevent instantiation.
  }

  public static initialize(merchantConfig: MerchantConfig): void {
    MerchantConfig.instance = merchantConfig;
  }

  public static getInstance(): MerchantConfig {
    if (!MerchantConfig.instance) {
      throw new Error('MerchantConfig has not been initialized. Call initialize first.');
    }
    return MerchantConfig.instance;
  }
}
