import { MerchantConfig } from '@root/core/config';
import {
  ACTIVITIES_BASE_PATH,
  GUEST_BASE_PATH,
  MEMBER_BASE_PATH,
  OPT_IN_PATH,
  OPT_OUT_PATH,
  TERMS_PATH,
  PERKS_BASE_PATH,
  PERKS_LOGS_BASE_PATH,
  POINTS_EXPIRY_PATH,
  POINTS_HISTORY_PATH,
  PROFILE_PATH,
  REWARDS_BASE_PATH,
  STREAKS_BASE_PATH,
  TIER_PATH
} from '@root/router/paths';
import { useCallback } from 'react';
import { GetScrollRestorationKeyFunction, To, useLocation, useNavigate } from 'react-router-dom';

export function useAppNavigation() {
  const scrollRestorePaths = [
    '/',
    MEMBER_BASE_PATH,
    GUEST_BASE_PATH,
    `${MEMBER_BASE_PATH}/${ACTIVITIES_BASE_PATH}`,
    `${MEMBER_BASE_PATH}/${REWARDS_BASE_PATH}`
  ];

  const getScrollRestorationKey: GetScrollRestorationKeyFunction = (location) => {
    return scrollRestorePaths.includes(location.pathname)
      ? location.pathname
      : // everything else by location like the browser
        location.key;
  };

  const navigate = useNavigate();
  const { pathname } = useLocation();
  const push = (to: To, state: any) => navigate(to, { state });

  const replace = (to: To, state: any) => navigate(to, { replace: true, state });

  const back = () => navigate(-1);

  const forward = () => navigate(1);

  const gotoMemberActivities = () => navigate(`${MEMBER_BASE_PATH}/${ACTIVITIES_BASE_PATH}`);

  const gotoMemberRewards = () => navigate(`${MEMBER_BASE_PATH}/${REWARDS_BASE_PATH}`);

  const gotoMemberReward = (rewardId: string) =>
    navigate(`${MEMBER_BASE_PATH}/${REWARDS_BASE_PATH}/${rewardId}`);

  const gotoMemberStreakPerk = (streakId: string, perkId: string) =>
    navigate(`${MEMBER_BASE_PATH}/${STREAKS_BASE_PATH}/${streakId}/${PERKS_BASE_PATH}/${perkId}`);

  const gotoMemberStreakPerkLog = (streakId: string, perkId: string, perkLogId: string) =>
    navigate(
      `${MEMBER_BASE_PATH}/${STREAKS_BASE_PATH}/${streakId}/${PERKS_BASE_PATH}/${perkId}/${PERKS_LOGS_BASE_PATH}/${perkLogId}`
    );

  const gotoMemberStreaks = () => navigate(`${MEMBER_BASE_PATH}/${STREAKS_BASE_PATH}`);

  const gotoMemberStreakDetails = (streakId: string) =>
    navigate(`${MEMBER_BASE_PATH}/${STREAKS_BASE_PATH}/${streakId}`);

  const gotoMemberActivity = (activityId: string) => {
    const path = pathname === '/' ? `${MEMBER_BASE_PATH}/${ACTIVITIES_BASE_PATH}` : pathname;
    navigate(`${path}/${activityId}`);
  };

  const gotoViewImage = (id: string, name: string, url: Array<string> | string) => {
    navigate(`${pathname}/${id}`, { state: { id, name, url } });
  };

  const gotoMemberProfile = () => navigate(`${MEMBER_BASE_PATH}${PROFILE_PATH}`);

  const gotoMemberPointsHistory = () => {
    return navigate(`${MEMBER_BASE_PATH}${PROFILE_PATH}/${POINTS_HISTORY_PATH}`);
  };

  const gotoMemberOptIn = () => navigate(`${MEMBER_BASE_PATH}${OPT_IN_PATH}`);

  const gotoMemberOptOut = () => navigate(`${MEMBER_BASE_PATH}${PROFILE_PATH}/${OPT_OUT_PATH}`);

  const gotoMemberTier = () => navigate(`${MEMBER_BASE_PATH}${TIER_PATH}`);

  const gotoMemberPointsExpiry = () =>
    navigate(`${MEMBER_BASE_PATH}${PROFILE_PATH}/${POINTS_EXPIRY_PATH}`);

  const gotoGuestActivities = () => navigate(`${GUEST_BASE_PATH}/${ACTIVITIES_BASE_PATH}`);

  const gotoGuestStreakDetails = (streakId: string) =>
    navigate(`${GUEST_BASE_PATH}/${STREAKS_BASE_PATH}/${streakId}`);

  const gotoGuestStreaks = () => navigate(`${GUEST_BASE_PATH}/${STREAKS_BASE_PATH}`);

  const gotoGuestRewards = () => navigate(`${GUEST_BASE_PATH}/${REWARDS_BASE_PATH}`);

  const gotoHome = useCallback(() => navigate(`/`), []);

  const reloadPage = () => window.location.reload();

  const gotoMerchantSignUpPage = () => {
    window.open(MerchantConfig.getInstance().signUpURL, '_blank');
  };

  const gotoMerchantLoginPage = () => {
    window.open(MerchantConfig.getInstance().loginURL, '_blank');
  };

  const openURL = (url: string) => {
    window.open(url, '_blank');
  };

  const gotoGuestTerms = () => navigate(`${GUEST_BASE_PATH}/${TERMS_PATH}`);

  const gotoTermsPage = () => navigate(`${MEMBER_BASE_PATH}${PROFILE_PATH}/${TERMS_PATH}`);

  return {
    back,
    forward,
    push,
    replace,
    gotoMemberActivities,
    gotoMemberRewards,
    gotoMemberReward,
    gotoMemberStreakPerk,
    gotoMemberStreakPerkLog,
    gotoMemberStreaks,
    gotoMemberStreakDetails,
    gotoMemberActivity,
    gotoMemberPointsHistory,
    gotoViewImage,
    gotoMemberProfile,
    gotoMemberOptIn,
    gotoMemberOptOut,
    gotoMemberTier,
    gotoMemberPointsExpiry,
    gotoGuestStreaks,
    gotoGuestStreakDetails,
    gotoGuestActivities,
    gotoGuestRewards,
    gotoHome,
    reloadPage,
    gotoMerchantSignUpPage,
    gotoMerchantLoginPage,
    getScrollRestorationKey,
    openURL,
    gotoTermsPage,
    gotoGuestTerms
  };
}
