import { Card, CardProps, Stack, classNames } from '@trueloyal-engineering/react-ui';
import React, { forwardRef } from 'react';
import { Tier } from '@trueloyal-engineering/ui-api-sdk';
import { TierHelper } from '@root/core/helpers';
import { Benefits, Header } from './components';
import styles from './tier-card.module.css';

export interface TierCardProps extends CardProps {
  tier: Tier;
  className?: string;
  nextTierPoints?: number;
  highlighted?: boolean;
}

export const TierCard = forwardRef(
  (
    { tier, nextTierPoints, className, highlighted, ...cardProps }: TierCardProps,
    ref: React.ForwardedRef<HTMLDivElement> | undefined
  ) => {
    const { name, description, minimum_points: minimumPoints } = tier;
    const benefits = description.split('|');
    const imageUrl = 'https://d1qbqkkh49kht1.cloudfront.net/57611553f77cf73834e2440254a7cbc9.png';
    // FIXME: HANDLE ABOVE
    const classes = classNames(highlighted && styles['tier-card--highlighted'], className);
    const subTitle = TierHelper.getTierTilesSubTitle(nextTierPoints, minimumPoints);
    return (
      <Card
        role="region"
        aria-label="Tier Information"
        className={classes}
        data-tier_id={tier.tier_id}
        {...cardProps}
      >
        <div ref={ref} />
        <Stack padding={0.2} gap={0.5}>
          <Header heading={name} imageUrl={imageUrl} subHeading={subTitle} />
          <Benefits benefits={benefits} />
        </Stack>
      </Card>
    );
  }
);
