import { ActivityList } from '@root/containers/activity/ActivityList';
import { EUDSettings } from '@root/core/config';
import { replaceLabels } from '@root/core/utils/textUtils';
import { useAppNavigation } from '@root/hooks';
import { GUEST_BASE_PATH } from '@root/router/paths';
import { Page } from '@trueloyal-engineering/react-ui';
import { useMatch } from 'react-router-dom';

export function DefaultActivityListPage() {
  const { gotoHome } = useAppNavigation();

  const match = useMatch(':from/activities');
  const from = match?.params.from;
  const isGuest = `/${from}` === GUEST_BASE_PATH;

  const {
    embed_page_url_patterns: embedURLPatterns,
    content_settings: {
      navigation_home_text: navigationHomeText,
      navigation_back_text: navigationBackText,
      activity_section_header_text: pageTitleText,
      program_details_currency_plural_text: currencyPlural
    }
  } = EUDSettings.getInstance();

  const pageTitle = replaceLabels(pageTitleText, { '{{POINTS_LABEL}}': currencyPlural });
  const showAppBar = embedURLPatterns.length < 1;

  return (
    <Page showAppBar={showAppBar} className="activity-list-page">
      <Page.Header
        title={pageTitle}
        prevPageTitle={navigationHomeText}
        onBack={gotoHome}
        backBtnLabel={navigationBackText}
      />
      <Page.Body>
        <ActivityList isGuest={isGuest} />
      </Page.Body>
    </Page>
  );
}
