import { Transaction } from '@trueloyal-engineering/ui-api-sdk';
import {
  TRANSACTION_AWARD_ICON_LABEL,
  TRANSACTION_DEDUCT_ICON_LABEL,
  TRANSACTION_GENERIC_ICON_LABEL,
  TRANSACTION_REDEEM_ICON_LABEL,
  ORDER_FULLY_RETURNED,
  ORDER_PARTIALLY_RETURNED
} from '@root/core/constants/transaction.constants';
import { ACTIVITY_IDS } from '@root/core/constants/activity.constants';
import { EUDSettings, MerchantConfig } from '@root/core/config';
import { ContentSettings } from '../config/types';
import { ApiClient } from '../api';

export interface TransactionDetails {
  name?: string;
  points?: number;
  iconLabel: string;
  couponCode?: string;
  orderId?: string;
  reason?: string;
  purchasedBy?: string;
  codeEntered?: string;
  usedCouponCode?: string;
  transactionLabel: string;
  receiptId?: string;
  rejectionReason?: string;
  receiptFileUrl?: string[];
  imageUrl?: string;
  rewardLink?: string;
  transactionType?: string;
  id?: string;
}

export class TransactionHelper {
  public static async getTransactionById(transactionId: string) {
    const apiClient = ApiClient.getInstance();
    const response = await apiClient.transactions.getTransactionById(transactionId);
    return response;
  }

  public static getTransactionLabel(transaction: Transaction, labelConfig: ContentSettings) {
    const {
      points_history_page_filter_deducted_button_label: deductedText,
      points_history_page_filter_spent_button_label: spentText,
      points_history_page_filter_earned_button_label: earnedText,
      points_history_page_filter_pending_button_label: pendingText,
      points_history_page_filter_rejected_button_label: rejectedText
    } = labelConfig;

    if (transaction.status === 'pending') return pendingText;
    if (transaction.status === 'rejected') return rejectedText;

    switch (transaction.transaction_type) {
      case 'award':
      case 'coupon_award':
        return earnedText;
      case 'redeem':
        return spentText;
      case 'deduct':
        return deductedText;
      default:
        return transaction.transaction_type;
    }
  }

  public static getDeductTransactionName(transaction: Transaction, labelConfig: ContentSettings) {
    const {
      points_history_page_deduct_transaction_text: deductTransactionName,
      points_history_page_partial_return_transaction_text: partialReturnText,
      points_history_page_fully_return_transaction_text: fullyReturnText
    } = labelConfig;

    const reason = transaction.transaction_attributes?.reason;
    if (reason === ORDER_FULLY_RETURNED) return fullyReturnText;
    if (reason === ORDER_PARTIALLY_RETURNED) return partialReturnText;
    if (reason) return reason;
    return deductTransactionName;
  }

  public static normalizeTransaction(
    transaction: Transaction,
    labelConfig?: ContentSettings
  ): TransactionDetails {
    if (!labelConfig) {
      // eslint-disable-next-line no-param-reassign
      labelConfig = EUDSettings.getInstance().content_settings;
    }
    const { points_history_page_filter_deducted_button_label: deductedText } = labelConfig;
    const transactionLabel = TransactionHelper.getTransactionLabel(transaction, labelConfig);
    const { showRedeemReason } = MerchantConfig.getInstance();

    switch (transaction.transaction_type) {
      case 'award':
      case 'coupon_award': {
        const activityId = transaction.award_info?.activity_id;
        let reason = transaction.transaction_attributes?.reason!;
        let purchasedBy = '';
        if (activityId === ACTIVITY_IDS.ZRL_REFERRAL_ACTIVITY) {
          purchasedBy = reason;
          reason = '';
        }
        return {
          id: transaction.award_info?.activity_id,
          transactionType: transaction.transaction_type,
          name: transaction.award_info?.activity_name,
          points: transaction.award_info?.points,
          orderId: transaction.transaction_attributes?.order_id!,
          reason,
          purchasedBy,
          codeEntered: transaction.additional_data?.code,
          usedCouponCode: transaction.transaction_attributes?.coupon_code!,
          couponCode: transaction.award_info?.coupon_code,
          receiptId: transaction.additional_data?.order_details?.receipt_id,
          rejectionReason: transaction.additional_data?.note,
          receiptFileUrl: transaction.transaction_attributes?.receipt_file_url,
          imageUrl: transaction.transaction_attributes?.image_url,
          iconLabel: TRANSACTION_AWARD_ICON_LABEL,
          transactionLabel
        };
      }
      case 'redeem': {
        return {
          id: transaction.reward_info?.reward_id,
          transactionType: transaction.transaction_type,
          name: transaction.reward_info?.reward_name,
          points: transaction.reward_info?.points,
          couponCode: transaction.reward_info?.coupon_code,
          reason: showRedeemReason ? transaction.transaction_attributes?.reason! : undefined,
          rewardLink: transaction.reward_info?.reward_link!,
          iconLabel: TRANSACTION_REDEEM_ICON_LABEL,
          transactionLabel
        };
      }
      case 'deduct': {
        const name = TransactionHelper.getDeductTransactionName(transaction, labelConfig);
        return {
          id: 'deduct',
          transactionType: transaction.transaction_type,
          name,
          points: transaction.deduct_info?.points,
          iconLabel: TRANSACTION_DEDUCT_ICON_LABEL,
          transactionLabel: deductedText,
          orderId: transaction.transaction_attributes.order_id || ''
        };
      }
      default:
        return {
          name: transaction.transaction_type,
          iconLabel: TRANSACTION_GENERIC_ICON_LABEL,
          transactionLabel: transaction.transaction_type
        };
    }
  }

  public static getPointsDisplay(trxn: Transaction) {
    let sign = '';
    let color = 'inherit';

    switch (trxn.transaction_type) {
      case 'award':
      case 'coupon_award':
        sign = '+';
        color = 'var(--zrl-text-success-color)';
        break;

      case 'deduct':
        sign = '-';
        color = 'var(--zrl-text-critical-color)';
        break;

      case 'redeem':
        sign = '-';
        color = 'var(--zrl-text-warning-color)';
        break;

      default:
        sign = '';
        color = 'inherit';
    }

    return {
      sign,
      color
    };
  }
}
