import { useState, useEffect } from 'react';
import { toast } from 'react-toastify';
import { useAppSelector } from '@root/store';
import { MemberHelper } from '@root/core/helpers';
import { Activity } from '@trueloyal-engineering/ui-api-sdk';
import { AuthConfig, EUDSettings } from '@root/core/config';
import {
  GATSBY_INSTAGRAM_ACTIVITIES,
  GATSBY_TIKTOK_ACTIVITIES,
  GATSBY_INSTAGRAM_BUSINESS_REDIRECT_ACTIVITIES
} from '@root/core/constants/activity.constants';

type Handle = {
  id: string;
  value: string;
};

export interface UseGatsbySocialShareActivityProps {
  activity: Activity;
}

const getActivityLink = (activityId: string, handle: string, businessHandle: string): string => {
  if (GATSBY_INSTAGRAM_ACTIVITIES.has(activityId)) {
    if (GATSBY_INSTAGRAM_BUSINESS_REDIRECT_ACTIVITIES.has(activityId)) {
      return `https://www.instagram.com/${businessHandle}`;
    }
    return `https://www.instagram.com/${handle}`;
  }
  if (GATSBY_TIKTOK_ACTIVITIES.has(activityId)) {
    return `https://www.tiktok.com/@${handle}`;
  }
  return '#';
};

export function useGatsbySocialShareActivity({ activity }: UseGatsbySocialShareActivityProps) {
  const { activity_id: activityId } = activity;
  const isPreview = AuthConfig.isPreview();
  const member = useAppSelector((state) => state.member.memberDetails);

  const isInstagramActivity = activityId.includes('instagram');
  let userHandle = MemberHelper.getUserHandle(member, isInstagramActivity ? 'instagram' : 'tiktok');
  const userHasHandle = !!userHandle;

  if (userHasHandle) {
    userHandle = userHandle.startsWith('@') ? userHandle.slice(1) : userHandle;
  }
  const businessHandle = MemberHelper.getBusinessHandle(
    isInstagramActivity ? 'instagram' : 'tiktok'
  );

  const [handles, setHandles] = useState<Handle[]>([]);
  const [isModalOpen, setModalOpen] = useState(false);
  const [showCongratsAfterVisit, setShowCongratsAfterVisit] = useState(false);

  const {
    content_settings: { commons_copy_text_successful_text: copiedToastText }
  } = EUDSettings.getInstance();

  useEffect(() => {
    if (!userHasHandle && !isPreview) {
      setModalOpen(true);
    }

    const handlesData = businessHandle.map((handle: string, index: number) => {
      let formattedHandle;
      if (isInstagramActivity) {
        formattedHandle = handle.startsWith('@') ? handle : `@${handle}`;
      } else {
        formattedHandle = handle.startsWith('#') ? handle : `#${handle}`;
      }
      return { id: `handle-${index}`, value: formattedHandle };
    });

    setHandles(handlesData);
  }, [businessHandle, userHasHandle]);

  const handleCopy = () => {
    toast.success(copiedToastText, { hideProgressBar: true, autoClose: 1000 });
  };

  const link = getActivityLink(activityId, userHandle, businessHandle?.[0] ?? '');

  const openSocialLink = () => {
    window.open(link, '_blank');
    setShowCongratsAfterVisit(true);
  };

  const handleSocialAction = () => {
    if (isPreview) return;
    if (userHasHandle) {
      openSocialLink();
    } else {
      setModalOpen(true);
    }
  };

  return {
    handles,
    isModalOpen,
    userHandle,
    userHasHandle,
    setModalOpen,
    showCongratsAfterVisit,
    openSocialLink,
    handleCopy,
    handleSocialAction
  };
}
