// eslint-disable-next-line import/no-extraneous-dependencies
import { Member } from '@trueloyal-engineering/ui-api-sdk';
import { MEMBER_STATUS_ACTIVE, MEMBER_STATUS_OPTED_OUT, MEMBER_STATUS_BLOCKED } from '../constants/member.constants';

export interface AuthConfig {
  isPreview?: boolean;
  accessToken: string | undefined | null;
  memberInfo?: Member;
  source: string;
}

export class AuthConfig {
  private static instance: AuthConfig;

  private constructor() {
    // Private constructor to prevent instantiation.
  }

  public static initialize(authConfig: AuthConfig): void {
    AuthConfig.instance = authConfig;
  }

  public static getInstance(): AuthConfig {
    if (!AuthConfig.instance) {
      throw new Error('AuthConfig has not been initialized. Call initialize first.');
    }
    return AuthConfig.instance;
  }

  public static isAuthenticated(): boolean {
    if (
      AuthConfig.instance?.accessToken &&
      AuthConfig.instance?.memberInfo?.member_id &&
      AuthConfig.instance?.memberInfo?.member_status
    ) {
      return true;
    }
    return false;
  }

  public static isPreview(): boolean {
    if (AuthConfig.instance?.isPreview) {
      return true;
    }
    return false;
  }

  public static isOptedOut(): boolean {
    if (!this.isAuthenticated()) {
      throw new Error('Member is not authenticated cannot check member status');
    }
    const instance = this.getInstance();
    return instance.memberInfo?.member_status === MEMBER_STATUS_OPTED_OUT;
  }

  public static isBlocked(): boolean {
    if (!this.isAuthenticated()) {
      throw new Error('Member is not authenticated cannot check member status');
    }
    const instance = this.getInstance();
    return (instance.memberInfo?.member_status as string) === MEMBER_STATUS_BLOCKED;
  }

  public static isMemberActive(): boolean {
    if (!this.isAuthenticated()) {
      return false;
    }
    return this.instance.memberInfo?.member_status === MEMBER_STATUS_ACTIVE;
  }
}
