import { Activity } from '@trueloyal-engineering/ui-api-sdk';
import { AuthConfig, MerchantConfig } from '@root/core/config';
import { TintForm } from '@root/components';

type TintActivityFormProps = {
  activity: Activity;
  onSuccess?: () => void;
};

export function TintActivityForm({ activity, onSuccess }: TintActivityFormProps) {
  const { accessToken } = AuthConfig.getInstance();
  const { tintTeamId } = MerchantConfig.getInstance();

  const { activity_id: activityId, tint_form_id: tintFormId, signature } = activity;

  if (!tintTeamId) {
    return null;
  }

  return (
    <TintForm
      teamId={tintTeamId}
      formId={tintFormId}
      accessToken={accessToken}
      metadata={`activity_id=${activityId}&signature=${signature}`}
      onAfterSubmit={onSuccess}
    />
  );
}
