import React from 'react';
import {
  Button,
  Card,
  CardProps,
  Image,
  Stack,
  Typography,
  classNames
} from '@trueloyal-engineering/react-ui';
import { DEFAULT_IMAGE_URL } from '@root/core/constants/reward.constants';
import { Perk } from '@root/store/slices/streakPerkSlice';
import { Icon } from '@root/components';
import styles from './perk-card.module.css';

export interface PerkCardProps extends CardProps {
  perk: Perk;
  onAction?: () => void;
  isGuest?: boolean;
  className?: string;
}

export function PerkCard({
  perk,
  onAction,
  isGuest = true,
  className,
  ...cardProps
}: PerkCardProps) {
  const imageSrc = perk.eud_image || DEFAULT_IMAGE_URL;

  const baseClasses = classNames(!isGuest && styles['perk-card--clickable'], className);

  return (
    <Card
      role="region"
      aria-labelledby="Perk Information"
      onClick={!isGuest ? onAction : undefined}
      className={baseClasses}
      data-perk_id={perk.id}
      {...cardProps}
    >
      <Stack gap={0.8} padding={0.7} align="start">
        <Stack className={styles['perk-card__image-container']}>
          <Image
            loading="lazy"
            className={styles['perk-card__image']}
            src={imageSrc}
            fit="cover"
            fillWidth
          />
        </Stack>
        <Stack gap={0.2}>
          <Typography trunc={2} title={perk.eud_title}>
            {perk.eud_title}
          </Typography>
          <Typography
            muted
            trunc={2}
            title={perk.eud_description}
            fontWeight="thin"
            variant="bodySm"
          >
            {perk.eud_description}
          </Typography>
        </Stack>
        {!isGuest && (
          <Button
            id="view-perk-btn"
            primary
            fullWidthOnDeviceType="all"
            disabled={!perk.reward_log_status || perk.reward_log_status === 'locked'}
            icon={
              (!perk.reward_log_status || perk.reward_log_status === 'locked') && (
                <Icon className={styles['perk-card__locked-icon']} name="lock" size={14} />
              )
            }
          >
            {perk.reward_log_status === 'claimed'
              ? perk.eud_post_claim_button_label
              : perk.eud_claim_button_label}
          </Button>
        )}
      </Stack>
    </Card>
  );
}
