import { isRTL } from '@root/core/utils/languageUtils';
import { useEffect } from 'react';

export function useLanguageHandler(language: string) {
  const isAppRTL = isRTL(language);
  useEffect(() => {
    document.documentElement.dir = isRTL(language) ? 'rtl' : 'ltr';
  }, [language]);
  return {
    isAppRTL
  };
}
