import { Hero, QuickActionList } from '@root/components';
import { Container, Typography } from '@trueloyal-engineering/react-ui';
import { EUDSettings, MerchantConfig } from '@root/core/config';
import {
  ActivityCarousel,
  MemberOverview,
  RewardCarousel,
  TierCarousel,
  MemberCard
} from '@root/containers';
import { useAppSelector } from '@root/store';
import React from 'react';
import { StreakCarousel } from '@root/containers/streaks/StreakCarousel';
import styles from './member-page.module.css';

export function DefaultMemberPage() {
  const memberTierId = useAppSelector(
    (state) => state.member.memberDetails?.tier_info?.loyalty_tier_id
  );

  const { background_image_url: backgroundImageURL } = EUDSettings.getInstance();

  const { enableStreaks, enableChallenges } = MerchantConfig.getInstance();

  return (
    <div className="member-page">
      <Hero bgImg={backgroundImageURL} fillImage={false}>
        <MemberOverview />
        <MemberCard />
      </Hero>

      <Container className={styles['member-container']}>
        {(enableStreaks || enableChallenges) && (
          <div className={styles['member-container__quick-actions']}>
            <Typography variant="headerXl" fontWeight="bold" titled trunc={1} title="Quick Actions">
              Quick Actions
            </Typography>
            <QuickActionList />
          </div>
        )}
        <RewardCarousel isGuest={false} />
        <ActivityCarousel isGuest={false} />
        <TierCarousel highlightedTierId={memberTierId} />
        {enableStreaks && <StreakCarousel isGuest={false} />}
      </Container>
    </div>
  );
}
