import { sanitizeHTML } from '@root/core/utils/htmlUtils';
import { Tag, Typography } from '@trueloyal-engineering/react-ui';

export interface ActivityHeaderProps {
  tagLabel?: string;
  title?: string;
  description?: string;
}

export function ActivityHeader({ tagLabel, title, description }: ActivityHeaderProps) {
  return (
    <>
      {tagLabel && <Tag primary label={tagLabel} />}
      <Typography variant="header2xl" fontWeight="bold">
        {title}
      </Typography>
      <Typography
        variant="bodyMd"
        fontWeight="thin"
        muted
        dangerouslySetInnerHTML={{ __html: sanitizeHTML(description) }}
      />
    </>
  );
}
