import { useEffect } from 'react';
import { Modal } from '@root/components';
import { Button, InputField, Stack, Typography } from '@trueloyal-engineering/react-ui';
import { useEnterHandleActivity } from '@root/hooks/useEnterHandleActivity';
import { AuthConfig } from '@root/core/config';
import { ACTIVITY_IDS, GATSBY_INSTAGRAM_ACTIVITIES } from '@root/core/constants/activity.constants';
import { Activity } from '@trueloyal-engineering/ui-api-sdk';
import styles from './add-edit-modal.module.css';

export interface CommonModalProps {
  isOpen: boolean;
  className?: string;
  closeModal: () => void;
  activity: Activity;
  userHasHandle: boolean;
  currentHandle?: string | null;
}

export function AddEditHandleModal({
  isOpen,
  className,
  closeModal,
  activity,
  userHasHandle,
  currentHandle
}: CommonModalProps) {
  const { extra_config: extraConfig, activity_id: activityId } = activity;

  const {
    handle_required_alert_text: handleRequiredAlertText,
    enter_handle_prompt_text: enterHandlePromptText,
    personal_handle_submit_button_text: personalHandleSubmitText,
    cancel_button_text: cancelButtonText,
    edit_handle_text: editHandleText,
    enter_handle_placeholder_text: enterHandlePlaceholderText
  } = extraConfig || {};

  let handleType: 'instagram_handle' | 'tiktok_handle';

  if (GATSBY_INSTAGRAM_ACTIVITIES.has(activityId)) {
    handleType = 'instagram_handle';
  } else if (activityId === ACTIVITY_IDS.ZRL_TAG_ON_TIKTOK) {
    handleType = 'tiktok_handle';
  } else {
    throw new Error('Unsupported activity Id');
  }

  const { loading, handle, setHandle, handleChange, submitHandle, isModified } =
    useEnterHandleActivity({
      activity,
      eligibleFieldKey: handleType
    });

  useEffect(() => {
    if (isOpen) {
      setHandle(() => (userHasHandle && currentHandle ? currentHandle : ''));
    }
  }, [isOpen, userHasHandle, currentHandle, setHandle]);

  const isPreview = AuthConfig.isPreview();

  const handleSubmit = async () => {
    await submitHandle();
    closeModal();
  };

  const handleCloseModal = () => {
    closeModal();
    setHandle('');
  };

  return (
    <Modal isOpen={isOpen}>
      <Modal.Body isDismissable>
        <Stack className={className}>
          {!userHasHandle && (
            <Typography variant="bodyLg" className={styles['prompt-error-text']}>
              {handleRequiredAlertText}
            </Typography>
          )}
          <Typography variant="header2xl" fontWeight="bold">
            {userHasHandle ? editHandleText : enterHandlePromptText}
          </Typography>
          <Stack
            orientation="horizontal"
            gap={0.4}
            className={styles['enter-handle-symbol__wrapper']}
          >
            <Typography variant="bodyXl" fontWeight="thin" className={styles['at-symbol']} muted>
              @
            </Typography>
            <InputField
              placeholder={enterHandlePlaceholderText}
              value={handle}
              onChange={handleChange}
              className={styles['edit-modal__input']}
            />
          </Stack>
          <Stack orientation="horizontal" className={styles['submit-handle__button-group']}>
            <Button
              id="submit-handles-btn"
              btnSize="medium"
              relaxed
              primary
              onClick={!isPreview ? handleSubmit : undefined}
              disabled={loading || !isModified}
            >
              {personalHandleSubmitText}
            </Button>
            <Button
              id="close-handles-modal-btn"
              onClick={handleCloseModal}
              btnSize="medium"
              relaxed
            >
              {cancelButtonText}
            </Button>
          </Stack>
        </Stack>
      </Modal.Body>
    </Modal>
  );
}
