export const calculateRemainingPointsPercentage = (
  availablePoints: number,
  points: number
): number => {
  if (points === 0 && availablePoints >= 0) {
    return 100;
  }
  if (availablePoints <= 0) return 0;
  const ratio = availablePoints / points;

  if (availablePoints >= points) {
    return 100;
  }
  if (ratio <= 0.2) {
    return 25;
  }
  if (ratio <= 0.4) {
    return 50;
  }
  if (ratio <= 0.75) {
    return 75;
  }
  if (ratio > 0.75 && ratio < 1) {
    return 75;
  }

  return 0;
};
