import { STYLE_ATTRIBUTES } from '../constants/styleConstants';

export const injectIndexStyles = (shadowRoot: ShadowRoot, indexCssString: string) => {
  const indexStyle = document.createElement('style');
  indexStyle.textContent = indexCssString;
  indexStyle.setAttribute(STYLE_ATTRIBUTES.INDEX, 'true');
  shadowRoot.appendChild(indexStyle);
};

export const injectIconStyles = (shadowRoot: ShadowRoot) => {
  const iconStyles = document.createElement('style');
  iconStyles.textContent = `
    .material-icons {
      font-family: 'Material Icons';
      font-weight: normal;
      font-style: normal;
      font-size: 24px;
      display: inline-block;
      line-height: 1;
      text-transform: none;
      letter-spacing: normal;
      word-wrap: normal;
      white-space: nowrap;
      direction: ltr;
      -webkit-font-smoothing: antialiased;
      text-rendering: optimizeLegibility;
      -moz-osx-font-smoothing: grayscale;
      font-feature-settings: 'liga';
    }
  `;
  iconStyles.setAttribute(STYLE_ATTRIBUTES.ICON_FIX, 'true');
  shadowRoot.appendChild(iconStyles);
};

const cloneAppBundledStyles = (shadowRoot: ShadowRoot) => {
  const allStyles = Array.from(document.head.querySelectorAll('style'));

  allStyles.forEach((styleTag) => {
    const content = styleTag.textContent || '';
    if (!content || content.trim().length === 0) return;

    const alreadyExists = Array.from(shadowRoot.querySelectorAll('style')).some(
      (existing) => existing.textContent === content
    );

    if (!alreadyExists) {
      const clonedStyle = document.createElement('style');
      clonedStyle.textContent = content;
      clonedStyle.setAttribute(STYLE_ATTRIBUTES.CLONED, 'true');
      shadowRoot.appendChild(clonedStyle);
    }
  });
};

const injectFontImports = (shadowRoot: ShadowRoot, customCss?: string) => {
  if (!customCss) return '';

  // Extract @import statements (must be at the beginning of stylesheet)
  const importRegex = /@import\s+url\([^)]+\)\s*;?/g;
  const imports = customCss.match(importRegex);

  if (imports && imports.length > 0) {
    // Check if already injected in document head to avoid duplicates
    const existingFontImports = document.head.querySelector(`[${STYLE_ATTRIBUTES.FONT_IMPORTS}]`);

    if (!existingFontImports) {
      // Inject into document head (like production) instead of Shadow DOM
      // This ensures fonts are globally available
      const fontImportStyle = document.createElement('style');
      fontImportStyle.setAttribute(STYLE_ATTRIBUTES.FONT_IMPORTS, 'true');
      fontImportStyle.textContent = imports.join('\n');
      document.head.appendChild(fontImportStyle);
    }

    // Return custom CSS without @import statements
    return customCss.replace(importRegex, '').trim();
  }

  return customCss;
};

export const injectCustomStyles = (shadowRoot: ShadowRoot, customCss?: string) => {
  if (!customCss) return;

  const customStyle = document.createElement('style');
  customStyle.setAttribute(STYLE_ATTRIBUTES.CUSTOM_CSS, 'true');
  customStyle.textContent = customCss;
  shadowRoot.appendChild(customStyle);
};

export const injectStylesIntoShadowRoot = (
  shadowRoot: ShadowRoot,
  indexCssString: string,
  customCss?: string
) => {
  // @import must be first in stylesheet, so extract and inject them before anything else
  const customCssWithoutImports = injectFontImports(shadowRoot, customCss);

  injectIconStyles(shadowRoot);
  cloneAppBundledStyles(shadowRoot);
  injectIndexStyles(shadowRoot, indexCssString);
  injectCustomStyles(shadowRoot, customCssWithoutImports);
};
