import { ThemeConfig } from '@trueloyal-engineering/react-ui';
import { ThemeHelpers } from '@root/core/helpers/theme';
import { overrideObject } from '@root/core/utils/commonUtils';
import { ContentSettings, IEUDSettings } from './types';

export class EUDSettings {
  private static instance: IEUDSettings;

  private constructor() {
    // Private constructor to prevent instantiation.
  }

  public static initialize(eudSettings: IEUDSettings): void {
    EUDSettings.instance = eudSettings;
  }

  public static getInstance(): IEUDSettings {
    if (!EUDSettings.instance) {
      throw new Error('EUDSettings has not been initialized. Call initialize first.');
    }
    return EUDSettings.instance;
  }

  public static getThemeConfig(): ThemeConfig {
    if (!EUDSettings.instance.theme_settings) {
      throw new Error(
        'EUDSettings has not been initialized with theme config. Call initialize first.'
      );
    }

    return ThemeHelpers.getRawThemeConfigFromThemeSettings(EUDSettings.instance.theme_settings);
  }

  public static updateLabelsConfig(updatedSettings: Partial<ContentSettings>) {
    if (!EUDSettings.instance.content_settings) {
      throw new Error(
        'EUDSettings has not been initialized with theme config. Call initialize first.'
      );
    }
    this.instance.content_settings = {
      ...this.instance.content_settings,
      ...updatedSettings
    };
  }

  public static updateEUDSettings(updatedSettings: Partial<IEUDSettings>) {
    if (!EUDSettings.instance.content_settings) {
      throw new Error(
        'EUDSettings has not been initialized with theme config. Call initialize first.'
      );
    }
    this.instance = overrideObject(this.instance, updatedSettings);

    if (
      Object.prototype.hasOwnProperty.call(updatedSettings, 'theme_settings') &&
      updatedSettings.theme_settings
    ) {
      ThemeHelpers.updateThemeFromThemeSettings(updatedSettings.theme_settings);
    }
  }
}
