import { ActivityHeader, ImagePreview, LoadMask } from '@root/components';
import { Button, Stack, Typography, Layout } from '@trueloyal-engineering/react-ui';
import { Activity } from '@trueloyal-engineering/ui-api-sdk';
import {
  ALLOWED_IMAGE_FILE_TYPES,
  MAX_NUMBER_OF_PHOTO_UPLOAD,
  MAX_UPLOAD_FILE_SIZE_IN_MB
} from '@root/core/constants/activity.constants';
import { useFile, useUploadPhotoActivity } from '@root/hooks';
import { sanitizeHTML } from '@root/core/utils/htmlUtils';
import { AuthConfig } from '@root/core/config';
import styles from './upload-photo-activity.module.css';
import { ActivitySuccess } from '../ActivitySuccess';

export interface UploadPhotoActivityProps {
  activity: Activity;
}

export function UploadPhotoActivity({ activity }: UploadPhotoActivityProps) {
  const {
    enduser_activity_short_description: title,
    extra_config: extraConfig,
    earnpoints_button_label: tagLabel
  } = activity;

  const { inputRef, files, removeAllFiles, selectFile, handleFileChange } = useFile({
    maxFileSizeInMB: MAX_UPLOAD_FILE_SIZE_IN_MB,
    maxNumberOfFiles: MAX_NUMBER_OF_PHOTO_UPLOAD,
    errorLabels: {
      MAX_FILE_NUMBER_REACHED: extraConfig?.file_count_error_message ?? '',
      MAX_FILE_SIZE_REACHED: extraConfig?.file_size_error_message ?? ''
    },
    allowedExtensions: ALLOWED_IMAGE_FILE_TYPES
  });

  const { loading, showCongratulation, uploadFile } = useUploadPhotoActivity({ activity, files });
  if (showCongratulation) {
    return <ActivitySuccess activity={activity} />;
  }

  const description = extraConfig?.reward_instruction_text;
  const instructionsHTML = extraConfig?.instructions_html;
  const choosePhotoButtonText = extraConfig?.upload_button_text;
  const uploadButtonText = extraConfig?.photo_upload_confirmation_text;

  const isPreview = AuthConfig.isPreview();

  return (
    <Layout className="upload-photo-activity">
      {loading && <LoadMask />}
      <Layout.Content>
        <Stack>
          <ActivityHeader tagLabel={tagLabel} title={title} description={description} />
          <Typography
            muted
            fontWeight="thin"
            dangerouslySetInnerHTML={{ __html: sanitizeHTML(instructionsHTML) }}
          />
          {files.length > 0 && (
            <ImagePreview onRemove={removeAllFiles}>
              <img
                src={URL.createObjectURL(files[0])}
                alt="hidden"
                className={styles['upload-photo-activity__image-preview']}
              />
            </ImagePreview>
          )}
        </Stack>
        <input
          hidden
          style={{ display: 'none' }}
          type="file"
          ref={isPreview ? null : inputRef}
          onChange={!isPreview ? handleFileChange : undefined}
          accept="image/*"
          aria-hidden
          aria-label="File Upload"
        />
      </Layout.Content>
      <Layout.Footer>
        <Button
          id="upload-photo-btn"
          primary
          fullWidthOnDeviceType="sm"
          onClick={files.length > 0 ? uploadFile : selectFile}
          btnSize="large"
        >
          {files.length > 0 ? uploadButtonText : choosePhotoButtonText}
        </Button>
      </Layout.Footer>
    </Layout>
  );
}
