import { ActivityHelper } from '@root/core/helpers';
import { ErrorHandler } from '@root/core/helpers/error';
import { UIHelpers } from '@root/core/helpers/ui';
import {
  Activity,
  ActivityTypes,
  GetTrackingCodeActivities
} from '@trueloyal-engineering/ui-api-sdk';
import { useState } from 'react';
import { toast } from 'react-toastify';

export interface UseSocialShareActivityProps {
  activity: Activity;
}
export function useSocialShareActivity({ activity }: UseSocialShareActivityProps) {
  const [loading, setLoading] = useState(false);
  const [showCongratulation, setShowCongratulation] = useState(false);

  const onPopupClose = async (trackCode: string) => {
    try {
      setLoading(true);
      const response = await ActivityHelper.performSocialShare(
        activity.activity_id as ActivityTypes,
        trackCode
      );
      if (response.success) {
        setShowCongratulation(true);
      }
    } catch (error) {
      const errorMessage = ErrorHandler.resolveActivityErrorMessage(activity, error);
      toast(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  const onShare = async () => {
    try {
      setLoading(true);
      const [shareURL, trackCode] = await ActivityHelper.getShareDetails(
        activity.activity_id as GetTrackingCodeActivities,
        activity.extra_config
      );
      UIHelpers.openPopup(
        shareURL,
        'share-dialog',
        'width=800,height=600',
        onPopupClose.bind(null, trackCode)
      );
    } catch (error) {
      toast(error.message);
    } finally {
      setLoading(false);
    }
  };

  return {
    loading,
    showCongratulation,
    onShare
  };
}
