import { useEffect, useRef } from 'react';
import { MerchantConfig } from '@root/core/config';
import { getTintUrls } from '@root/core/helpers/tint';

export interface TintFormProps {
  teamId: string;
  formId: string;
  accessToken: string;
  metadata: string;
  onAfterSubmit?: () => void;
}

export function TintForm({ teamId, formId, accessToken, metadata, onAfterSubmit }: TintFormProps) {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) {
      return;
    }

    // eslint-disable-next-line no-underscore-dangle
    if (!(window as any)._env_ || typeof (window as any)._env_ !== 'object') {
      // eslint-disable-next-line no-underscore-dangle
      (window as any)._env_ = {};
    }
    // eslint-disable-next-line no-underscore-dangle
    const env = (window as any)._env_;

    const { appUrl: eudBaseUrl, apiUrl: eudApiUrl } = getTintUrls(MerchantConfig.getInstance());

    env.BASE_URL = eudBaseUrl;
    env.API_URL = eudApiUrl;

    const formBuilderBundleUrl = `${eudBaseUrl}dist/formBuilder-bundle.js`;

    const ensureFormBuilderLoaded = (): Promise<void> => {
      return new Promise((resolve, reject) => {
        if (typeof (window as any).Tint?.tintFormBuilderRender === 'function') {
          resolve();
          return;
        }

        const existingScript = document.querySelector(
          `script[src="${formBuilderBundleUrl}"]`
        ) as HTMLScriptElement | null;
        if (existingScript && existingScript.addEventListener) {
          try {
            existingScript.addEventListener('load', () => {
              if (typeof (window as any).Tint?.tintFormBuilderRender === 'function') {
                resolve();
              } else {
                reject(
                  new Error('formBuilder script loaded but tintFormBuilderRender not defined')
                );
              }
            });
            existingScript.addEventListener('error', () => {
              reject(new Error('Failed to load formBuilder script'));
            });
            return;
          } catch (err) {
            // Script exists but event listeners couldn't be attached
          }
        }

        const script = document.createElement('script');
        script.src = formBuilderBundleUrl;
        script.async = true;
        script.onload = () => {
          if (typeof (window as any).Tint?.tintFormBuilderRender === 'function') {
            if (!(window as any).Tint) {
              (window as any).Tint = {};
            }
            (window as any).Tint.formScriptFetched = true;
            resolve();
          } else {
            reject(new Error('formBuilder script loaded but tintFormBuilderRender not defined'));
          }
        };
        script.onerror = () => {
          reject(new Error('Failed to load formBuilder-bundle.js'));
        };
        document.head.appendChild(script);
      });
    };

    let formElement: any = null;
    let mounted = true;

    ensureFormBuilderLoaded()
      .then(() => {
        if (!mounted) return;

        formElement = document.createElement('tint-form') as any;
        formElement.setAttribute('team-id', teamId);
        formElement.setAttribute('form-id', formId);
        formElement.setAttribute('access-token', accessToken);
        formElement.setAttribute('metadata', metadata);

        formElement.style.all = 'initial';
        formElement.style.display = 'block';

        container.appendChild(formElement);

        setTimeout(() => {
          if (!mounted || !formElement.parentNode) {
            return;
          }

          // eslint-disable-next-line no-underscore-dangle
          const apiUrl = (window as any)._env_.API_URL;
          (window as any).Tint.tintFormBuilderRender({
            hostElement: formElement,
            stylesUrl: `${apiUrl}/v2/teams/${teamId}/forms/${formId}.css`,
            apiUrl,
            tintAnonymousUid: (window as any).Tint?.anonymous_uid,
            teamId,
            formId,
            accessToken,
            metadata,
            onAfterSubmit: () => {
              onAfterSubmit?.();
            },
            onAfterLoad: () => {},
            onBeforeSubmit: () => {}
          });
        }, 0);
      })
      .catch((error) => {
        if (!mounted || !container) {
          return;
        }

        const errorDiv = document.createElement('div');
        errorDiv.style.cssText =
          'padding: 1rem; color: #dc3545; background: #f8d7da; border: 1px solid #f5c6cb; border-radius: 4px;';
        errorDiv.innerHTML = `<strong>Error:</strong> Failed to load form builder. ${error.message}`;
        container.appendChild(errorDiv);
      });

    // eslint-disable-next-line consistent-return
    return () => {
      mounted = false;
      if (formElement && container.contains(formElement)) {
        container.removeChild(formElement);
      }
    };
  }, [teamId, formId, accessToken, metadata]);

  return (
    <div
      ref={containerRef}
      style={{
        all: 'initial',
        display: 'block',
        width: '100%'
      }}
    />
  );
}
