import { ChangeEvent } from 'react';
import styles from './select.module.css';

export interface SelectOption {
  label: string;
  value: string | number;
}

export interface SelectProps {
  options?: SelectOption[];
  placeholder?: string;
  selectedOption?: string | number;
  onOptionChange?: (value: string | number) => void;
  disabled?: boolean;
  className?: string;
  ariaLabel?: string;
}

export function Select({
  options = [],
  placeholder = 'Select...',
  selectedOption,
  onOptionChange,
  disabled = false,
  className = '',
  ariaLabel
}: SelectProps) {
  const handleChange = (e: ChangeEvent<HTMLSelectElement>) => {
    const { value } = e.target;
    if (onOptionChange && value !== '') {
      // Convert to number if the original option value is a number
      const option = options.find((opt) => String(opt.value) === value);
      if (option) {
        onOptionChange(option.value);
      }
    }
  };

  const selectedValue = selectedOption !== undefined ? String(selectedOption) : '';

  return (
    <div className={`${styles['select-wrapper']} ${className}`}>
      <select
        className={styles.select}
        value={selectedValue}
        onChange={handleChange}
        disabled={disabled}
        aria-label={ariaLabel}
      >
        <option value="" disabled>
          {placeholder}
        </option>
        {options.map((option) => (
          <option key={option.value} value={String(option.value)}>
            {option.label}
          </option>
        ))}
      </select>
      {!disabled && (
        <span className={`${styles['select-icon']} material-symbols-rounded`}>expand_more</span>
      )}
    </div>
  );
}
