/* eslint-disable no-param-reassign */
import { createAsyncThunk, createSlice } from '@reduxjs/toolkit';
import { fetchData } from '@root/store/slices/mockApi/streaks.api';
import { EUDSettings } from '@root/core/config';
import { RootState } from '@root/store';
import { CommonThunkError, CommonState } from '../types';

export interface Streak {
  name: string;
  description: string;
  eud_headline: string;
  eud_message: string;
  eud_call_to_action: string;
  eud_validity: string;
  end_at: string;
  start_at: string;
  id: string;
  status: 'live' | 'inactive' | 'draft' | 'scheduled' | 'manual_paused' | 'auto_paused' | 'aborted';
  eud_streak_completion_count: number;
  eud_streak_unit: string;
  eud_user_progress_text: string;
  eud_streak_completion_text: string;
  eud_streak_broken_text: string;
  eud_manual_paused_text: string;
  rewards: Array<string>;
}

type ApiResponse<T> = {
  data: T;
};

export interface StreakState extends CommonState {
  streaks: Streak[] | undefined;
}

const initialState: StreakState = {
  streaks: undefined,
  status: 'idle',
  errorMessage: ''
};

export const fetchAllStreaks = createAsyncThunk<
  Streak[] | undefined,
  void,
  { rejectValue: CommonThunkError }
>('streaks/fetchAll', async (_, { rejectWithValue }) => {
  try {
    const response = await fetchData<ApiResponse<Streak[]>>();
    return response?.data ?? [];
  } catch (error) {
    return rejectWithValue({
      errorMessage: EUDSettings.getInstance().content_settings.streak_section_error_state_message
    });
  }
});

export const streakSlice = createSlice({
  name: 'streak',
  initialState,
  reducers: {},
  extraReducers: (builder) => {
    builder.addCase(fetchAllStreaks.fulfilled, (state, action) => {
      state.streaks = action.payload;
      state.status = 'succeeded';
    });
    builder.addCase(fetchAllStreaks.rejected, (state) => {
      state.status = 'failed';
    });
    builder.addCase(fetchAllStreaks.pending, (state) => {
      state.status = 'pending';
    });
  }
});

export const selectStreak = (state: RootState, streakId: string | undefined) => {
  if (!streakId) return null;
  const filteredStreaks = state.streak.streaks?.filter((streak) => streak.id === streakId);
  if (filteredStreaks) {
    return filteredStreaks[0];
  }
  return null;
};

export default streakSlice.reducer;
