import React from 'react';
import { ModalCommonProps } from '../../types';

export interface ModalTriggerProps extends ModalCommonProps {
  children: React.ReactElement;
}

export function ModalTrigger({ children, _state }: ModalTriggerProps) {
  if (!_state) {
    return null;
  }
  const togglePopover = () => {
    _state.toggle();
  };
  return React.cloneElement(children as React.ReactElement, {
    onClick: togglePopover
  });
}
