  width: 100%;
  max-height: 350px;
  aspect-ratio: 1;
  background-color: #f8f8f8;
  background-color: var(--zrl-image-bg, #f8f8f8);
}

.perk-details main {
  flex: 1 1;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 1rem;
  position: relative;
  margin-bottom: 4rem;
}

.perk-details__footer{
  box-sizing: border-box;
  position: -webkit-sticky;
  position: sticky;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 1.5rem;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.00) 0%, var(--zrl-global-color-bg) 100%);
}

