/* eslint-disable no-param-reassign */
import {
  Activity,
  PointsExpirationSchedule,
  Reward,
  Tier
} from '@trueloyal-engineering/ui-api-sdk';
import { Replaceable } from '@root/core/types';
import { formatDateString } from '@root/core/utils/dateUtils';
import { EUDSettings, IntegrationSettings, MerchantConfig } from '@root/core/config';
import { formatNumber, pluralize, replaceLabels } from '@root/core/utils/textUtils';
import { ContentSettings } from '@root/core/config/types';
import { TIER_QUALIFICATION_SPEND_BASED } from '../constants/tier.constants';

export type ValidCandidateForReplace = 'activity' | 'reward' | 'tier' | 'streaks' | 'streak';

export class LabelHelpers {
  public static getTierReplaceable(tier: Tier, labels: ContentSettings) {
    const {
      program_details_currency_plural_text: currencyPlural,
      program_details_currency_singular_text: currencySingular
    } = labels;
    const { minimum_points: points } = tier;
    return {
      '{{POINTS}}': formatNumber(points),
      '{{POINTS_LABEL}}': pluralize(points, currencySingular, currencyPlural)
    };
  }

  public static getActivityReplaceable(activity: Activity, labels: ContentSettings) {
    const {
      program_details_currency_plural_text: currencyPlural,
      program_details_currency_singular_text: currencySingular
    } = labels;
    const { points_config: pointsConfig } = activity;
    const points =
      pointsConfig.points_computation_type === 'multiplier_based'
        ? pointsConfig.multiplier
        : pointsConfig.points;

    const {
      business_instagram_handles: businessInstagramHandles = [],
      tiktok_hashtags: tiktokHashtags = []
    } = IntegrationSettings.getInstance();

    const instagramHandlesString =
      businessInstagramHandles.length > 0
        ? businessInstagramHandles.map((handle) => `@${handle.replace(/^@/, '')}`).join(' / ')
        : '';

    const tiktokHashtagsString =
      tiktokHashtags.length > 0
        ? tiktokHashtags.map((hashtag) => `@${hashtag.replace(/^@/, '')}`).join(' / ')
        : '';

    return {
      '{{POINTS}}': formatNumber(points) ?? '',
      '{{POINTS_LABEL}}': pluralize(points, currencySingular, currencyPlural),
      '{{MERCHANT_NAME}}': MerchantConfig.getInstance().name,
      '{{BUSINESS_IG}}': instagramHandlesString,
      '{{TIKTOK_HASHTAGS}}': tiktokHashtagsString
    };
  }

  public static getRewardReplaceable(reward: Reward, labels: ContentSettings) {
    const {
      program_details_currency_plural_text: currencyPlural,
      program_details_currency_singular_text: currencySingular
    } = labels;
    const { points_to_be_redeemed: points } = reward;
    return {
      '{{POINTS}}': formatNumber(points),
      '{{POINTS_LABEL}}': pluralize(points, currencySingular, currencyPlural)
    };
  }

  public static getReplaceable(
    item: Activity | Reward | Tier,
    type: ValidCandidateForReplace,
    labels: ContentSettings
  ) {
    switch (type) {
      case 'activity':
        return this.getActivityReplaceable(item as Activity, labels);
      case 'reward':
        return this.getRewardReplaceable(item as Reward, labels);
      case 'tier':
        return this.getTierReplaceable(item as Tier, labels);
      default:
        return {};
    }
  }

  public static replaceNestedObject(item: any, replaceable: Replaceable) {
    Object.keys(item).forEach((key) => {
      if (Object.prototype.hasOwnProperty.call(item, key)) {
        const value = item[key as keyof typeof item];
        if (typeof value === 'string') {
          item[key as keyof typeof item] = replaceLabels(value, replaceable) as string;
        } else if (typeof value === 'object' && value !== null) {
          item[key as keyof typeof item] = this.replaceNestedObject(value, replaceable);
        } else {
          item[key as keyof typeof item] = value; // Preserve non-string, non-object values
        }
      }
    });
    return item;
  }

  public static replaceVariables(
    data: Activity[] | Reward[] | Tier[],
    type: ValidCandidateForReplace
  ) {
    const labelConfig = EUDSettings.getInstance().content_settings;

    return data.map((item) => {
      try {
        const replaceable = this.getReplaceable(item, type, labelConfig);
        this.replaceNestedObject(item, replaceable);
      } catch (error) {
        // eslint-disable-next-line no-console
        console.error(error);
      }
      return item;
    });
  }

  public static replaceTierBenefitDescriptionText(
    text: string,
    requiredUnitsForNextTier: number,
    nextTierName: string | undefined
  ) {
    const {
      program_details_currency_plural_text: currencyPlural,
      program_details_currency_singular_text: currencySingular
    } = EUDSettings.getInstance().content_settings;
    const { storeCurrencySymbol, tierQualificationCriteria } = MerchantConfig.getInstance();
    const formatOptions =
      tierQualificationCriteria === TIER_QUALIFICATION_SPEND_BASED
        ? {
            maximumFractionDigits: 2
          }
        : undefined;
    return replaceLabels(text, {
      '{{POINTS_REMAINING_TO_REACH_NEXT_TIER}}': formatNumber(
        requiredUnitsForNextTier,
        undefined,
        formatOptions
      )?.toString(),
      '{{UNITS_REMAINING_TO_REACH_NEXT_TIER}}': formatNumber(
        requiredUnitsForNextTier,
        undefined,
        formatOptions
      )?.toString(),
      '{{POINTS_LABEL}}': pluralize(requiredUnitsForNextTier, currencySingular, currencyPlural),
      '{{NEXT_TIER_NAME}}': nextTierName,
      '{{CURRENCY_SYMBOL}}': storeCurrencySymbol
    });
  }

  public static getPointsExpirationReplaceable(
    pointsExpirationSchedule: PointsExpirationSchedule[]
  ): Replaceable {
    const {
      program_details_currency_plural_text: currencyPlural,
      program_details_currency_singular_text: currencySingular
    } = EUDSettings.getInstance().content_settings;

    const { display_date_format: displayDateFormat } = EUDSettings.getInstance();
    const pointsExpiration = pointsExpirationSchedule.length
      ? pointsExpirationSchedule[0]
      : undefined;
    return {
      '{{POINTS_LABEL}}': pluralize(pointsExpiration?.points, currencySingular, currencyPlural),
      '{{POINTS_TO_EXPIRE}}': formatNumber(pointsExpiration?.points),
      '{{POINTS_EXPIRY_DATE}}': formatDateString(
        pointsExpiration?.expiration_date,
        displayDateFormat
      )
    };
  }

  public static replaceTierValidityExpiryText(
    text: string,
    currentTier: string,
    expiryDate: string | undefined
  ) {
    const { display_date_format: displayDateFormat } = EUDSettings.getInstance();
    return replaceLabels(text, {
      '{{CONDITIONAL_TIER_END_DATE}}': formatDateString(expiryDate, displayDateFormat),
      '{{CURRENT_TIER_NAME}}': currentTier
    });
  }
}
