import fetch from 'cross-fetch'
import qs from 'qs'
import { ZinreloErrors, ZinreloRegex } from '@root/constants'
import { ApiClientType, ClientConfig } from './types'
import { ZinreloErrorType } from '@root/constants/types'
import { convertObjectValuesToString, isEmpty } from '@root/utils'

export class ApiClient {
  baseUrl?: string
  authToken?: string
  partnerId: string
  apiVersion?: string
  language?: string

  constructor(config: ApiClientType) {
    this.baseUrl = config?.baseUrl ?? 'https://api.zinrelo.com'
    this.authToken = config?.authToken
    if (!config?.partnerId) {
      ZinreloErrors.throwErrorHelper(ZinreloErrors.PARTNER_ID_MISSING)
    }
    this.partnerId = config?.partnerId
    this.apiVersion = config?.apiVersion || 'v2'
    this.language = config?.language
  }

  public getApiUrl(): string {
    return `${this.baseUrl}/${this.apiVersion}/loyalty-storefront`
  }

  public async execute(config: ClientConfig) {
    try {
      let headers: Record<string, string> = {
        'partner-id': this.partnerId,
      }

      headers = config.headers ? (config.mergeHeaders ? { ...headers, ...config.headers } : config.headers) : headers

      headers['zrl-sdk-version'] = ZINRELO_HEADER_SDK_VERSION
      headers['zrl-sdk-name'] = ZINRELO_HEADER_SDK_NAME
      if (config.passToken) {
        if (this.authToken) {
          headers['access-token'] = this.authToken
        } else {
          ZinreloErrors.throwErrorHelper(ZinreloErrors.AUTH_TOKEN_MISSING)
        }
      }

      // Extract options, with defaults, from config.

      const contentType = config.contentType || null
      const method = config.method || null

      const params = this.buildQueryParams(config.params)
      const json = config.data || null

      const fetchUrl = params ? `${config.url}?${params}` : config.url
      let fetchMethod = 'get'
      let fetchBody = null

      if (json) {
        headers['content-type'] = contentType || 'application/json'
        fetchMethod = method || 'post'
        fetchBody = JSON.stringify(json)
      }

      const response = await fetch(fetchUrl, {
        method: fetchMethod,
        headers: headers,
        body: fetchBody,
      })
      const data = await this.unwrapResponseData(response)
      if (response.ok) {
        if (data?.success === false && data?.error_code && data?.reason) {
          return Promise.reject(this.normalizeError(data))
        }

        return data
      }

      return Promise.reject(this.normalizeError(data))
    } catch (error) {
      // The request failed in a critical way; the content of this error will be
      // entirely unpredictable.
      return Promise.reject(this.normalizeError(error as ZinreloErrorType))
    }
  }

  /**
   * unwrap the response payload from the given response based on the reported
   * content-type.
   */
  private async unwrapResponseData(response: Response) {
    const contentType = (response.headers.has('content-type') ? response.headers.get('content-type') : '') as string

    if (ZinreloRegex.CONTENT_TYPE_JSON.test(contentType)) {
      return response.json()
    } else if (ZinreloRegex.CONTENT_TYPE_TEXT.test(contentType)) {
      return response.text()
    } else {
      return response.blob()
    }
  }

  /**
   * At a minimum, we want every error to have "type" and "message" properties. These
   * are the two keys that the calling context will depend on; and, are the minimum keys
   * that the server is expected to return when it throws domain errors.
   */
  private normalizeError(data: ZinreloErrorType) {
    if (data?.cause && data?.type && data?.message) {
      return data
    } else {
      const error = ZinreloErrors.API_CLIENT_SERVER_UNEXPECTED_ERROR_MESSAGE
      error.cause = data
      return error
    }
  }

  private buildQueryParams(params: Record<string, unknown> | null = null): string | null {
    let returnValue = {}

    if (params) {
      returnValue = convertObjectValuesToString({ ...params }) as Record<string, unknown>
    }

    if (this.language) {
      returnValue = { language: this.language, ...returnValue }
    }

    return !isEmpty(returnValue) ? qs.stringify(returnValue) : null
  }
}
