  --bg-color: var(--zrl-input-bg-color);
  --active-bg-color: var(--zrl-button-primary-color-bg);
  background-color: var(--bg-color);
  border: var(--zrl-input-border);
  max-height: inherit;
  overflow-y: auto;
}

.styled-calendar * {
  background-color: transparent;
  border: none;
  font-weight: var(--zrl-text-bold-font-weight);
  font-family: var(--zrl-global-body-font-family);
  color: inherit;
}

/* styles for all the tiles */
.styled-calendar .react-calendar__tile {
  background-color: var(--zrl-global-color-bg);
  border: 1.5px solid var(--bg-color);
  border-radius: 6px;
}

/* styles override for other month dates*/
.styled-calendar .react-calendar__month-view__days__day--neighboringMonth {
  background-color: var(--bg-color);
}

.styled-calendar .react-calendar__tile:enabled:hover {
  background-color: var(--active-bg-color);
  color: var(--zrl-button-primary-text-color);
}

.styled-calendar .react-calendar__navigation button:enabled:hover,
.styled-calendar .react-calendar__navigation button:enabled:focus {
  background-color: transparent;
  background-color: initial;
}

.styled-calendar .react-calendar__month-view__weekdays,
.styled-calendar .react-calendar__month-view__weekdays abbr {
  text-decoration: none;
  text-transform: none;
}

.styled-calendar .react-calendar__month-view__weekdays abbr {
  font-size: 1.2em;
}

.react-calendar__navigation__prev2-button,
.react-calendar__navigation__next2-button {
  display: none;
}

.styled-calendar .react-calendar__month-view__days__day--weekend{
  color: var(--zrl-text-muted-color);
}

.styled-calendar::-webkit-scrollbar {
  width: 14px;
  width: var(--zrl-scroll-width, 14px);
}

.styled-calendar::-webkit-scrollbar-thumb {
  border: 4px solid rgba(0, 0, 0, 0);
  border: var(--zrl-scroll-border, 4px solid rgba(0, 0, 0, 0));
  background-clip: padding-box;
  background-clip: var(--zrl-scroll-bg-clip, padding-box);
  border-radius: 9999px;
  border-radius: var(--zrl-scroll-border-radius, 9999px);
  background-color: #AAAAAA;
  background-color: var(--zrl-scroll-bg-color, #AAAAAA);
}

.styled-calendar .react-calendar__tile--active {
  background: var(--active-bg-color) !important;
  color: var(--zrl-button-primary-text-color);
