import { Card, Stack, Image, Button, Typography } from '@trueloyal-engineering/react-ui';
import { ChevronRight as ChevronRightIcon } from '@root/icons';
import { EUDSettings, MerchantConfig } from '@root/core/config';
import { formatNumber } from '@root/core/utils/textUtils';
import { PointsExpirationSchedule } from '@trueloyal-engineering/ui-api-sdk';
import { MemberPointsExpirationBanner, MemberNegativePointsBanner } from '@root/containers';
import { MemberHelper } from '@root/core/helpers';
import styles from './main.module.css';

export interface MainProps {
  points: number;
  pointsExpirationSchedule: PointsExpirationSchedule[];
  gotoPointsHistory?: () => void;
}

export function Main({ points, pointsExpirationSchedule, gotoPointsHistory }: MainProps) {
  const {
    content_settings: {
      program_details_currency_plural_text: currencyPlural,
      program_details_currency_singular_text: currencySingular
    },
    points_image_url: pointsImageURL
  } = EUDSettings.getInstance();

  const currency = {
    plural: currencyPlural,
    singular: currencySingular
  };
  const shouldShowExpiryBanner = MemberHelper.isExpiryNearThreshold(pointsExpirationSchedule);
  const shouldShowNegativePointsBanner =
    MerchantConfig.getInstance().negativePointsAllowed && points < 0;

  return (
    <Card.Section role="region" aria-label="Member points history" className="member-card__main">
      <Stack>
        <Stack orientation="horizontal" align="center" justify="center" gap={1.2}>
          <Image src={pointsImageURL} width="45px" role="presentation" />
          <Stack gap={0.5}>
            <Button
              id="points-btn"
              onClick={gotoPointsHistory}
              mono
              iconAlignment="right"
              icon={
                <ChevronRightIcon className="zrl-icon zrl-icon--flip-on-rtl" fontSize="small" />
              }
              aria-label="Go To Points History"
              className={styles['member-card__points-cta']}
            >
              {currency.plural}
            </Button>
            <Typography
              variant="bodyXl"
              fontWeight="bold"
              aria-description="Available Points"
              className={styles['member-card__points']}
            >
              {formatNumber(points)}
            </Typography>
          </Stack>
        </Stack>
        {shouldShowNegativePointsBanner && <MemberNegativePointsBanner />}
        {shouldShowExpiryBanner && (
          <MemberPointsExpirationBanner
            pointsExpirationSchedule={pointsExpirationSchedule}
            isClickable
          />
        )}
      </Stack>
    </Card.Section>
  );
}
