import { Activity, ActivityExtraConfig } from '@trueloyal-engineering/ui-api-sdk';
import { EUDSettings } from '@root/core/config';
import { ERROR_CODES_TO_FIELD_MAPPING } from '../constants/error.constants';

export class ErrorHandler {
  public static resolveActivityErrorMessage(activity: Activity, error: any) {
    let errorMessage =
      EUDSettings.getInstance().content_settings.commons_error_message_general_text;
    if (
      error.type === 'SERVER_ERROR' &&
      activity.extra_config &&
      error?.cause &&
      Object.prototype.hasOwnProperty.call(ERROR_CODES_TO_FIELD_MAPPING, error.cause.error_code)
    ) {
      const errorCause = error.cause;
      const activityErrorMessage =
        activity.extra_config[
          ERROR_CODES_TO_FIELD_MAPPING[
            errorCause.error_code as keyof typeof ERROR_CODES_TO_FIELD_MAPPING
          ] as keyof ActivityExtraConfig
        ];
      if (activityErrorMessage && activityErrorMessage !== null && activityErrorMessage !== '') {
        errorMessage = String(activityErrorMessage);
      }
    }

    return errorMessage;
  }

  public static resolveErrorMessage(_error: any) {
    return EUDSettings.getInstance().content_settings.commons_error_message_general_text;
  }

  public static resolveErrorMessageFromErrorMapping(
    error: any,
    errorMapping?: Record<string, string>
  ): string {
    const defaultMessage =
      EUDSettings.getInstance().content_settings.commons_error_message_general_text;

    if (
      errorMapping &&
      error.cause &&
      Object.prototype.hasOwnProperty.call(errorMapping, error.cause.error_code)
    ) {
      return errorMapping[error.cause.error_code];
    }
    return defaultMessage;
  }
}
