import { ApiClient } from '@root/core/api';
import {
  MethodArgsWithoutQueryParams,
  Reward,
  RewardsInputData
} from '@trueloyal-engineering/ui-api-sdk';
import { LOYALTY_REDEMPTION_FLEXIBLE_POINTS_REWARD } from '@root/core/constants/reward.constants';
import { formatNumber, pluralize } from '@root/core/utils/textUtils';
import { EUDSettings } from '@root/core/config';

export class RewardHelper {
  public static async redeem(rewardId: string) {
    const apiClient = ApiClient.getInstance();
    const input: MethodArgsWithoutQueryParams<RewardsInputData> = {
      data: {
        reward_id: rewardId
      }
    };
    const response = await apiClient.transactions.redeem(input);
    return response;
  }

  public static getTagLabelText(reward: Reward, points: number) {
    const isFlexiblePointsReward =
      reward.reward_sub_type === LOYALTY_REDEMPTION_FLEXIBLE_POINTS_REWARD;
    const {
      program_details_currency_plural_text: currencyPlural,
      program_details_currency_singular_text: currencySingular
    } = EUDSettings.getInstance().content_settings;
    if (!isFlexiblePointsReward) {
      const pointsLabelText = pluralize(points, currencySingular, currencyPlural);
      const tagLabelText = `${formatNumber(points)} ${pointsLabelText}`;
      return tagLabelText;
    }
    const minPoints = reward.extra_parameters?.minimum_redemption_limit;
    const maxPoints = reward.extra_parameters?.maximum_redemption_limit;
    const pointsLabelText = pluralize(minPoints, currencySingular, currencyPlural);
    let tagLabelText = `${formatNumber(minPoints)}+ ${pointsLabelText}`;
    if (maxPoints) {
      tagLabelText = `${formatNumber(minPoints)} ${pointsLabelText} - ${formatNumber(
        maxPoints
      )} ${pointsLabelText}`;
    }
    return tagLabelText;
  }
}
