export class UIHelpers {
  public static isIOS() {
    try {
      return /ipad|iphone|ipod/i.test(navigator.userAgent);
    } catch (error) {
      // eslint-disable-next-line no-console
      console.error(error);
      return false;
    }
  }

  public static openPopup(
    url: string,
    popupName: string,
    popupFeatures: string,
    onClose: () => void
  ) {
    const popup = window.open(url, popupName, popupFeatures);
    if (this.isIOS()) {
      // On iOS, popups may not work as expected when the URL opens its equivalent app
      onClose();
      return;
    }
    const intervalId = setInterval(() => {
      if (popup && popup.closed) {
        clearInterval(intervalId);
        onClose();
      }
    }, 1000);
  }

  public static copyToClipboard(text: string | undefined, callback: () => void) {
    if (text && window.isSecureContext) {
      navigator.clipboard.writeText(text);
      callback();
    }
  }

  public static convertHtmlEntityToCharacter(htmlEntity: string): string {
    const tempElement = document.createElement('div');
    tempElement.innerHTML = htmlEntity;
    return tempElement.textContent || tempElement.innerText;
  }
}
