import { Member, PointsExpirationSchedule } from '@trueloyal-engineering/ui-api-sdk';
import { isDateWithinDays } from '../utils/dateUtils';
import { EUDSettings, IntegrationSettings } from '../config';
import { ACTIVITY_TYPE } from '../constants/activity.constants';

export class MemberHelper {
  public static getName(member: Member | undefined) {
    if (!member) return '';
    if (member.first_name) return member.first_name;
    if (member.last_name) return member.last_name;
    if (member.email_address) return member.email_address;
    if (member.member_id) return member.member_id;
    return '';
  }

  public static getFullName(member: Member | undefined) {
    if (!member) return '';
    const nameCandidates = [member.first_name, member.last_name].filter(Boolean);
    return nameCandidates.length > 0
      ? nameCandidates.join(' ')
      : member.email_address || member.member_id;
  }

  public static isExpiryNearThreshold(pointsExpirationSchedule: PointsExpirationSchedule[]) {
    const { points_expiry_alert_trigger_before_days: pointsExpirationNotificationThresholdDays } =
      EUDSettings.getInstance();
    return (
      pointsExpirationSchedule.length > 0 &&
      isDateWithinDays(
        new Date(pointsExpirationSchedule[0].expiration_date),
        pointsExpirationNotificationThresholdDays
      )
    );
  }

  public static getUserHandle(member: Member | undefined, activity_type: 'instagram' | 'tiktok') {
    if (!member) return '';
    return activity_type === ACTIVITY_TYPE.INSTAGRAM
      ? member.instagram_handle
      : member.tiktok_handle;
  }

  public static getBusinessHandle(platform: 'instagram' | 'tiktok') {
    const integrationSettings = IntegrationSettings.getInstance();

    if (platform === ACTIVITY_TYPE.INSTAGRAM) {
      return integrationSettings.business_instagram_handles || [];
    }

    if (platform === ACTIVITY_TYPE.TIKTOK) {
      return integrationSettings.tiktok_hashtags || [];
    }

    return [];
  }
}
