import { Button, Stack, Image, Typography, Layout } from '@trueloyal-engineering/react-ui';
import { Reward, RewardTransaction, Transaction } from '@trueloyal-engineering/ui-api-sdk';
import { EUDSettings } from '@root/core/config';
import { CopyToClipboardInput } from '@root/components';
import { useAppNavigation } from '@root/hooks';
import { toast } from 'react-toastify';
import { sanitizeHTML } from '@root/core/utils/htmlUtils';
import styles from './reward-success.module.css';

export interface RewardSuccessProps {
  rewardTransaction: RewardTransaction | Transaction;
  reward: Reward;
}

export function RewardSuccess({ rewardTransaction, reward }: RewardSuccessProps) {
  const { gotoHome, gotoMemberRewards } = useAppNavigation();

  const {
    content_settings: {
      commons_copy_text_successful_text: copiedToastText,
      reward_details_page_congratulation_text: congratulationText,
      reward_details_page_redeem_more_button_label: redeemMoreButtonLabel,
      reward_details_page_goto_home_button_label: gotoHomeButtonLabel,
      commons_coupon_code_text: couponCodeText,
      commons_reward_link_text: rewardLinkText
    },
    reward_details_page_congratulations_image_url: imageURL,
    congratulations_confetti_url: confettiURL
  } = EUDSettings.getInstance();

  const rewardInfo = rewardTransaction.reward_info;
  const couponCode = rewardInfo && 'coupon_code' in rewardInfo ? rewardInfo.coupon_code : undefined;
  const rewardLink = rewardInfo && 'reward_link' in rewardInfo ? rewardInfo.reward_link : undefined;

  const { extra_parameters: extraParameters } = reward;

  const handleCopy = () => {
    toast.success(copiedToastText, { hideProgressBar: true, autoClose: 1000 });
  };

  const thankYouText = extraParameters?.points_deduction_text;

  return (
    <Layout className={styles['reward-success']} data-redemption_id={reward?.reward_id}>
      <Layout.Content centered className={styles['reward-success__content']}>
        <Stack justify="center" align="center" gap={2}>
          <Stack justify="center" align="center" gap={0.5}>
            <Image src={imageURL} role="presentation" className={styles['reward-success__image']} />
            <Typography as="h1" variant="header3xl" fontWeight="bold" align="center">
              {congratulationText}
            </Typography>
            <Typography
              muted
              fontWeight="thin"
              align="center"
              dangerouslySetInnerHTML={{ __html: sanitizeHTML(thankYouText) }}
            />
          </Stack>
          {couponCode && (
            <CopyToClipboardInput
              label={couponCodeText}
              value={couponCode}
              textAlign="center"
              borderStyle="dotted"
              onCopy={handleCopy}
            />
          )}
          {rewardLink && (
            <CopyToClipboardInput
              label={rewardLinkText}
              onClick={() => window.open(rewardLink, '_blank')}
              className={styles['reward-success__reward-link-input']}
              value={rewardLink}
              textAlign="center"
              borderStyle="dotted"
              onCopy={handleCopy}
            />
          )}
        </Stack>
        <img
          className={styles['reward-success__confetti']}
          src={confettiURL}
          alt="confetti"
          role="presentation"
        />
      </Layout.Content>
      <Layout.Footer>
        <Stack justify="center" align="center">
          <Button
            id="redeem-more-btn"
            fullWidthOnDeviceType="sm"
            primary
            relaxed
            onClick={gotoMemberRewards}
            btnSize="large"
          >
            {redeemMoreButtonLabel}
          </Button>
          <Button
            id="goto-home-btn"
            fullWidthOnDeviceType="sm"
            relaxed
            onClick={gotoHome}
            btnSize="large"
          >
            {gotoHomeButtonLabel}
          </Button>
        </Stack>
      </Layout.Footer>
    </Layout>
  );
}
