import { Button, Carousel, CarouselProps, Typography } from '@trueloyal-engineering/react-ui';
import { EUDSettings } from '@root/core/config';
import { RewardCard } from '@root/core/presets';
import { SkeletonCarouselSlides } from '@root/components';
import { useAppSelector } from '@root/store';
import { selectRewards } from '@root/store/slices/rewardSlice';
import { useAppNavigation } from '@root/hooks';
import styles from './reward-carousel.module.css';

export interface RewardCarouselProps extends CarouselProps {
  isGuest: boolean;
}

export function RewardCarousel({ isGuest, ...carouselProps }: RewardCarouselProps) {
  const requestActivitiesFor = isGuest ? 'guest' : 'member';
  const rewards = useAppSelector((state) => selectRewards(state, requestActivitiesFor));
  const availablePoints =
    useAppSelector((state) => state.member.memberDetails?.available_points) ?? 0;
  const status = useAppSelector((state) => state.reward.status);

  const { gotoGuestRewards, gotoMemberRewards, gotoMemberReward } = useAppNavigation();
  const gotoRewardList = isGuest ? gotoGuestRewards : gotoMemberRewards;

  const {
    reward_section_pagination_label: carouselViewAllButtonText,
    reward_section_loggedin_empty_state_message: noRewardsLoggedInMessage,
    reward_section_guest_empty_state_message: noRewardsGuestMessage,
    reward_section_header_text: header
  } = EUDSettings.getInstance().content_settings;

  const noRewardsMessage = isGuest ? noRewardsGuestMessage : noRewardsLoggedInMessage;

  const loading = ['pending', 'idle'].includes(status);

  return (
    <Carousel className="reward-carousel" aria-label={`${header} Carousel`} {...carouselProps}>
      <Carousel.Header>
        <Typography variant="headerXl" fontWeight="bold" titled trunc={1} title={header}>
          {header}
        </Typography>
      </Carousel.Header>
      {loading && <SkeletonCarouselSlides />}
      {!loading && rewards && rewards?.length > 0 && (
        <>
          <Carousel.Slides>
            {rewards.map((reward) => {
              return (
                <RewardCard
                  key={reward.reward_id}
                  reward={reward}
                  className={styles['reward-carousel__reward-card']}
                  readOnly={isGuest}
                  availablePoints={availablePoints}
                  onAction={() => gotoMemberReward(reward.reward_id)}
                />
              );
            })}
          </Carousel.Slides>
          <Carousel.Footer>
            <Button
              relaxed
              fullWidthOnDeviceType="sm"
              onClick={gotoRewardList}
              id="view-rewards-btn"
            >
              {`${carouselViewAllButtonText} (${rewards.length})`}
            </Button>
          </Carousel.Footer>
        </>
      )}
      {!loading && (!rewards || !rewards.length) && (
        <Typography muted align="center">
          {noRewardsMessage}
        </Typography>
      )}
    </Carousel>
  );
}
