import { AuthConfig, MerchantConfig } from '@root/core/config';
import { TierHelper } from '@root/core/helpers';
import { useAppDispatch, useAppSelector } from '@root/store';
import { fetchAllActivities, fetchEligibleActivities } from '@root/store/slices/activitySlice';
import { setMember, setNextTier } from '@root/store/slices/memberSlice';
import { fetchAllRewards, fetchEligibleRewards } from '@root/store/slices/rewardSlice';
import { fetchAllTiers } from '@root/store/slices/tierSlice';
import {
  GetActivitiesQueryParams,
  GetAllRewardsQueryParams,
  GetRewardsQueryParams
} from '@trueloyal-engineering/ui-api-sdk';
import { useEffect } from 'react';
import { fetchAllStreaks } from '@root/store/slices/streakSlice';
import { useStreakUserProgress } from './useStreakUserProgress';

export interface IUseInitializeStore {
  shouldLoadInitialState: boolean;
}

export function useInitializeStore({ shouldLoadInitialState }: IUseInitializeStore) {
  const dispatch = useAppDispatch();

  const member = useAppSelector((state) => state.member.memberDetails);
  const tiers = useAppSelector((state) => state.tier.tiers);
  const { enableStreaks } = MerchantConfig.getInstance();

  const activityQueryParams: GetActivitiesQueryParams = {
    sort_by: 'rank,created_date',
    sign_activity: true
  };

  const initializeGuestState = () => {
    const allRewardsQueryParams: GetAllRewardsQueryParams = {
      sort_by: 'rank,points_to_be_redeemed'
    };
    dispatch(fetchAllRewards(allRewardsQueryParams));
    dispatch(fetchAllActivities(activityQueryParams));
    dispatch(fetchAllTiers());
    if (enableStreaks) {
      dispatch(fetchAllStreaks());
    }
  };

  const initializeMemberState = () => {
    const { memberInfo } = AuthConfig.getInstance();
    dispatch(setMember(memberInfo));

    if (!AuthConfig.isMemberActive()) return;

    const eligibleRewardsQueryParams: GetRewardsQueryParams = {
      ignore_allowed_redeem_points: true,
      sort_by: 'rank,points_to_be_redeemed'
    };
    dispatch(fetchEligibleActivities(activityQueryParams));
    dispatch(fetchEligibleRewards(eligibleRewardsQueryParams));
    dispatch(fetchAllTiers());
    if (enableStreaks) {
      dispatch(fetchAllStreaks());
    }
  };

  const initializeAppState = () => {
    if (AuthConfig.isPreview()) {
      initializeGuestState();
      initializeMemberState();
      return;
    }
    if (!AuthConfig.isAuthenticated()) {
      initializeGuestState();
      return;
    }
    initializeMemberState();
  };

  const initializeNextTier = () => {
    if (member?.tier_info && tiers) {
      dispatch(setNextTier(TierHelper.getNextTier(member.tier_info.loyalty_tier_id, tiers)));
    }
  };

  useEffect(() => {
    if (!shouldLoadInitialState) return;
    initializeAppState();
  }, [shouldLoadInitialState]);

  useEffect(() => {
    initializeNextTier();
  }, [member, tiers]);

  if (shouldLoadInitialState && enableStreaks && AuthConfig.isAuthenticated()) {
    useStreakUserProgress();
  }

  return {
    initializeAppState,
    initializeGuestState,
    initializeMemberState
  };
}
