import { ChevronRight } from '@root/icons';
import { EUDSettings } from '@root/core/config';
import { Button, Stack, Typography, Image } from '@trueloyal-engineering/react-ui';
import { MemberHelper } from '@root/core/helpers/member';
import { useAppSelector } from '@root/store';
import { useAppNavigation } from '@root/hooks';
import { replaceLabels } from '@root/core/utils/textUtils';
import styles from './member-overview.module.css';

export function MemberOverview() {
  const member = useAppSelector((state) => state.member.memberDetails);
  const {
    content_settings: {
      program_details_program_name: programName,
      dashboard_header_section_view_profile_button_label: viewProfileButtonLabel,
      dashboard_header_section_greeting_text: greetingText,
      dashboard_header_section_welcome_text: welcomeText
    },
    avatar_url: avatar
  } = EUDSettings.getInstance();

  const { gotoMemberProfile } = useAppNavigation();

  const memberName = MemberHelper.getName(member);
  const greetingMessage = replaceLabels(greetingText, {
    '{{USER_NAME}}': memberName
  });
  const welcomeMessage = replaceLabels(welcomeText, {
    '{{PROGRAM_NAME}}': programName
  });
  return (
    <div className={styles['member-overview']} aria-label="Member Profile Overview">
      <Stack orientation="horizontal" className={styles['member-overview__wrapper']}>
        <Image
          circular
          className={styles['member-overview__avatar']}
          src={avatar}
          alt="Avatar"
          role="presentation"
        />
        <div className={styles['member-overview__section']}>
          <Stack gap={0.2}>
            <Typography
              variant="bodySm"
              className={styles['member-overview__name']}
              trunc={1}
              title={greetingMessage}
            >
              {greetingMessage},
            </Typography>
            <Typography
              fontWeight="bold"
              className={styles['member-overview__welcome-message']}
              trunc={3}
              title={welcomeMessage}
            >
              {welcomeMessage}
            </Typography>
          </Stack>
          <Button
            className={styles['member-overview__view-profile-btn']}
            id="view-profile-btn"
            btnSize="small"
            icon={<ChevronRight className="zrl-icon zrl-icon--flip-on-rtl" fontSize="small" />}
            iconAlignment="right"
            onClick={gotoMemberProfile}
            aria-label="Go to Member Profile"
          >
            {viewProfileButtonLabel}
          </Button>
        </div>
      </Stack>
    </div>
  );
}
