import { OPERATORS } from '@root/core/constants/operator.constants';
import { STREAK_SLUG } from '@root/core/constants/streak.constants';
import { QueryBuilder } from '@root/core/helpers/querybuilder';
import { ListQueryParams, useAppDispatch, useAppSelector } from '@root/store';
import { Streak } from '@root/store/slices/streakSlice';
import { fetchStreakUserProgress } from '@root/store/slices/streakUserProgressSlice';
import { shouldFetchStreakUserProgress } from '@root/utils/gamification';
import { useEffect } from 'react';

export function useStreakUserProgress() {
  const dispatch = useAppDispatch();
  const member = useAppSelector((state) => state.member.memberDetails);
  const streaks = useAppSelector((state) => state.streak.streaks);
  const streakUserProgress = useAppSelector((state) => state.streakUserProgress.streakUserProgress);

  useEffect(() => {
    if (shouldFetchStreakUserProgress(member, streaks, streakUserProgress)) {
      const dataFilters: ListQueryParams = {
        query: QueryBuilder.buildQueryForCondsArrayWithAndOp([
          {
            field_slug: 'linked_schema_slug',
            operator: OPERATORS.EQUALS,
            field_value: STREAK_SLUG
          },
          {
            field_slug: 'linked_schema_record_id',
            operator: OPERATORS.IN,
            field_value: streaks?.map((streak: Streak) => streak.id)
          }
        ])
      };
      dispatch(fetchStreakUserProgress(dataFilters));
    }
  }, [member, streaks, streakUserProgress]);
}
