.footer-container{
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  background-color: white;
}

.line-separator {
  margin-bottom: 1rem;
  width: 99%;
  align-self: center;
}

.footer-handle__container {
  display: flex;
  align-items: center;
  margin-bottom: 1rem;
}

.footer-user-handle__icon {
  margin-right: 0.5rem;
}

.footer {
  width: 100%;
}

.gatsby-social-activity__edit-modal {
  padding: 3rem;
  gap: 2rem;
}

.footer-display-text__wrapper{
  margin-left: 32px;
  padding-top: 0px;
}

.footer-handle__container {
  position: relative;
}

.social-share-activity__edit-button {
  margin-left: 8px;
}

.social-layout-container {
  padding-bottom: 10rem;
}

@media (max-width: 48em) {
  .footer-handle__container {
    align-items: flex-start;
  }

  .social-share-activity__edit-button {
    position: absolute;
    top: 0;
    right: 0;
    margin-left: 0; 
  }

  .line-separator {
    width: 100%; 
    height: 1px;
    border-top: 1px solid #ddd;
    box-shadow: 0px -2px 12px rgba(0, 0, 0, 0.15);
    margin-bottom: 1.5rem; 
  }

  .gatsby-social-activity__edit-modal {
    padding-left: 20px;
    padding-right: 20px;
  }

  .footer-container{
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    background-color: white;
    padding: 0px 20px 40px;
  }
}

.footer-handle__text {
  max-width: calc(100% - 80px);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.footer-main-container {
  padding: 0px;
