/* eslint-disable no-param-reassign */
import {
  PayloadAction,
  createAsyncThunk,
  createSelector,
  createSlice,
  isAnyOf
} from '@reduxjs/toolkit';
import { ApiClient } from '@root/core/api';
import { Member, Tier, UpdateMemberInputData } from '@trueloyal-engineering/ui-api-sdk';
import { CommonState, CommonThunkError } from '@root/store/types';
import { EUDSettings } from '@root/core/config';
import { ErrorHandler } from '@root/core/helpers/error';
import { RootState } from '@root/store';
import { formatDateString } from '@root/core/utils/dateUtils';
import { formatNumber } from '@root/core/utils/textUtils';
import { toast } from 'react-toastify';
import { FormattedPointsExpirationScheduleDatumType } from './types';

export interface MemberState extends CommonState {
  memberDetails: Member | undefined;
  nextTier?: Tier;
}

export const fetchMember = createAsyncThunk<
  Member | undefined,
  void,
  { rejectValue: CommonThunkError }
>('member/fetchMember', async (_, { rejectWithValue }) => {
  try {
    const apiClient = ApiClient.getInstance();
    const response = await apiClient.members.getMember();
    if (!response.success) {
      return rejectWithValue({
        errorMessage: EUDSettings.getInstance().content_settings.commons_error_message_general_text
      });
    }
    return response.data;
  } catch (error) {
    return rejectWithValue({
      errorMessage: EUDSettings.getInstance().content_settings.commons_error_message_general_text
    });
  }
});

type ThunkUpdateMemberPayload = {
  updateParams: UpdateMemberInputData & { custom_attributes?: Record<string, string> };
  errorMapping?: Record<string, string>;
};

export const updateMember = createAsyncThunk<
  Member | undefined,
  ThunkUpdateMemberPayload,
  { rejectValue: CommonThunkError }
>('member/updateMember', async ({ updateParams, errorMapping }, { rejectWithValue }) => {
  try {
    const apiClient = ApiClient.getInstance();
    const input = { data: updateParams };
    const response = await apiClient.members.updateMember(input);
    return response;
  } catch (error) {
    let errorMessage = ErrorHandler.resolveErrorMessageFromErrorMapping(error, errorMapping);
    toast.error(errorMessage);
    errorMessage = '';
    return rejectWithValue({ errorMessage });
  }
});

const initialState: MemberState = {
  memberDetails: undefined,
  status: 'idle',
  errorMessage: ''
};

export const memberSlice = createSlice({
  name: 'member',
  initialState,
  reducers: {
    setMember: (state, action: PayloadAction<Member | undefined>) => {
      state.memberDetails = action.payload;
    },
    setNextTier: (state, action: PayloadAction<Tier | undefined>) => {
      state.nextTier = action.payload;
    }
  },
  extraReducers: (builder) => {
    builder.addMatcher(isAnyOf(fetchMember.fulfilled, updateMember.fulfilled), (state, action) => {
      state.status = 'succeeded';
      state.memberDetails = action.payload as Member;
    });
    builder.addMatcher(isAnyOf(fetchMember.pending, updateMember.pending), (state, _) => {
      state.status = 'pending';
    });
    builder.addMatcher(isAnyOf(fetchMember.rejected, updateMember.rejected), (state, action) => {
      state.status = 'failed';
      state.errorMessage = action.payload?.errorMessage ?? 'Unknown Error';
    });
  }
});

// Action creators are generated for each case reducer function
export const { setMember, setNextTier } = memberSlice.actions;

export default memberSlice.reducer;

/* ---------- SELECTORS ----------- */
export const selectMemberPointsExpirationSchedule = (state: RootState) =>
  state.member.memberDetails?.points_expiration_schedule;
export const selectFormattedPointsExpirationSchedule = createSelector(
  [selectMemberPointsExpirationSchedule],
  (pointsExpirationSchedule) => {
    const { display_date_format: displayDateFormat } = EUDSettings.getInstance();
    return pointsExpirationSchedule?.map<FormattedPointsExpirationScheduleDatumType>((datum) => ({
      expirationDate: formatDateString(datum.expiration_date, displayDateFormat),
      points: formatNumber(datum.points)
    }));
  }
);
