import React from 'react';
import {
  Button,
  Card,
  CardProps,
  Image,
  Stack,
  Tag,
  Typography,
  classNames
} from '@trueloyal-engineering/react-ui';
import { Activity } from '@trueloyal-engineering/ui-api-sdk';
import { formatNumber, pluralize } from '@root/core/utils/textUtils';
import { EUDSettings } from '@root/core/config';
import styles from './activity-card.module.css';

export interface ActivityCardProps extends CardProps {
  activity: Activity;
  readOnly?: boolean;
  className?: string;
  onAction?: () => void;
}

export function ActivityCard({
  activity,
  readOnly = true,
  onAction,
  className,
  ...cardProps
}: ActivityCardProps) {
  const {
    program_details_currency_plural_text: currencyPlural,
    program_details_currency_singular_text: currencySingular
  } = EUDSettings.getInstance().content_settings;

  const {
    icon_image_url: imageUrl,
    activity_name: name,
    enduser_activity_short_description: description,
    points_config: pointsConfig,
    earnpoints_button_label: earnPointsButtonLabel
  } = activity;

  const isMultiplierBasedActivity = pointsConfig.points_computation_type === 'multiplier_based';
  const points = isMultiplierBasedActivity ? pointsConfig.multiplier : pointsConfig.points;

  const pointsLabelText = pluralize(points, currencySingular, currencyPlural);
  const tagLabelText = `${formatNumber(points)} ${pointsLabelText}`;

  const classes = classNames(!readOnly && styles['activity-card--clickable'], className);

  return (
    <Card
      role="region"
      aria-label="Activity Information"
      className={classes}
      onClick={!readOnly ? onAction : undefined}
      data-activity_id={activity.activity_id}
      {...cardProps}
    >
      <Stack padding={1} align="center">
        <Image
          loading="lazy"
          src={imageUrl as string}
          className={styles['activity-card__image']}
          alt={name}
          fit="cover"
        />
        <Stack gap={0.2} align="center">
          <Typography trunc={2} align="center" title={name}>
            {name}
          </Typography>
          <Typography
            variant="bodySm"
            align="center"
            fontWeight="thin"
            muted
            trunc={2}
            title={description}
          >
            {description}
          </Typography>
        </Stack>
        {readOnly ? (
          <Tag className={styles['activity-card__points-tag']} label={tagLabelText} primary />
        ) : (
          <Button id={`view-${activity.activity_id}-btn`} primary fullWidthOnDeviceType="all">
            {earnPointsButtonLabel}
          </Button>
        )}
      </Stack>
    </Card>
  );
}
