import { Stack, Button, InputField, Layout } from '@trueloyal-engineering/react-ui';
import { Activity } from '@trueloyal-engineering/ui-api-sdk';
import { ActivityHeader, LoadMask } from '@root/components';
import { useEnterCodeActivity } from '@root/hooks';
import { AuthConfig } from '@root/core/config';
import { ActivitySuccess } from '../ActivitySuccess';
import styles from './enter-code-activity.module.css';

export interface EnterCodeActivityProps {
  activity: Activity;
}

export function EnterCodeActivity({ activity }: EnterCodeActivityProps) {
  const {
    enduser_activity_short_description: shortDescription,
    earnpoints_button_label: tagLabel,
    extra_config: extraConfig
  } = activity;

  const { loading, showCongratulation, code, handleChange, submitCode } = useEnterCodeActivity({
    activity
  });

  if (showCongratulation) {
    return <ActivitySuccess activity={activity} />;
  }

  const isPreview = AuthConfig.isPreview();
  const description = extraConfig?.reward_instruction_text;
  const placeholderText = extraConfig?.placeholder_text;
  const submitButtonText = extraConfig?.submit_button_text;

  return (
    <Layout className="enter-code-activity">
      {loading && <LoadMask />}
      <Layout.Content>
        <Stack>
          <ActivityHeader tagLabel={tagLabel} title={shortDescription} description={description} />
          <InputField
            className={styles['enter-code-activity__input']}
            value={code}
            onChange={handleChange}
            placeholder={placeholderText}
          />
        </Stack>
      </Layout.Content>
      <Layout.Footer>
        <Button
          id="submit-code-btn"
          fullWidthOnDeviceType="sm"
          primary
          onClick={!isPreview ? submitCode : undefined}
          disabled={!code.trim()}
          btnSize="large"
        >
          {submitButtonText}
        </Button>
      </Layout.Footer>
    </Layout>
  );
}
