import { CalendarDateInput } from '@root/components/StyledCalendar/types';

// Quoted literals first, then longer tokens before their shorter prefixes.
const FORMAT_TOKENS = /'(?:[^']|'')*'|yyyy|yy|MMMM|MMM|MM|dd|d|HH|H|hh|h|mm|m|a/g;

/**
 * Native date formatter (replaces date-fns format)
 * Supports common date-fns tokens: yyyy, yy, MM, MMM, MMMM, dd, d, HH, H, hh, h, mm, m, a
 * and quoted literals ('at', with '' for a single quote). Other characters are kept as they are.
 */
function format(date: Date, pattern: string): string {
  const year = date.getFullYear();
  const month = date.getMonth();
  const day = date.getDate();
  const hours = date.getHours();
  const minutes = date.getMinutes();
  const hours12 = hours % 12 || 12;

  const monthNames = [
    'Jan',
    'Feb',
    'Mar',
    'Apr',
    'May',
    'Jun',
    'Jul',
    'Aug',
    'Sep',
    'Oct',
    'Nov',
    'Dec'
  ];
  const monthNamesFull = [
    'January',
    'February',
    'March',
    'April',
    'May',
    'June',
    'July',
    'August',
    'September',
    'October',
    'November',
    'December'
  ];

  const values: Record<string, string> = {
    yyyy: String(year),
    yy: String(year).slice(-2),
    MMMM: monthNamesFull[month],
    MMM: monthNames[month],
    MM: String(month + 1).padStart(2, '0'),
    dd: String(day).padStart(2, '0'),
    d: String(day),
    HH: String(hours).padStart(2, '0'),
    H: String(hours),
    hh: String(hours12).padStart(2, '0'),
    h: String(hours12),
    mm: String(minutes).padStart(2, '0'),
    m: String(minutes),
    a: hours < 12 ? 'AM' : 'PM'
  };

  // One pass, so letters in literals and in month names are never replaced again.
  return pattern.replace(FORMAT_TOKENS, (token) => {
    if (token.startsWith("'")) {
      return token === "''" ? "'" : token.slice(1, -1).replace(/''/g, "'");
    }
    return values[token];
  });
}

/**
 * Native differenceInDays (replaces date-fns differenceInDays)
 */
function differenceInDays(date1: Date, date2: Date): number {
  const msPerDay = 24 * 60 * 60 * 1000;
  const utc1 = Date.UTC(date1.getFullYear(), date1.getMonth(), date1.getDate());
  const utc2 = Date.UTC(date2.getFullYear(), date2.getMonth(), date2.getDate());
  return Math.floor((utc1 - utc2) / msPerDay);
}

// TODO : Display date for time-zone
export function formatCalenderDates(date: CalendarDateInput, dateFormat: string): string {
  if (!date) return '';
  if (Array.isArray(date)) {
    const [date1, date2] = date;
    return `${formatCalenderDates(date1, dateFormat)}-${formatCalenderDates(date2, dateFormat)}`;
  }
  return format(date, dateFormat);
}

export function formatDateString(dateString: string | undefined, outputFormat: string) {
  if (!dateString) return '';
  const date = new Date(dateString);
  // eslint-disable-next-line no-restricted-globals
  if (date instanceof Date && !isNaN(date.getTime())) {
    return format(date, outputFormat);
  }
  return '';
}

export function isDateWithinDays(date: Date, days: number): boolean {
  return differenceInDays(date, new Date()) <= days;
}

export function getDaysInMonth(month: number, year: number) {
  // Add 1 to the month parameter to get to the next month, and set the day to 0
  // to automatically roll back to the last day of the specified month.
  return new Date(year, month + 1, 0).getDate();
}
