import { Stack, Button, Layout } from '@trueloyal-engineering/react-ui';
import {
  X as XIcon,
  FacebookRounded as FacebookRoundedIcon,
  Pinterest as PinterestIcon
} from '@root/icons';
import { Activity } from '@trueloyal-engineering/ui-api-sdk';
import { ActivityHeader, LoadMask } from '@root/components';
import { useSocialShareActivity } from '@root/hooks';
import { AuthConfig } from '@root/core/config';
import { ActivitySuccess } from '../ActivitySuccess';

export interface SocialShareActivityProps {
  activity: Activity;
}

function getActivityIcons(activityId: string) {
  switch (activityId) {
    case 'share_on_twitter':
      return <XIcon />;
    case 'share_on_facebook':
      return <FacebookRoundedIcon />;
    case 'share_on_pinterest':
      return <PinterestIcon />;
    default:
      return null;
  }
}

export function SocialShareActivity({ activity }: SocialShareActivityProps) {
  const {
    enduser_activity_short_description: title,
    activity_id: activityId,
    earnpoints_button_label: tagLabel,
    extra_config: extraConfig
  } = activity;

  const { loading, showCongratulation, onShare } = useSocialShareActivity({ activity });

  if (showCongratulation) {
    return <ActivitySuccess activity={activity} />;
  }

  const description = extraConfig?.reward_text;
  const shareButtonText = extraConfig?.share_button_text;

  const activityIcon = getActivityIcons(activityId);

  const isPreview = AuthConfig.isPreview();

  return (
    <Layout className="social-share-activity">
      {loading && <LoadMask />}
      <Layout.Content>
        <Stack>
          <ActivityHeader tagLabel={tagLabel} title={title} description={description} />
        </Stack>
      </Layout.Content>
      <Layout.Footer>
        <Button
          id="share-btn"
          fullWidthOnDeviceType="sm"
          primary
          icon={activityIcon}
          onClick={!isPreview ? onShare : undefined}
          btnSize="large"
        >
          {shareButtonText}
        </Button>
      </Layout.Footer>
    </Layout>
  );
}
