import { useEffect } from 'react';
import { toast } from 'react-toastify';
import { MerchantConfig } from '@root/core/config';
import { useAppDispatch } from '@root/store';
import { fetchMember } from '@root/store/slices/memberSlice';
import { fetchTransaction } from '@root/store/slices/transactionSlice';

type UseTintFormParams = {
  formRef: React.RefObject<any>;
  onSuccess: (transactionData: any) => void;
};

export function useTintForm({ formRef, onSuccess }: UseTintFormParams) {
  const dispatch = useAppDispatch();

  useEffect(() => {
    // Wait for tint-form element to be created by TintForm component
    const checkAndSetupForm = (): (() => void) | undefined => {
      const formElement = formRef.current?.querySelector('tint-form');

      if (!formElement) {
        // Form element not ready yet, try again
        const timeoutId: ReturnType<typeof setTimeout> = setTimeout(checkAndSetupForm, 100);
        return () => clearTimeout(timeoutId);
      }

      const { tintLocaleMapping } = MerchantConfig.getInstance();
      const formLanguage = window?.language;
      let tintLocale: string | undefined;

      if (
        formLanguage &&
        tintLocaleMapping &&
        Object.prototype.hasOwnProperty.call(tintLocaleMapping, formLanguage)
      ) {
        tintLocale = tintLocaleMapping[formLanguage];
      }

      if (tintLocale) {
        formElement.setAttribute('form-locale', tintLocale);
      }

      const handleAfterSubmit = async (e: CustomEvent<any>) => {
        const metadata = e.detail?.data?.attributes?.metadata || {};
        const transactionId = metadata.transaction_id;

        if (transactionId) {
          try {
            const response = await dispatch(fetchTransaction({ id: transactionId })).unwrap();
            dispatch(fetchMember());
            onSuccess(response);
          } catch (error) {
            toast.error(error?.errorMessage);
          }
        }
      };

      formElement.addEventListener('afterSubmit', handleAfterSubmit);

      return () => {
        formElement.removeEventListener('afterSubmit', handleAfterSubmit);
      };
    };

    return checkAndSetupForm();
  }, []);
}
