import { ActivityHeader, FilesList, LoadMask } from '@root/components';
import { Button, Stack, Typography, Layout } from '@trueloyal-engineering/react-ui';
import { Activity } from '@trueloyal-engineering/ui-api-sdk';
import { useFile, useSubmitReceiptActivity } from '@root/hooks';
import {
  ALLOWED_RECEIPT_FILE_TYPES,
  MAX_NUMBER_OF_RECEIPTS_UPLOAD,
  MAX_UPLOAD_FILE_SIZE_IN_MB
} from '@root/core/constants/activity.constants';
import { sanitizeHTML } from '@root/core/utils/htmlUtils';
import { AuthConfig } from '@root/core/config';
import { ActivitySuccess } from '../ActivitySuccess';

export interface SubmitReceiptActivityProps {
  activity: Activity;
}

export function SubmitReceiptActivity({ activity }: SubmitReceiptActivityProps) {
  const {
    enduser_activity_short_description: title,
    earnpoints_button_label: tagLabel,
    extra_config: extraConfig
  } = activity;

  const { inputRef, files, removeFile, selectFile, handleFileChange } = useFile({
    maxFileSizeInMB: MAX_UPLOAD_FILE_SIZE_IN_MB,
    maxNumberOfFiles: MAX_NUMBER_OF_RECEIPTS_UPLOAD,
    errorLabels: {
      MAX_FILE_NUMBER_REACHED: extraConfig?.file_count_error_message ?? '',
      MAX_FILE_SIZE_REACHED: extraConfig?.file_size_error_message ?? ''
    },
    allowedExtensions: ALLOWED_RECEIPT_FILE_TYPES
  });

  const { loading, showCongratulation, uploadFile } = useSubmitReceiptActivity({ activity, files });

  if (showCongratulation) {
    return <ActivitySuccess activity={activity} />;
  }

  const isPreview = AuthConfig.isPreview();

  const description = extraConfig?.reward_instruction_text;
  const instructionText = extraConfig?.instruction_text;
  const addAnotherButtonText = extraConfig?.add_another_image_button_text;
  const selectReceiptText = extraConfig?.receipt_selection_button_text;
  const uploadReceiptText = extraConfig?.upload_button_text;

  return (
    <Layout className="submit-receipt-activity">
      {loading && <LoadMask />}
      <Layout.Content>
        <Stack>
          <ActivityHeader tagLabel={tagLabel} title={title} description={description} />
          <Typography
            muted
            fontWeight="thin"
            dangerouslySetInnerHTML={{ __html: sanitizeHTML(instructionText) }}
          />
          {files.length > 0 && (
            <Stack>
              <FilesList files={files} onRemove={removeFile} />
              {files.length < 5 && (
                <Button mono onClick={selectFile} id="select-receipt-btn">
                  {addAnotherButtonText}
                </Button>
              )}
            </Stack>
          )}
        </Stack>
        <input
          hidden
          style={{ display: 'none' }}
          type="file"
          ref={isPreview ? null : inputRef}
          onChange={!isPreview ? handleFileChange : undefined}
          multiple
          accept=".jpg, .jpeg, .png, .pdf, .heic, .heif"
          aria-hidden
          aria-label="File Upload"
        />
      </Layout.Content>
      <Layout.Footer>
        <Button
          id="upload-receipt-btn"
          primary
          fullWidthOnDeviceType="sm"
          onClick={files.length > 0 ? uploadFile : selectFile}
          btnSize="large"
        >
          {files.length > 0 ? uploadReceiptText : selectReceiptText}
        </Button>
      </Layout.Footer>
    </Layout>
  );
}
