import { ZinreloApi } from '@root/ZinreloApi'
import {
  GetTransactionsQueryParams,
  RedeemResponse,
  RewardsInputData,
  TransactionsResponse,
  TransactionResponse,
} from './types'
import { MethodArgsWithoutData, MethodArgsWithoutQueryParams } from '@root/types'
import { isEmpty } from '@root/utils'
import { ZinreloErrors } from '@root/constants'

export class TransactionsApi {
  private readonly apiClient: ZinreloApi

  constructor(apiClient: ZinreloApi) {
    this.apiClient = apiClient
  }

  private get url(): string {
    return `${this.apiClient.client.getApiUrl()}`
  }

  public async redeem(input: MethodArgsWithoutQueryParams<RewardsInputData>): Promise<RedeemResponse> {
    const endpoint = `${this.url}/redeem`

    if (!input?.data || isEmpty(input.data)) {
      ZinreloErrors.throwErrorHelper(ZinreloErrors.INVALID_INPUT)
    }

    return this.apiClient.client.execute({
      method: 'post',
      url: endpoint,
      passToken: true,
      data: input?.data,
    })
  }

  /**
   *  https://help.zinrelo.com/reference/list-members-transaction-api
   */
  public async getTransactions(
    input?: MethodArgsWithoutData<GetTransactionsQueryParams>
  ): Promise<TransactionsResponse> {
    const endpoint = `${this.url}/transactions`

    return this.apiClient.client.execute({
      method: 'get',
      url: endpoint,
      passToken: true,
      params: input?.queryParams,
    })
  }

  public async getTransactionById(id: string, input?: MethodArgsWithoutData): Promise<TransactionResponse> {
    const endpoint = `${this.url}/transactions/${id}`

    return this.apiClient.client.execute({
      url: endpoint,
      method: 'get',
      passToken: true,
      params: input?.queryParams,
    })
  }
}
