export interface IntegrationSettings {
  business_instagram_handles: string[];
  tiktok_hashtags: string[];
  blocked_instagram_handles: string[];
  blocked_tiktok_handles: string[];
}

export class IntegrationSettings {
  private static instance: IntegrationSettings;

  private constructor() {
    // Private constructor to prevent instantiation.
  }

  public static initialize(integrationSettings: IntegrationSettings): void {
    IntegrationSettings.instance = integrationSettings;
  }

  public static getInstance(): IntegrationSettings {
    if (!IntegrationSettings.instance) {
      throw new Error('Integration Setttings has not been initialized. Call initialize first.');
    }
    return IntegrationSettings.instance;
  }
}
