import { ZinreloApi } from '@root/ZinreloApi'
import {
  ActivityData,
  ActivityDataResponse,
  GetActivitiesQueryParams,
  GetActivityTrackCodeQueryParams,
  TrackingCodeData,
} from './types'
import { MethodArgsWithoutData } from '@root/types'

export class ActivitiesApi {
  private readonly apiClient: ZinreloApi

  constructor(apiClient: ZinreloApi) {
    this.apiClient = apiClient
  }

  private get url(): string {
    return `${this.apiClient.client.getApiUrl()}`
  }

  public async getActivities(
    input?: MethodArgsWithoutData<GetActivitiesQueryParams>
  ): Promise<ActivityDataResponse<ActivityData>> {
    const endpoint = `${this.url}/activities`

    return this.apiClient.client.execute({
      method: 'get',
      url: endpoint,
      params: input?.queryParams,
    })
  }

  public async getEligibleActivities(
    input?: MethodArgsWithoutData<GetActivitiesQueryParams>
  ): Promise<ActivityDataResponse<ActivityData>> {
    const endpoint = `${this.url}/eligible-activities`

    return this.apiClient.client.execute({
      method: 'get',
      url: endpoint,
      passToken: true,
      params: input?.queryParams,
    })
  }

  public async getActivityTrackCode(
    input: MethodArgsWithoutData<GetActivityTrackCodeQueryParams>
  ): Promise<ActivityDataResponse<TrackingCodeData>> {
    const endpoint = `${this.url}/activity-track-code`

    return this.apiClient.client.execute({
      method: 'get',
      url: endpoint,
      params: input?.queryParams,
      passToken: true,
    })
  }
}
