import { FormattedPointsExpirationScheduleDatumType } from '@root/store';
import { BasicTableColumnConfig, toTitleCase } from '@trueloyal-engineering/react-ui';
import { useMemo } from 'react';

export const usePointsExpirationTableColumnConfig = ({
  expirationDateColumnTitle,
  pointsColumnTitle
}: {
  expirationDateColumnTitle: string;
  pointsColumnTitle: string;
}): BasicTableColumnConfig<FormattedPointsExpirationScheduleDatumType>[] => {
  return useMemo(
    () => [
      {
        field: 'expirationDate',
        title: expirationDateColumnTitle,
        format: 'text'
      },
      {
        field: 'points',
        // points label isn't part of points expiry page settings, so the text casing needs formatting
        title: toTitleCase(pointsColumnTitle),
        format: 'text',
        textAlign: 'right'
      }
    ],
    [expirationDateColumnTitle, pointsColumnTitle]
  );
};
