import { ReactComponent as Verified } from '@root/assets/icons/verified.svg';
import { ReactComponent as Stars } from '@root/assets/icons/stars.svg';
import { ReactComponent as FeaturedSeasonalAndGifts } from '@root/assets/icons/featured_seasonal_and_gifts.svg';
import { ReactComponent as Campaign } from '@root/assets/icons/campaign.svg';
import { ReactComponent as DoNotDisturbOn } from '@root/assets/icons/do_not_disturb_on.svg';
import { ReactComponent as CheckCircle } from '@root/assets/icons/check_circle.svg';
import { ReactComponent as Lock } from '@root/assets/icons/lock.svg';
import { ReactComponent as Terms } from '@root/assets/icons/terms.svg';
import { ReactComponent as NegativePoints } from '@root/assets/icons/nagative_points.svg';
import { classNames } from '@trueloyal-engineering/react-ui';
import styles from './icon.module.css';

export type IconName =
  | 'verified'
  | 'check_circle'
  | 'stars'
  | 'campaign'
  | 'do_not_disturb_on'
  | 'featured_seasonal_and_gifts'
  | 'lock'
  | 'terms'
  | 'negative_points';

const icons: Record<IconName, React.FunctionComponent<React.SVGProps<SVGSVGElement>>> = {
  verified: Verified,
  check_circle: CheckCircle,
  stars: Stars,
  campaign: Campaign,
  do_not_disturb_on: DoNotDisturbOn,
  featured_seasonal_and_gifts: FeaturedSeasonalAndGifts,
  lock: Lock,
  terms: Terms,
  negative_points: NegativePoints
};

interface IconProps extends React.SVGProps<SVGSVGElement> {
  name: IconName;
  size?: number;
  flipOnRTL?: boolean;
}

export function Icon({ name, className, size = 20, flipOnRTL = false, ...props }: IconProps) {
  const SvgIcon = icons[name];

  const classes = classNames(
    styles['zrl-icon'],
    `zrl-icon--${name}`,
    flipOnRTL && 'zrl-icon--flip-on-rtl',
    className
  );
  return <SvgIcon className={classes} width={size} height={size} {...props} />;
}
