import React from 'react';

import { Container, Stack, Typography } from '@trueloyal-engineering/react-ui';
import { EUDSettings, MerchantConfig } from '@root/core/config';
import { ActivityCarousel, RewardCarousel, TierCarousel } from '@root/containers';
import { SignUpSection } from '@root/containers/auth';
import { TermsSection } from '@root/containers/terms';
import { replaceLabels } from '@root/core/utils/textUtils';
import { Hero, QuickActionList } from '@root/components';
import { StreakCarousel } from '@root/containers/streaks/StreakCarousel';
import styles from './guest-page.module.css';

export function DefaultGuestPage() {
  const {
    content_settings: {
      program_details_program_name: programName,
      dashboard_header_section_program_description: descriptionText,
      dashboard_header_section_welcome_text: welcomeText,
      program_details_currency_plural_text: currencyPlural,
      quick_actions_section_header_text: quickActionsHeaderText
    },
    background_image_url: backgroundImage
  } = EUDSettings.getInstance();

  const { enableStreaks, enableChallenges } = MerchantConfig.getInstance();

  const welcomeMessage = replaceLabels(welcomeText, { '{{PROGRAM_NAME}}': programName });
  const description = replaceLabels(descriptionText, { '{{POINTS_LABEL}}': currencyPlural });

  return (
    <div className="guest-page">
      <Hero bgImg={backgroundImage} fillImage>
        <Stack gap={2} className="guest-page__program-info">
          <Stack gap={1} style={{ alignItems: 'stretch' }}>
            <Typography variant="bodyMd" fontWeight="bold" titled as="h1" title={welcomeMessage}>
              {welcomeMessage}
            </Typography>
            <Typography variant="header3xl" fontWeight="bold" titled as="h1" title={description}>
              {description}
            </Typography>
          </Stack>
          <SignUpSection />
          <TermsSection />
        </Stack>
      </Hero>

      <Container className={styles['guest-container']}>
        {(enableStreaks || enableChallenges) && (
          <div className={styles['guest-container__quick-actions']}>
            <Typography
              variant="headerXl"
              fontWeight="bold"
              titled
              trunc={1}
              title={quickActionsHeaderText}
            >
              {quickActionsHeaderText}
            </Typography>
            <QuickActionList />
          </div>
        )}
        <RewardCarousel isGuest />
        <ActivityCarousel isGuest />
        <TierCarousel />
        {enableStreaks && <StreakCarousel isGuest />}
      </Container>
    </div>
  );
}
