import { LoadMask } from '@root/components';
import { AuthConfig, EUDSettings } from '@root/core/config';
import { MEMBER_STATUS_OPTED_OUT } from '@root/core/constants/member.constants';
import { replaceLabels } from '@root/core/utils/textUtils';
import { useAppNavigation } from '@root/hooks';
import { useAppDispatch, useAppSelector } from '@root/store';
import { updateMember } from '@root/store/slices/memberSlice';
import { Button, Stack, Typography } from '@trueloyal-engineering/react-ui';
import { UpdateMemberInputData } from '@trueloyal-engineering/ui-api-sdk';

export function MemberOptOut() {
  const dispatch = useAppDispatch();
  const status = useAppSelector((state) => state.member.status);

  const { back, reloadPage } = useAppNavigation();

  const handleOptOut = () => {
    const updateParams: UpdateMemberInputData = {
      member_status: MEMBER_STATUS_OPTED_OUT
    };
    dispatch(updateMember({ updateParams })).then((response) => {
      if (response.meta.requestStatus === 'fulfilled') {
        reloadPage();
      }
    });
  };

  const {
    membership_opt_out_page_header: header,
    membership_opt_out_page_description: descriptionText,
    membership_opt_out_page_confirm_button_label: confirmButtonLabel,
    membership_opt_out_page_cancel_button_label: dismissalButtonLabel,
    program_details_currency_plural_text: currencyPlural
  } = EUDSettings.getInstance().content_settings;

  const loading = status === 'pending';
  const isPreview = AuthConfig.isPreview();

  const description = replaceLabels(descriptionText, {
    '{{POINTS_LABEL}}': currencyPlural
  });

  return (
    <Stack gap={3} className="member-optout">
      {loading && <LoadMask />}
      <Stack gap={0.2}>
        <Typography variant="header2xl" fontWeight="bold">
          {header}
        </Typography>
        <Typography fontWeight="thin" muted>
          {description}
        </Typography>
      </Stack>
      <Stack>
        <Button
          id="member-optout-cancel-btn"
          primary
          fullWidthOnDeviceType="sm"
          onClick={back}
          btnSize="large"
        >
          {dismissalButtonLabel}
        </Button>
        <Button
          id="member-optout-btn"
          fullWidthOnDeviceType="sm"
          onClick={!isPreview ? handleOptOut : undefined}
          btnSize="large"
        >
          {confirmButtonLabel}
        </Button>
      </Stack>
    </Stack>
  );
}
