import { useState } from 'react';
import { ActivityHeader, LoadMask, Select } from '@root/components';
import { Button, Stack, Layout, Typography } from '@trueloyal-engineering/react-ui';
import { Activity, ActivityExtraConfig, Member } from '@trueloyal-engineering/ui-api-sdk';
import { AuthConfig } from '@root/core/config';
import { MONTH_OPTIONS } from '@root/core/constants/activity.constants';
import { getDaysInMonth } from '@root/core/utils/dateUtils';
import { useAppDispatch, useAppSelector } from '@root/store';
import { updateMember } from '@root/store/slices/memberSlice';
import { ActivitySuccess } from '../ActivitySuccess';
import styles from './date-activity.module.css';

export interface DateAttribute {
  attribute_key: string;
  name: string;
  is_year_required?: boolean;
}

export interface DateValue {
  month?: number;
  day?: number;
  year?: number;
}

type DateActivityExtraConfig = ActivityExtraConfig & { date_attributes?: DateAttribute[] };
type MemberWithCustomAttributes = Member & { custom_attributes?: Record<string, string | null> };

// The year stored when a member gives none.
const NO_YEAR = 1904;
const NO_YEAR_OPTION = { label: 'No year', value: 0 };
const currentYear = new Date().getFullYear();
const YEAR_OPTIONS = Array.from({ length: 121 }, (_, i) => ({
  label: String(currentYear - i),
  value: currentYear - i
}));

const pad = (value?: number) => String(value).padStart(2, '0');

export function parseStoredDate(value?: string | null): DateValue {
  const match = value?.match(/^(\d{2})\/(\d{2})\/(\d{4})/);
  if (!match) return {};
  const year = Number(match[3]);
  return {
    month: Number(match[1]),
    day: Number(match[2]),
    year: year === NO_YEAR ? undefined : year
  };
}

// Always month first, whatever the merchant's input_date_format.
export function formatDate({ month, day, year }: DateValue) {
  return `${pad(month)}/${pad(day)}${year ? `/${year}` : ''}`;
}

const isComplete = (date: DateValue, attribute: DateAttribute) =>
  Boolean(date.month && date.day && (date.year || !attribute.is_year_required));

const isStarted = (date: DateValue) => Boolean(date.month || date.day || date.year);

export interface DateActivityProps {
  activity: Activity;
}

export function DateActivity({ activity }: DateActivityProps) {
  const dispatch = useAppDispatch();
  const savedDates = useAppSelector(
    (state) =>
      (state.member.memberDetails as MemberWithCustomAttributes | undefined)?.custom_attributes
  );
  const loading = useAppSelector((state) => state.member.status === 'pending');

  const {
    earnpoints_button_label: tagLabel,
    enduser_activity_short_description: shortDescription
  } = activity;
  const extraConfig = activity.extra_config as DateActivityExtraConfig | undefined;
  const attributes = extraConfig?.date_attributes ?? [];

  const [dates, setDates] = useState<Record<string, DateValue>>(() =>
    Object.fromEntries(attributes.map(({ name }) => [name, parseStoredDate(savedDates?.[name])]))
  );
  const [isSaved, setIsSaved] = useState(false);

  const allDatesSaved =
    attributes.length > 0 && attributes.every(({ name }) => Boolean(savedDates?.[name]));

  const isChanged = ({ name }: DateAttribute) => {
    const date = dates[name] ?? {};
    const saved = parseStoredDate(savedDates?.[name]);
    return date.month !== saved.month || date.day !== saved.day || date.year !== saved.year;
  };
  // Unchanged dates are neither sent nor checked, so an old date can't block saving the others.
  const changedAttributes = attributes.filter(isChanged);
  const canSave =
    changedAttributes.length > 0 &&
    changedAttributes.every((attribute) => {
      const date = dates[attribute.name] ?? {};
      return !isStarted(date) || isComplete(date, attribute);
    });

  const setDate = (name: string, change: DateValue) => {
    setDates((previous) => {
      const date = { ...previous[name], ...change };
      if (
        date.month &&
        date.day &&
        date.day > getDaysInMonth(date.month - 1, date.year || NO_YEAR)
      ) {
        date.day = undefined;
      }
      return { ...previous, [name]: date };
    });
  };

  const clearDate = (name: string) => setDates((previous) => ({ ...previous, [name]: {} }));

  const saveDates = async () => {
    const customAttributes = Object.fromEntries(
      changedAttributes.map(({ name }) => {
        const date = dates[name] ?? {};
        // An empty value clears a saved date.
        return [name, isStarted(date) ? formatDate(date) : ''];
      })
    );
    const result = await dispatch(
      updateMember({ updateParams: { custom_attributes: customAttributes } })
    );
    // Only removing dates isn't worth a "Congratulations"; stay on the form.
    if (updateMember.fulfilled.match(result) && Object.values(customAttributes).some(Boolean)) {
      setIsSaved(true);
    }
  };

  const dayOptions = ({ month, year }: DateValue) =>
    month
      ? Array.from({ length: getDaysInMonth(month - 1, year || NO_YEAR) }, (_, i) => ({
          label: String(i + 1),
          value: i + 1
        }))
      : [];

  if (isSaved) {
    return <ActivitySuccess activity={activity} />;
  }

  return (
    <Layout className="date-activity">
      {loading && <LoadMask />}
      <Layout.Content>
        <Stack>
          <ActivityHeader
            tagLabel={tagLabel}
            title={shortDescription}
            description={allDatesSaved ? extraConfig?.thank_you_text : extraConfig?.reward_text}
          />
          {attributes.map((attribute) => {
            const date = dates[attribute.name] ?? {};
            return (
              <Stack key={attribute.attribute_key} gap={1} className={styles['date-activity__row']}>
                <Typography fontWeight="bold">{attribute.name}</Typography>
                <Stack orientation="horizontal" gap={1} className={styles['date-activity__fields']}>
                  <Select
                    className={styles['date-activity__month-picker']}
                    options={MONTH_OPTIONS}
                    placeholder="month"
                    ariaLabel={`${attribute.name} month`}
                    selectedOption={date.month}
                    onOptionChange={(value) => setDate(attribute.name, { month: Number(value) })}
                  />
                  <Select
                    className={styles['date-activity__day-picker']}
                    options={dayOptions(date)}
                    placeholder="day"
                    ariaLabel={`${attribute.name} day`}
                    selectedOption={date.day}
                    onOptionChange={(value) => setDate(attribute.name, { day: Number(value) })}
                    disabled={!date.month}
                  />
                  <Select
                    className={styles['date-activity__year-picker']}
                    options={
                      attribute.is_year_required ? YEAR_OPTIONS : [NO_YEAR_OPTION, ...YEAR_OPTIONS]
                    }
                    placeholder={attribute.is_year_required ? 'year' : 'year (optional)'}
                    ariaLabel={`${attribute.name} year`}
                    selectedOption={date.year}
                    onOptionChange={(value) =>
                      setDate(attribute.name, { year: Number(value) || undefined })
                    }
                  />
                  {isStarted(date) && (
                    <Button mono onClick={() => clearDate(attribute.name)}>
                      Clear
                    </Button>
                  )}
                </Stack>
              </Stack>
            );
          })}
        </Stack>
      </Layout.Content>
      <Layout.Footer>
        <Button
          id="save-dates-btn"
          fullWidthOnDeviceType="sm"
          primary
          onClick={!AuthConfig.isPreview() ? saveDates : undefined}
          btnSize="large"
          disabled={!canSave || loading}
        >
          {extraConfig?.save_button_text || 'Save'}
        </Button>
      </Layout.Footer>
    </Layout>
  );
}
