import { GENERIC_FONTS, GOOGLE_FONTS_API_BASE, GOOGLE_FONTS_DISPLAY } from '../constants/fonts';
import { STYLE_ATTRIBUTES } from '../constants/styleConstants';

export const extractFontName = (fontFamily?: string): string | null => {
  if (!fontFamily || fontFamily === 'inherit') return null;

  const cleaned = fontFamily.split(',')[0].replace(/['"]/g, '').trim();
  return GENERIC_FONTS.includes(cleaned.toLowerCase()) ? null : cleaned;
};

export const buildGoogleFontsUrl = (fonts: string[]): string => {
  const families = fonts.map((f) => `family=${f}`).join('&');
  return `${GOOGLE_FONTS_API_BASE}?${families}&display=${GOOGLE_FONTS_DISPLAY}`;
};

export const createOrUpdateLink = (
  url: string,
  id: string,
  target: HTMLElement | ShadowRoot
): void => {
  let link = target.querySelector(`#${id}`) as HTMLLinkElement;

  if (!link) {
    link = document.createElement('link');
    link.id = id;
    link.rel = 'stylesheet';
    link.href = url;
    target.appendChild(link);
  } else {
    link.href = url;
  }
};

export const getTargetRoot = (targetRoot?: ShadowRoot | Document): Document | ShadowRoot => {
  if (targetRoot) return targetRoot;

  const dashboardRoot = document.querySelector(`[${STYLE_ATTRIBUTES.DASHBOARD_ROOT}]`);
  return (dashboardRoot?.getRootNode() as Document | ShadowRoot) || document;
};
