import {
  BUFFER_COUNT,
  DISPLAY_COUNT,
  INITIAL_FETCH_COUNT
} from '@root/core/constants/pagination.constants';
import { Status } from '@root/store/types';
import { CommonQueryParams } from '@trueloyal-engineering/ui-api-sdk';
import { useEffect, useState } from 'react';

// TODO : Change filters to generic type when the use case is expanded beyond
export interface PaginationConfig {
  initialFetchCount: number;
  bufferSize: number;
  displayCount: number;
}

export interface UsePaginationProps<T, V = object> {
  data: T[] | undefined;
  fetchData: (filters: CommonQueryParams<V>) => void;
  more: boolean;
  nextCursor: number;
  totalCount: number;
  status: Status;
  config?: PaginationConfig;
}

const defaultConfig: PaginationConfig = {
  initialFetchCount: INITIAL_FETCH_COUNT,
  bufferSize: BUFFER_COUNT,
  displayCount: DISPLAY_COUNT
};

export function usePagination<T, V>({
  data,
  fetchData,
  more,
  nextCursor,
  status,
  totalCount,
  config = defaultConfig
}: UsePaginationProps<T, V>) {
  const [visibleSlice, setVisibleSlice] = useState<T[]>([]);
  const [filters, changeFilters] = useState<V | null>(null);
  const { initialFetchCount, displayCount, bufferSize } = config;
  const fetchDataHelper = (startIndex: number) => {
    const input = {
      start_cursor: startIndex,
      count: initialFetchCount,
      ...filters
    } as CommonQueryParams<V>;
    fetchData(input);
  };

  useEffect(() => {
    if (data && visibleSlice.length === 0) {
      // set initial transaction
      setVisibleSlice(data.slice(0, displayCount));
    }
  }, [data]);

  useEffect(() => {
    // if filters changed
    if (!filters) return;
    setVisibleSlice([]);
    fetchDataHelper(0);
  }, [filters]);

  const showMore = () => {
    if (!data) return;
    const startIndex = visibleSlice.length;
    const endIndex = startIndex + displayCount;
    if (more && data.length < endIndex + bufferSize) {
      fetchDataHelper(nextCursor);
    }
    setVisibleSlice((prevSlice) => [...prevSlice, ...data.slice(startIndex, endIndex)]);
  };

  return {
    visibleSlice,
    showMore,
    fetchDataHelper,
    changeFilters,
    loading: status === 'pending',
    more: visibleSlice.length < totalCount
  };
}
