import { TransactionHelper } from '@root/core/helpers/transaction';
import { formatDateString } from '@root/core/utils/dateUtils';
import { Stack, Typography, Button } from '@trueloyal-engineering/react-ui';
import { Transaction } from '@trueloyal-engineering/ui-api-sdk';
import { AuthConfig, EUDSettings, MerchantConfig } from '@root/core/config';
import { formatNumber, pluralize } from '@root/core/utils/textUtils';
import { CopyToClipboardInput, Icon, IconName } from '@root/components';
import { useAppNavigation } from '@root/hooks';
import {
  TRANSACTION_AWARD_ICON_LABEL,
  TRANSACTION_DEDUCT_ICON_LABEL,
  TRANSACTION_GENERIC_ICON_LABEL,
  TRANSACTION_REDEEM_ICON_LABEL,
  TRANSACTION_STATUS_PENDING
} from '@root/core/constants/transaction.constants';
import { toast } from 'react-toastify';
import { ACTIVITY_IDS } from '@root/core/constants/activity.constants';
import styles from './transaction-row.module.css';

export interface TransactionRowProps {
  transaction: Transaction;
}

const IconMapping: Record<string, IconName> = {
  [TRANSACTION_GENERIC_ICON_LABEL]: 'stars',
  [TRANSACTION_DEDUCT_ICON_LABEL]: 'do_not_disturb_on',
  [TRANSACTION_AWARD_ICON_LABEL]: 'stars',
  [TRANSACTION_REDEEM_ICON_LABEL]: 'featured_seasonal_and_gifts'
};

export function TransactionRow({ transaction }: TransactionRowProps) {
  const { display_date_format: displayDateFormat, content_settings: labelConfig } =
    EUDSettings.getInstance();

  const {
    id,
    iconLabel,
    name,
    points,
    transactionLabel,
    couponCode,
    rewardLink,
    orderId,
    reason,
    purchasedBy,
    codeEntered,
    usedCouponCode,
    receiptId,
    rejectionReason,
    receiptFileUrl,
    imageUrl,
    transactionType
  } = TransactionHelper.normalizeTransaction(transaction, labelConfig);

  const {
    program_details_currency_plural_text: currencyPlural,
    program_details_currency_singular_text: currencySingular,
    commons_copy_text_successful_text: copiedToastText,
    commons_coupon_code_text: couponCodeText,
    points_history_page_order_id_text: orderIdText,
    points_history_page_reason_text: reasonText,
    points_history_page_purchased_by_text: purchasedByText,
    points_history_page_code_entered_text: codeEnteredText,
    points_history_page_receipt_id_text: receiptIdText,
    points_history_page_receipt_rejection_reason_text: rejectionReasonText,
    points_history_page_img_view_text: imgViewText,
    commons_reward_link_text: rewardLinkText
  } = labelConfig;

  const currency = {
    plural: currencyPlural,
    singular: currencySingular
  };

  const isPreview = AuthConfig.isPreview();

  const { gotoViewImage } = useAppNavigation();

  const handleCopy = () => {
    toast.success(copiedToastText, { hideProgressBar: true, autoClose: 1000 });
  };

  const handleViewImage = () => {
    if (id && name) {
      gotoViewImage(id, name, (imageUrl || receiptFileUrl)!);
    }
  };

  const shouldShowPointsSign = MerchantConfig.getInstance().negativePointsAllowed;

  const hidePoints =
    id === ACTIVITY_IDS.ZRL_SUBMIT_RECEIPT &&
    points === 0 &&
    transaction.status === TRANSACTION_STATUS_PENDING;

  const transactionDate = formatDateString(transaction.created_date, displayDateFormat);
  const pointsLabel = pluralize(points, currency.singular, currency.plural);

  const pointsContentMarkup = shouldShowPointsSign
    ? (() => {
        const { sign, color } = TransactionHelper.getPointsDisplay(transaction);
        return (
          <>
            <span style={{ color }}>{`${sign}${formatNumber(points)}`}</span>{' '}
            <span>{pointsLabel}</span>
          </>
        );
      })()
    : `${formatNumber(points)} ${pointsLabel}`;

  return (
    <Stack
      orientation="horizontal"
      role="listitem"
      className={styles['transaction-row']}
      gap={0.7}
      data-transaction_type={transactionType}
      data-transaction_type_id={id}
    >
      <Icon size={19.7} name={IconMapping[iconLabel as keyof typeof IconMapping]} />
      <Stack gap={0.5} className={styles['transaction-row__content']}>
        <Stack orientation="horizontal">
          <Stack gap={0.25}>
            <Typography variant="bodyMd">{name}</Typography>
            <Typography variant="bodySm" muted fontWeight="thin">
              {transactionDate}
            </Typography>
            {orderId && (
              <Typography variant="bodySm" muted fontWeight="thin">
                {`${orderIdText}: ${orderId}`}
              </Typography>
            )}
            {receiptId && (
              <Typography variant="bodySm" muted fontWeight="thin">
                {`${receiptIdText}: ${receiptId}`}
              </Typography>
            )}
            {purchasedBy && (
              <Typography variant="bodySm" muted fontWeight="thin">
                {`${purchasedByText}: ${purchasedBy}`}
              </Typography>
            )}
            {codeEntered && (
              <Typography variant="bodySm" muted fontWeight="thin">
                {`${codeEnteredText}: ${codeEntered}`}
              </Typography>
            )}
            {usedCouponCode && (
              <Typography variant="bodySm" muted fontWeight="thin">
                {`${couponCodeText}: ${usedCouponCode}`}
              </Typography>
            )}
            {reason && (
              <Typography variant="bodySm" muted fontWeight="thin">
                {`${reasonText}: ${reason}`}
              </Typography>
            )}
            {rejectionReason && (
              <Typography variant="bodySm" muted fontWeight="thin">
                {`${rejectionReasonText}: ${rejectionReason}`}
              </Typography>
            )}
            {((receiptFileUrl && receiptFileUrl.length > 0) || imageUrl) && (
              <Button
                className={styles['transaction-row__view-btn']}
                link
                onClick={!isPreview ? handleViewImage : undefined}
              >
                {imgViewText}
              </Button>
            )}
          </Stack>
          <Stack gap={0} align="end">
            <Typography variant="bodyMd" className={hidePoints ? styles.hidden : undefined}>
              {pointsContentMarkup}
            </Typography>

            <Typography variant="bodySm" muted fontWeight="thin">
              {transactionLabel}
            </Typography>
          </Stack>
        </Stack>
        {couponCode && (
          <Stack
            orientation="horizontal"
            align="center"
            justify="end"
            gap={0.7}
            className={styles['transaction-row__coupon-container']}
          >
            <Typography
              variant="bodySm"
              fontWeight="thin"
              className={styles['transaction-row__coupon-label']}
            >
              {couponCodeText}:
            </Typography>
            <CopyToClipboardInput
              value={couponCode}
              className={styles['transaction-row__coupon-input']}
              textAlign="center"
              borderStyle="dashed"
              onCopy={handleCopy}
            />
          </Stack>
        )}
        {rewardLink && (
          <Stack
            orientation="horizontal"
            align="center"
            justify="end"
            gap={0.7}
            className={styles['transaction-row__coupon-container']}
          >
            <Typography variant="bodySm" fontWeight="thin" nowrap>
              {rewardLinkText}:
            </Typography>
            <CopyToClipboardInput
              onClick={() => window.open(rewardLink, '_blank')}
              value={rewardLink}
              className={styles['transaction-row__reward-link-input']}
              textAlign="center"
              borderStyle="dashed"
              onCopy={handleCopy}
            />
          </Stack>
        )}
      </Stack>
    </Stack>
  );
}
