/* eslint-disable react/no-danger */
import { EUDSettings } from '@root/core/config';
import { Outlet, ScrollRestoration, useLocation } from 'react-router-dom';
import { ThemeProvider } from '@trueloyal-engineering/react-ui';
import {
  useAppNavigation,
  useHandleReduxErrors,
  useInitializeStore,
  useMessage,
  useGTMPageTracking,
  useLanguageHandler
} from '@root/hooks';
import { ToastContainer, toast } from 'react-toastify';
import { useEffect, useRef } from 'react';

export function App() {
  useGTMPageTracking();
  const { pathname, search } = useLocation();
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const { resetKey, shouldLoadInitialState } = useMessage();
  useInitializeStore({ shouldLoadInitialState });
  const { isAppRTL } = useLanguageHandler(window?.language ?? '');
  const errorHandler = (message: string) => {
    toast.error(message, { autoClose: false });
  };
  useHandleReduxErrors({ errorHandler });
  const { getScrollRestorationKey } = useAppNavigation();

  useEffect(() => {
    // Event when the react app is rendered. We can add listener from outside to perform some action when this event is triggered
    const event = new Event('rendered');
    document.dispatchEvent(event);
  }, []);

  useEffect(() => {
    scrollContainerRef.current?.scrollTo(0, 0);
  }, [pathname, search]);

  // TODO Replace with new carouselfrom new UI library where aria-hidden container will not have focusable children
  useEffect(() => {
    // WCAG: aria-hidden elements must not contain focusable elements.
    // The Carousel library sets aria-hidden="true" on .zrl-carousel__content but doesn't
    // pull focusable children out of the tab order. Strip the attribute and keep it off.
    const stripAriaHidden = () => {
      document
        .querySelectorAll<HTMLElement>(
          '.zrl-carousel__content[aria-hidden], .zrl-carousel__header[aria-hidden], .zrl-carousel__footer[aria-hidden]'
        )
        .forEach((el) => {
          el.removeAttribute('aria-hidden');
        });
    };

    stripAriaHidden();
    const observer = new MutationObserver(stripAriaHidden);
    observer.observe(document.body, {
      subtree: true,
      childList: true,
      attributeFilter: ['aria-hidden']
    });
    return () => observer.disconnect();
  }, []);

  return (
    <ThemeProvider extendThemeConfig={EUDSettings.getThemeConfig()}>
      <div id="zrl-frame-container" ref={scrollContainerRef}>
        <Outlet key={resetKey} />
        <ToastContainer position="top-center" theme="dark" rtl={isAppRTL} />
        <ScrollRestoration getKey={getScrollRestorationKey} />
      </div>
    </ThemeProvider>
  );
}
