import { Button, Stack } from '@trueloyal-engineering/react-ui';
import { Cancel as CancelIcon } from '@root/icons';
import styles from './files-list.module.css';

export interface FilesListProps {
  files: File[] | undefined;
  onRemove: (fileIndex: number) => void;
}

export function FilesList({ files, onRemove }: FilesListProps) {
  if (!files) {
    return null;
  }
  return (
    <Stack role="list" aria-label="File List" className="files-list">
      {Array.from(files).map((file, index) => (
        // eslint-disable-next-line react/no-array-index-key
        <div key={index} role="listitem" className={styles['files-list__item']}>
          <Button mono>{file.name}</Button>
          <Button
            id="remove-file-btn"
            iconOnly
            icon={<CancelIcon className="zrl-icon" fontSize="small" />}
            onClick={() => onRemove(index)}
          />
        </div>
      ))}
    </Stack>
  );
}
