import { PerkCard } from '@root/core/presets';
import { useAppNavigation } from '@root/hooks';
import { Stack, StackProps, classNames } from '@trueloyal-engineering/react-ui';
import { Perk } from '@root/store/slices/streakPerkSlice';
import styles from './perk-list.module.css';

export interface PerkListProps extends StackProps {
  isGuest: boolean;
  linkedSchemaRecordId: string;
  perks: Perk[] | undefined;
  className?: string;
}

export function PerkList({
  isGuest,
  linkedSchemaRecordId,
  perks,
  className,
  ...props
}: PerkListProps) {
  const { gotoMemberStreakPerk, gotoMemberStreakPerkLog } = useAppNavigation();

  const classes = classNames('perk-list', className);
  return (
    <Stack orientation="horizontal" wrapped justify="center" className={classes} {...props}>
      {perks && perks.length > 0
        ? perks.map((perk) => {
            return (
              <PerkCard
                perk={perk}
                className={styles['perk-list__perk-card']}
                isGuest={isGuest}
                onAction={() =>
                  perk.reward_log_id
                    ? gotoMemberStreakPerkLog(linkedSchemaRecordId, perk.id, perk.reward_log_id)
                    : gotoMemberStreakPerk(linkedSchemaRecordId, perk.id)
                }
              />
            );
          })
        : 'No perks available'}
    </Stack>
  );
}
