import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { AuthConfig, EUDSettings } from '@root/core/config';
import { ThemeHelpers } from '@root/core/helpers/theme';
import { ACTIVITY_IDS } from '@root/core/constants/activity.constants';
import {
  CTA_SHOW_ACTIVITIES,
  CTA_SHOW_ACTIVITY_REGEX,
  CTA_SHOW_FACEBOOK,
  CTA_SHOW_PINTEREST,
  CTA_SHOW_POINT_HISTORY,
  CTA_SHOW_REFERRAL,
  CTA_SHOW_REWARDS,
  CTA_SHOW_REWARD_REGEX,
  CTA_SHOW_TWITTER
} from '@root/core/constants/messages.constants';
import { SOURCE_ZINRELO_POPUP_WIDGET } from '@root/core/constants/auth.constants';
import {
  ChangeEUDSettingsMessageType,
  ChangeLabelMessageType,
  ChangeRouteMessageType,
  ChangeThemeVariablesMessageType,
  MessageHandler,
  MessageTypes,
  TestMessageType
} from './types';
import { useAppNavigation } from './useAppNavigation';

export function useMessage() {
  const navigate = useNavigate();
  const {
    gotoMemberActivity,
    gotoMemberPointsHistory,
    gotoMemberReward,
    gotoMemberActivities,
    gotoMemberRewards
  } = useAppNavigation();
  // Add resetKey to top component to re-initialize to change the configs etc.
  const [resetKey, setResetKey] = useState(Math.random);
  const [shouldLoadInitialState, setShouldLoadInitialState] = useState(
    AuthConfig.getInstance().source === SOURCE_ZINRELO_POPUP_WIDGET
      ? AuthConfig.isAuthenticated()
      : true
  );

  const forceInitialization = () => {
    setResetKey(Math.random());
    // Force a re-render or any other necessary actions to re-initialize the component
    // This might involve state updates or side effects depending on your component's logic
  };

  const changeRouteHandler: MessageHandler<ChangeRouteMessageType['payload']> = (payload) => {
    navigate(payload.route);
  };

  const testHandler: MessageHandler<TestMessageType['payload']> = (_payload) => {
    // Test handler for message validation
  };

  const changeLabelsHandler: MessageHandler<ChangeLabelMessageType['payload']> = (payload) => {
    EUDSettings.updateLabelsConfig(payload.updateSettings);
    if (payload.route) {
      navigate(payload.route);
    }
    forceInitialization();
  };

  const changeThemeVariablesHandler: MessageHandler<ChangeThemeVariablesMessageType['payload']> = (
    payload
  ) => {
    ThemeHelpers.updateThemeFromThemeSettings(payload.updateThemeVariables);
    if (payload.route) {
      navigate(payload.route);
    }
    forceInitialization();
  };

  const changeEUDSettingsHandler: MessageHandler<ChangeEUDSettingsMessageType['payload']> = (
    payload
  ) => {
    EUDSettings.updateEUDSettings(payload.updateSettings);
    if (payload.route) {
      navigate(payload.route);
    }
    forceInitialization();
  };

  const resumeDashboardRendering: MessageHandler<ChangeEUDSettingsMessageType['payload']> = (
    _payload
  ) => {
    setShouldLoadInitialState(true);
  };
  const MESSAGE_HANDLERS: Record<MessageTypes['type'], MessageHandler<MessageTypes['payload']>> = {
    changeRoute: changeRouteHandler,
    test: testHandler,
    changeLabels: changeLabelsHandler,
    changeThemeVariables: changeThemeVariablesHandler,
    changeEUDSettings: changeEUDSettingsHandler,
    resumeDashboardRendering
  };

  const handleCTA = (ctaCommand: string) => {
    switch (ctaCommand) {
      case CTA_SHOW_REFERRAL: {
        gotoMemberActivity(ACTIVITY_IDS.ZRL_REFERRAL_ACTIVITY);
        break;
      }
      case CTA_SHOW_FACEBOOK: {
        gotoMemberActivity(ACTIVITY_IDS.ZRL_SHARE_ON_FACEBOOK);
        break;
      }
      case CTA_SHOW_TWITTER: {
        gotoMemberActivity(ACTIVITY_IDS.ZRL_SHARE_ON_TWITTER);
        break;
      }
      case CTA_SHOW_PINTEREST: {
        gotoMemberActivity(ACTIVITY_IDS.ZRL_SHARE_ON_PINTEREST);
        break;
      }
      case CTA_SHOW_ACTIVITIES: {
        gotoMemberActivities();
        break;
      }
      case CTA_SHOW_REWARDS: {
        gotoMemberRewards();
        break;
      }
      case CTA_SHOW_POINT_HISTORY: {
        gotoMemberPointsHistory();
        break;
      }
      case String(ctaCommand.match(CTA_SHOW_REWARD_REGEX)): {
        gotoMemberReward(ctaCommand.replace('show_', ''));
        break;
      }
      case String(ctaCommand.match(CTA_SHOW_ACTIVITY_REGEX)): {
        gotoMemberActivity(ctaCommand.replace('show_', ''));
        break;
      }
      default:
        break;
    }
  };

  useEffect(() => {
    function handleMessage(ev: MessageEvent<MessageTypes>) {
      if (typeof ev.data === 'string') {
        // handle legacy cta events from parent
        handleCTA(ev.data);
      }
      if (typeof ev.data !== 'object') return;
      if (!ev.data.type) return;
      const { type, payload } = ev.data;
      if (Object.prototype.hasOwnProperty.call(MESSAGE_HANDLERS, type)) {
        MESSAGE_HANDLERS[type](payload);
      }
    }

    window.addEventListener('message', handleMessage);
    return () => {
      window.removeEventListener('message', handleMessage);
    };
  }, []);

  return {
    resetKey,
    shouldLoadInitialState
  };
}
