import { MemberOptIn } from '@root/containers';
import { EUDSettings } from '@root/core/config';
import { Page } from '@trueloyal-engineering/react-ui';

export function DefaultMemberOptInPage() {
  const { embed_page_url_patterns: embedURLPatterns } = EUDSettings.getInstance();

  const showAppBar = embedURLPatterns.length < 1;

  return (
    <Page showAppBar={showAppBar} className="member-optin-page">
      <Page.Body>
        <MemberOptIn />
      </Page.Body>
    </Page>
  );
}
