import { AuthConfig } from '@root/core/config';
import { Navigate, Outlet } from 'react-router-dom';
import { MemberBlockedPage, MemberOptInPage } from '@root/pages';
import { GUEST_BASE_PATH } from './paths';

export function PrivateRoute() {
  if (!AuthConfig.isAuthenticated()) {
    return <Navigate to={GUEST_BASE_PATH} />;
  }
  if (AuthConfig.isBlocked()) {
    return <MemberBlockedPage />;
  }
  if (AuthConfig.isOptedOut()) {
    return <MemberOptInPage />;
  }
  return <Outlet />;
}
