/* eslint-disable no-param-reassign */
import { createAsyncThunk, createSlice } from '@reduxjs/toolkit';
import { fetchData } from '@root/store/slices/mockApi/perks.api';
import { EUDSettings } from '@root/core/config';
import { RootState } from '@root/store';
import { CommonThunkError, CommonState } from '../types';
import { ListIdStateMapping } from './types';

export interface Perk {
  id: string;
  eud_title: string;
  eud_description: string;
  eud_image: string;
  eud_claim_button_label: string;
  eud_claim_confirmation_message: string;
  eud_claim_confirm_button_label: string;
  eud_claim_cancel_button_label: string;
  eud_post_claim_message: string;
  eud_post_claim_button_label: string;
  reward_log_id: string;
  coupon_code: string;
  reward_log_status: string;
  linked_schema_record_id: string;
  linked_schema_slug: string;
}

type ApiResponse<T> = {
  data: T;
};

export interface StreakPerkState extends CommonState {
  streakPerks: Record<string, Perk[]> | undefined;
}

const initialState: StreakPerkState = {
  streakPerks: undefined,
  status: 'idle',
  errorMessage: ''
};

export const fetchPerks = createAsyncThunk<
  Record<string, Array<Perk>> | undefined,
  ListIdStateMapping,
  { rejectValue: CommonThunkError }
>('streakPerks/fetch', async (listIdStateMapping, { rejectWithValue }) => {
  try {
    const response = await fetchData<ApiResponse<Perk[]>>(listIdStateMapping.listQueryParams);
    const streakPerkMapping: Record<string, Array<Perk>> = {};
    const perks = response?.data ?? [];
    streakPerkMapping[listIdStateMapping.id] = perks;
    return streakPerkMapping;
  } catch (error) {
    return rejectWithValue({
      errorMessage: EUDSettings.getInstance().content_settings.streak_section_error_state_message
    });
  }
});

export const perkSlice = createSlice({
  name: 'perk',
  initialState,
  reducers: {},
  extraReducers: (builder) => {
    builder.addCase(fetchPerks.fulfilled, (state, action) => {
      state.streakPerks = {
        ...state.streakPerks,
        ...action.payload
      };
      state.status = 'succeeded';
    });
    builder.addCase(fetchPerks.rejected, (state) => {
      state.status = 'failed';
    });
    builder.addCase(fetchPerks.pending, (state) => {
      state.status = 'pending';
    });
  }
});

export const selectStreakPerk = (
  state: RootState,
  streakId: string | undefined,
  perkId: string | undefined
) => {
  if (!streakId || !perkId) return null;
  const perks: Perk[] | undefined = state.streakPerks.streakPerks?.[streakId];
  const filteredPerks = perks?.filter((perk: Perk) => perk.id === perkId);
  if (filteredPerks) {
    return filteredPerks[0];
  }
  return null;
};

export const selectStreakPerks = (state: RootState, streakId: string | undefined) => {
  if (!streakId) return null;
  return state.streakPerks.streakPerks?.[streakId];
};

export default perkSlice.reducer;
