import { useAppSelector } from '@root/store';
import { Navigate, useParams } from 'react-router-dom';
import { Button, Page } from '@trueloyal-engineering/react-ui';
import { selectStreakPerk } from '@root/store/slices/streakPerkSlice';
import { EUDSettings } from '@root/core/config';
import { PerkDetails } from '@root/containers/perk/PerkDetail';
import { useAppNavigation, usePage } from '@root/hooks';
import { MEMBER_BASE_PATH, STREAKS_BASE_PATH } from '@root/router/paths';

export function DefaultPerkDetailsPage() {
  const { back } = useAppNavigation();
  const { id, perkId } = useParams();
  const {
    embed_page_url_patterns: embedURLPatterns,
    content_settings: {
      navigation_home_text: navigationHomeText,
      navigation_back_text: navigationBackText
    }
  } = EUDSettings.getInstance();
  const perk = useAppSelector((state) => selectStreakPerk(state, id, perkId));
  if (!perk) {
    return <Navigate to={`${MEMBER_BASE_PATH}/${STREAKS_BASE_PATH}/${id}`} replace />;
  }

  const { getBreadcrumbs } = usePage();

  const showAppBar = embedURLPatterns.length < 1;
  const breadcrumbs = [
    ...getBreadcrumbs(),
    <Button mono disabled>
      {perk.eud_title}
    </Button>
  ];
  return (
    <Page showAppBar={showAppBar} className="perk-details-page">
      <Page.Header
        title={perk.eud_title}
        prevPageTitle={navigationHomeText}
        onBack={back}
        breadcrumbs={breadcrumbs}
        backBtnLabel={navigationBackText}
      />
      <Page.Body>
        <PerkDetails perk={perk} />
      </Page.Body>
    </Page>
  );
}
