import React from 'react';
import { EUDSettings } from '@root/core/config';
import { Button, Page } from '@trueloyal-engineering/react-ui';
import { Navigate, useMatch, useParams } from 'react-router-dom';
import { selectStreak } from '@root/store/slices/streakSlice';
import { useAppSelector } from '@root/store';
import { replaceLabels } from '@root/core/utils/textUtils';
import { StreakDetails } from '@root/containers/streaks/StreakDetail/StreakDetails';
import { useAppNavigation, usePage } from '@root/hooks';
import { GUEST_BASE_PATH, MEMBER_BASE_PATH, STREAKS_BASE_PATH } from '@root/router/paths';
import {
  selectStreakRuns,
  selectStreakUserProgress
} from '@root/store/slices/streakUserProgressSlice';

export function DefaultStreakDetailsPage() {
  const { back } = useAppNavigation();
  const { id } = useParams();
  const match = useMatch(':from/streaks/:id');
  const from = match?.params.from;
  const isGuest = `/${from}` === GUEST_BASE_PATH;

  const {
    embed_page_url_patterns: embedURLPatterns,
    content_settings: {
      navigation_home_text: navigationHomeText,
      navigation_back_text: navigationBackText
    }
  } = EUDSettings.getInstance();
  const streak = useAppSelector((state) => selectStreak(state, id));
  const streakUserProgress = useAppSelector((state) => selectStreakUserProgress(state, id));
  const streakRuns = useAppSelector((state) => selectStreakRuns(state, id));
  const { getBreadcrumbs } = usePage();

  if (!streak) {
    if (isGuest) {
      return <Navigate to={`${GUEST_BASE_PATH}/${STREAKS_BASE_PATH}`} replace />;
    }
    return <Navigate to={`${MEMBER_BASE_PATH}/${STREAKS_BASE_PATH}`} replace />;
  }

  const nameHeader = replaceLabels(streak.eud_headline, {
    '{{STREAK_COUNT}}': streak.eud_streak_completion_count,
    '{{STREAK_INTERVAL}}': streak.eud_streak_unit
  });

  const showAppBar = embedURLPatterns.length < 1;
  const breadcrumbs = [
    ...getBreadcrumbs(),
    <Button mono disabled>
      {nameHeader}
    </Button>
  ];

  return (
    <Page showAppBar={showAppBar} className="streak-details-page">
      <Page.Header
        title={nameHeader}
        prevPageTitle={navigationHomeText}
        onBack={back}
        breadcrumbs={breadcrumbs}
        backBtnLabel={navigationBackText}
      />
      <Page.Body data-streak_id={streak.id}>
        <StreakDetails
          streakUserProgress={streakUserProgress}
          streakRuns={streakRuns}
          streak={streak}
          isGuest={isGuest}
        />
      </Page.Body>
    </Page>
  );
}
