import { Stack, Typography } from '@trueloyal-engineering/react-ui';
import { Icon } from '@root/components';
import styles from './benefits.module.css';

export interface BenefitsProps {
  benefits: string[];
}

export function Benefits({ benefits }: BenefitsProps) {
  return (
    <Stack padding={1.2} role="list" gap={1.3}>
      {benefits.map((benefit) => (
        <Typography fontWeight="thin" key={benefit}>
          <Stack
            orientation="horizontal"
            align="start"
            justify="start"
            gap={0.5}
            role="listitem"
            style={{ height: 'auto' }}
          >
            <Icon name="check_circle" size={16} className={styles.benefit__icon} />
            <span> {benefit} </span>
          </Stack>
        </Typography>
      ))}
    </Stack>
  );
}
