import { ApiClient } from '@root/core/api';
import { AuthConfig } from '@root/core/config';

// TODO : should come from env
const DEFAULT_GAMIFICATION_BASE_URL = 'api.trueloyal.com';

export const getGamificationBaseUrl = (): string => {
  try {
    if (AuthConfig.isPreview()) {
      return '';
    }
    return ApiClient.getInstance()?.client?.baseUrl || DEFAULT_GAMIFICATION_BASE_URL;
  } catch (error) {
    // eslint-disable-next-line no-console
    console.error('Error getting gamification base URL:', error);
    return DEFAULT_GAMIFICATION_BASE_URL;
  }
};
