import TagManager from 'react-gtm-module';
import { getURLParameter } from '@root/core/utils/paramUtils';
import { ApiClient } from './core/api';
import { AuthConfig, MerchantConfig, EUDSettings, IntegrationSettings } from './core/config';

export interface InitAppConfig {
  apiBaseURL?: string;
  partnerId: string;
  accessToken?: string;
  language?: string;
  isPreview?: boolean;
  eudSettings?: any;
  merchantConfig?: any;
  memberInfo?: any;
  integrationSettings?: any;
}

export function initApp(config: InitAppConfig) {
  const {
    apiBaseURL: providedApiBaseURL,
    partnerId,
    accessToken,
    language,
    isPreview = false,
    eudSettings = {},
    merchantConfig = {},
    memberInfo = {},
    integrationSettings = {}
  } = config;

  let apiBaseURL: string;

  // Use provided apiBaseURL or derive from script src
  if (providedApiBaseURL) {
    apiBaseURL = providedApiBaseURL;
  } else {
    const currentScript = document.currentScript as HTMLScriptElement | null;
    if (currentScript?.src) {
      const scriptUrl = new URL(currentScript.src);
      apiBaseURL = `https://${scriptUrl.hostname.replace(/^([^.]+)/, 'api')}`;
    } else {
      apiBaseURL = 'https://api.trueloyal.com';
    }
  }

  if (isPreview) {
    // in preview mode append /mock to every api request of zinrelo api sdk to returned mocked response
    apiBaseURL += '/mock';
  }

  EUDSettings.initialize(eudSettings);

  ApiClient.initialize({
    baseUrl: apiBaseURL,
    partnerId,
    authToken: accessToken,
    language
  });

  MerchantConfig.initialize(merchantConfig);

  AuthConfig.initialize({
    accessToken,
    memberInfo,
    isPreview,
    source: getURLParameter('source') ?? ''
  });

  IntegrationSettings.initialize(integrationSettings);

  if (process.env.REACT_APP_GTM_ID) {
    TagManager.initialize({
      gtmId: process.env.REACT_APP_GTM_ID,
      dataLayer: {
        partnerId,
        memberId: memberInfo?.member_id ?? 'Guest'
      }
    });
  }
}
