import { isFileTypeValid } from '@root/core/utils/fileUtils';
import { useRef, useState } from 'react';
import { toast } from 'react-toastify';

export type ErrorLabels = {
  MAX_FILE_SIZE_REACHED: string;
  MAX_FILE_NUMBER_REACHED: string;
};

export interface UseFileProps {
  maxFileSizeInMB: number;
  maxNumberOfFiles: number;
  errorLabels: ErrorLabels;
  allowedExtensions: string[];
}

export function useFile({
  maxFileSizeInMB,
  maxNumberOfFiles,
  errorLabels,
  allowedExtensions
}: UseFileProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [files, setFiles] = useState<File[]>([]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files) {
      return;
    }
    if (!e.target.files[0]) {
      return;
    }

    const selectedFiles = [...files, ...Array.from(e.target.files)];
    if (inputRef.current) {
      // reset input for next selection
      inputRef.current.value = '';
    }
    if (selectedFiles.length > maxNumberOfFiles) {
      toast.error(errorLabels.MAX_FILE_NUMBER_REACHED);
      return;
    }
    // eslint-disable-next-line no-plusplus
    for (let index = 0; index < selectedFiles.length; index++) {
      const fileSize = selectedFiles[index].size / 1024 / 1024;
      if (
        fileSize > maxFileSizeInMB ||
        !isFileTypeValid(selectedFiles[index].name, allowedExtensions)
      ) {
        toast.error(errorLabels.MAX_FILE_SIZE_REACHED);
        return;
      }
    }
    setFiles(selectedFiles);
  };

  const selectFile = () => {
    if (!inputRef.current) return;
    inputRef.current?.click();
  };

  const removeAllFiles = () => {
    if (!files) return;
    setFiles([]);
  };

  const removeFile = (removeIndex: number) => {
    if (!files) return;
    let updatedFiles = Array.from(files);
    updatedFiles = updatedFiles.filter((_, index) => removeIndex !== index);
    setFiles(updatedFiles);
  };

  return { inputRef, handleFileChange, selectFile, removeAllFiles, removeFile, files, setFiles };
}
