import { Instagram as InstagramIcon } from '@root/icons';
import InstagramIconImage from '@root/assets/images/InstagramIcon.png';
import TikTokIconImage from '@root/assets/images/tiktokIcon.png';
import {
  GATSBY_INSTAGRAM_ACTIVITIES,
  GATSBY_TIKTOK_ACTIVITIES
} from '@root/core/constants/activity.constants';

export const getActivityIcons = (activityId: string): string => {
  if (GATSBY_INSTAGRAM_ACTIVITIES.has(activityId)) {
    return InstagramIconImage;
  }

  if (GATSBY_TIKTOK_ACTIVITIES.has(activityId)) {
    return TikTokIconImage;
  }

  return '';
};

