export const getButtonIcon = (activityId: string): JSX.Element | null => {
  if (GATSBY_INSTAGRAM_ACTIVITIES.has(activityId)) {
    return <InstagramIcon />;
  }

  if (GATSBY_TIKTOK_ACTIVITIES.has(activityId)) {
    return <TikTokIcon />;
  }

  return null;
};
