import { Card, CardProps, Stack, Typography, classNames } from '@trueloyal-engineering/react-ui';
import { KeyboardEvent, ReactNode, useCallback } from 'react';
import { ChevronRight } from '@root/icons';
import styles from './navigation-card.module.css';

export interface NavigationCardProps extends CardProps {
  icon?: ReactNode;
  banner?: ReactNode;
  title: string;
  onClick?: () => void;
  className?: string;
}

export function NavigationCard({
  icon,
  title,
  onClick,
  className,
  banner,
  ...props
}: NavigationCardProps) {
  const classes = classNames(styles['navigation-card'], className);

  const handleKeyDown = useCallback(
    (e: KeyboardEvent<HTMLDivElement>) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        onClick?.();
      }
    },
    [onClick]
  );

  return (
    <Card
      className={classes}
      onClick={onClick}
      onKeyDown={handleKeyDown}
      role="button"
      {...props}
      tabIndex={0}
    >
      <Stack padding={1.25} orientation="horizontal" justify="center" align="start">
        {icon}
        <Stack>
          <Typography className={styles['navigation-card__title']}>{title}</Typography>
          {banner}
        </Stack>
        <ChevronRight className="zrl-icon zrl-icon--flip-on-rtl" width={24} height={24} />
      </Stack>
    </Card>
  );
}
