import DOMPurify from 'dompurify';

export function sanitizeHTML(htmlString?: string) {
  return DOMPurify.sanitize(htmlString ?? '', {
    // Allowing iframe tags and attributes unless there is native support for features like paper form
    ADD_TAGS: ['iframe', 'tint-form'],
    ADD_ATTR: [
      'allow',
      'allowfullscreen',
      'frameborder',
      'scrolling',
      'onload',
      'onsubmit',
      'target',
      'form-id',
      'team-id',
      'form-values',
      'form-locale',
      'metadata',
      'access-token'
    ]
  });
}
