export const isEmpty = (value: unknown) => {
  return (
    value === undefined ||
    value === null ||
    (typeof value === 'object' && Object.keys(value).length === 0) ||
    (typeof value === 'string' && value.trim().length === 0)
  )
}

export const convertObjectValuesToString = (obj: Record<string, unknown>): undefined | Record<string, unknown> => {
  let returnValue
  try {
    if (obj && typeof obj === 'object') {
      const objNew: Record<string, unknown> = {}
      const keys = Object.keys(obj)

      for (let idx = 0; idx < keys.length; idx++) {
        const key = keys[idx]
        if (typeof obj[key] === 'object') {
          objNew[key] = JSON.stringify(obj[key])
        } else {
          objNew[key] = obj[key]
        }
      }

      if (!isEmpty(objNew)) {
        returnValue = objNew
      }
    }
  } catch {
    returnValue = undefined
  }
  return returnValue
}
