import { ActivityHelper } from '@root/core/helpers';
import { ErrorHandler } from '@root/core/helpers/error';
import { useAppDispatch } from '@root/store';
import { fetchMember } from '@root/store/slices/memberSlice';
import { Activity } from '@trueloyal-engineering/ui-api-sdk';
import { useState } from 'react';
import { toast } from 'react-toastify';

export interface UseUploadPhotoActivityProps {
  activity: Activity;
  files: File[];
}
export function useUploadPhotoActivity({ activity, files }: UseUploadPhotoActivityProps) {
  const [loading, setLoading] = useState(false);
  const [showCongratulation, setShowCongratulation] = useState(false);
  const dispatch = useAppDispatch();

  const uploadFile = async () => {
    if (files.length < 1) {
      toast('Please select file to upload');
      return;
    }
    try {
      setLoading(true);
      const response = await ActivityHelper.performUploadPhotoActivity(files[0]);
      if (response.success) {
        dispatch(fetchMember());
        setShowCongratulation(true);
      }
    } catch (error) {
      const errorMessage = ErrorHandler.resolveActivityErrorMessage(activity, error);
      toast(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  return {
    loading,
    showCongratulation,
    uploadFile
  };
}
