/* eslint-disable no-param-reassign */
import { createAsyncThunk, createSlice } from '@reduxjs/toolkit';
import { EUDSettings } from '@root/core/config';
import { StreakHelper } from '@root/core/helpers/streak';
import { RootState } from '@root/store';
import { CommonThunkError, CommonState } from '../types';
import { fetchStreakChallengeUserProgress } from './mockApi/streakChallengeStatus.api';
import { ListQueryParams } from './types';

export interface StreakUserProgress {
  id: string;
  progress: number;
  linked_schema_slug: string;
  linked_schema_record_id: string;
  progress_status: string;
  created_at: string;
}

type ApiResponse<T> = {
  data: T;
};

export interface StreakUserProgressState extends CommonState {
  streakUserProgress: Record<string, StreakUserProgress[]> | undefined;
}

const initialState: StreakUserProgressState = {
  streakUserProgress: undefined,
  status: 'idle',
  errorMessage: ''
};

export const fetchStreakUserProgress = createAsyncThunk<
  Record<string, StreakUserProgress[]> | undefined,
  ListQueryParams,
  { rejectValue: CommonThunkError }
>('streakUserProgress/fetch', async (queryParams, { rejectWithValue }) => {
  try {
    const response =
      await fetchStreakChallengeUserProgress<ApiResponse<StreakUserProgress[]>>(queryParams);
    const streakUserProgressMapping: Record<string, StreakUserProgress[]> = {};
    if (response && response.data) {
      response.data.forEach((item) => {
        const runs = streakUserProgressMapping[item.linked_schema_record_id];
        if (runs) {
          runs.push(item);
        } else {
          streakUserProgressMapping[item.linked_schema_record_id] = [item];
        }
      });
      // Order is applied in the selectors; see StreakHelper.currentRun.
      return streakUserProgressMapping;
    }
    return {};
  } catch (error) {
    return rejectWithValue({
      errorMessage: EUDSettings.getInstance().content_settings.streak_section_error_state_message
    });
  }
});

export const streakUserProgressSlice = createSlice({
  name: 'streakUserProgress',
  initialState,
  reducers: {},
  extraReducers: (builder) => {
    builder.addCase(fetchStreakUserProgress.fulfilled, (state, action) => {
      state.streakUserProgress = action.payload;
      state.status = 'succeeded';
    });
    builder.addCase(fetchStreakUserProgress.rejected, (state) => {
      state.status = 'failed';
    });
    builder.addCase(fetchStreakUserProgress.pending, (state) => {
      state.status = 'pending';
    });
  }
});

export const selectStreakRuns = (state: RootState, streakId: string | undefined) => {
  if (!streakId) return undefined;
  return state.streakUserProgress.streakUserProgress?.[streakId];
};

export const selectStreakUserProgress = (state: RootState, streakId: string | undefined) => {
  if (!streakId) return null;
  return StreakHelper.currentRun(selectStreakRuns(state, streakId));
};

export default streakUserProgressSlice.reducer;
