import React, { useEffect, useMemo, useState } from 'react';
import { Stack, Typography } from '@trueloyal-engineering/react-ui';
import StreaksFlame from '@root/containers/streaks/StreaksFlame/StreaksFlame';
import { ReactComponent as CompletedStreakIcon } from '@root/assets/images/CompletedStreakIcon.svg';
import { ReactComponent as BrokenStreakIcon } from '@root/assets/images/BrokenStreakIcon.svg';
import { ReactComponent as CelebrationStreakIcon } from '@root/assets/images/CelebrationStreakIcon.svg';
import { ReactComponent as SadStreakIcon } from '@root/assets/images/SadStreakIcon.svg';
import { ReactComponent as PauseIcon } from '@root/assets/images/Pause.svg';
import { ReactComponent as PausedStreakIcon } from '@root/assets/images/PausedStreakIcon.svg';
import { Streak } from '@root/store/slices/streakSlice';
import { StreakUserProgress } from '@root/store/slices/streakUserProgressSlice';
import { Perk, selectStreakPerks } from '@root/store/slices/streakPerkSlice';
import { useAppSelector } from '@root/store';
import { PerkList } from '@root/containers/perk/PerkList';
import { Divider } from '@root/components/Divider';
import { useStreakPerks } from '@root/hooks/useStreakPerks';
import { usePerkLogs } from '@root/hooks/usePerkLogs';
import { AuthConfig } from '@root/core/config';
import { StreakHelper } from '@root/core/helpers/streak';
import { formatDateString } from '@root/core/utils/dateUtils';
import { StreakPreviousRuns } from './StreakPreviousRuns';
import styles from './streak-details.module.css';

export interface StreakDetailsProps {
  streakUserProgress?: StreakUserProgress | null;
  /** Every run of this streak. Absent for guests. */
  streakRuns?: StreakUserProgress[];
  streak: Streak;
  isGuest?: boolean;
}

export function StreakDetails({
  streakUserProgress,
  streakRuns,
  streak,
  isGuest = true
}: StreakDetailsProps) {
  const isPreview = AuthConfig.isPreview();
  let userProgress = streakUserProgress?.progress ?? 0;
  if (isPreview && !isGuest) {
    userProgress = 2;
  }
  const { nameHeader, streakValidity, userProgressText, streakBrokenText, streakCompletionText } =
    StreakHelper.getStreakLabels(streak, userProgress);
  const streakPerks = useAppSelector((state) => selectStreakPerks(state, streak.id));
  useStreakPerks({ streak });
  const allPerkLogs = useAppSelector((state) => state.perkLogs.perkLogs);
  usePerkLogs({ streak });
  const { isStreakRunsEnabled } = StreakHelper;
  const sortedRuns = useMemo(
    () => (isStreakRunsEnabled ? StreakHelper.sortedRuns(streakRuns) : []),
    [isStreakRunsEnabled, streakRuns]
  );
  const [perksResponse, setPerksResponse] = useState<Perk[] | undefined>();
  useEffect(() => {
    if (streakPerks && streakPerks.length > 0) {
      const perks: Perk[] = [];
      streakPerks.forEach((perk) => {
        const logsForPerk = allPerkLogs?.[perk.id] ?? [];
        const perkLogs = isStreakRunsEnabled
          ? StreakHelper.perkLogsForRun(logsForPerk, sortedRuns, streakUserProgress ?? undefined)
          : logsForPerk;
        if (perkLogs.length > 0) {
          perkLogs.forEach((perkLog) => {
            perks.push({
              ...perk,
              reward_log_id: perkLog.id,
              reward_log_status: perkLog.reward_log_status,
              coupon_code: perkLog.coupon_code,
              linked_schema_record_id: perkLog.linked_schema_record_id,
              linked_schema_slug: perkLog.linked_schema_slug
            });
          });
        } else {
          perks.push(perk);
        }
      });
      setPerksResponse(perks);
    }
  }, [streakPerks, allPerkLogs, isStreakRunsEnabled, sortedRuns, streakUserProgress]);

  const isStreakPaused = streak?.status === 'manual_paused';

  return (
    <div className={styles['streak-details']} data-streak_id={streak.id}>
      <Stack gap={0} padding={0.7} align="start" orientation="horizontal">
        <div className={styles['streak-details__image-container']}>
          {isStreakPaused ? (
            <PausedStreakIcon className={styles['streak-details__image-container']} />
          ) : (
            <>
              {(!streakUserProgress || streakUserProgress?.progress_status === 'in_progress') && (
                <StreaksFlame digit={userProgress} />
              )}
              {streakUserProgress?.progress_status === 'completed' && (
                <CompletedStreakIcon className={styles['streak-details__image-container']} />
              )}
              {streakUserProgress?.progress_status === 'broken' && (
                <BrokenStreakIcon className={styles['streak-details__image-container']} />
              )}
            </>
          )}
        </div>
        <Stack gap={0.6} padding={0.7} align="start" orientation="vertical">
          <Typography trunc={2} title={nameHeader} variant="header2xl" fontWeight="bold">
            {nameHeader}
          </Typography>
          <Typography fontWeight="thin" muted>
            {streak.eud_message}
          </Typography>
        </Stack>
      </Stack>
      {isStreakPaused || userProgress !== 0 ? (
        <Stack gap={0.6} padding={0.7} align="center" orientation="horizontal">
          <div className={styles['streak-details__chip']}>
            <Stack gap={0.7} align="center" orientation="horizontal">
              {isStreakPaused ? (
                <div className={styles['streak-details__chip-image-container']}>
                  <PauseIcon width={18} height={18} />
                  <Typography muted fontWeight="thin" variant="bodySm">
                    {streak.eud_manual_paused_text}
                  </Typography>
                </div>
              ) : (
                <>
                  {(!streakUserProgress ||
                    streakUserProgress?.progress_status === 'in_progress') && (
                    <div className={styles['streak-details__chip-image-container']}>
                      <CelebrationStreakIcon />
                      <Typography muted fontWeight="thin" variant="bodySm">
                        {userProgressText}
                      </Typography>
                    </div>
                  )}
                  {streakUserProgress?.progress_status === 'completed' && (
                    <div className={styles['streak-details__chip-image-container']}>
                      <CelebrationStreakIcon />
                      <Typography muted fontWeight="thin" variant="bodySm">
                        {streakCompletionText}
                      </Typography>
                    </div>
                  )}
                  {streakUserProgress?.progress_status === 'broken' && (
                    <div className={styles['streak-details__chip-image-container']}>
                      <SadStreakIcon />
                      <Typography muted fontWeight="thin" variant="bodySm">
                        {streakBrokenText}
                      </Typography>
                    </div>
                  )}
                </>
              )}
            </Stack>
          </div>
        </Stack>
      ) : undefined}
      <Stack gap={0.6} padding={0.7} align="start" orientation="vertical">
        <Typography fontWeight="thin" variant="bodySm" muted>
          {streak?.status !== 'scheduled' && streak?.status !== 'auto_paused'
            ? streakValidity
            : `Starts ${formatDateString(streak.start_at, 'MMM d, yyyy')}`}
        </Typography>
      </Stack>
      <Stack gap={0.6} padding={0.7} align="start" orientation="vertical">
        <Divider />
      </Stack>
      {perksResponse && (
        <div className={styles['streak-details__perks-container']}>
          <PerkList isGuest={isGuest} linkedSchemaRecordId={streak.id} perks={perksResponse} />
        </div>
      )}
      {isStreakRunsEnabled && sortedRuns.length > 0 && streakPerks && (
        <StreakPreviousRuns
          streakId={streak.id}
          runs={sortedRuns}
          streakPerks={streakPerks}
          allPerkLogs={allPerkLogs}
          isGuest={isGuest}
        />
      )}
    </div>
  );
}
