import { OPERATORS } from '@root/core/constants/operator.constants';
import { QueryBuilder } from '@root/core/helpers/querybuilder';
import { ListQueryParams, useAppDispatch, useAppSelector } from '@root/store';
import { fetchPerks, selectStreakPerks } from '@root/store/slices/streakPerkSlice';
import { Streak } from '@root/store/slices/streakSlice';
import { useEffect } from 'react';

export interface UseStreakPerksProps {
  streak: Streak;
}

export function useStreakPerks({ streak }: UseStreakPerksProps) {
  const dispatch = useAppDispatch();
  const streakPerks = useAppSelector((state) => selectStreakPerks(state, streak.id));

  useEffect(() => {
    if (streak?.id && streak?.rewards?.length > 0 && !streakPerks) {
      const dataFilters: ListQueryParams = {
        language: 'en-us',
        query: QueryBuilder.buildQueryForOneCondWithAndOp({
          field_slug: 'id',
          operator: OPERATORS.IN,
          field_value: streak.rewards
        })
      };
      dispatch(fetchPerks({ id: streak.id, listQueryParams: dataFilters }));
    }
  }, [streak, streakPerks]);
}
