import { ThemeConfig, extendTheme } from '@trueloyal-engineering/react-ui';
import { ThemeSettings } from '../config/types';
import { THEME_VARIABLES_MAPPING } from '../constants/theme.constants';

export class ThemeHelpers {
  public static getCSSVariablesFromThemeSettings(themeSettings: ThemeSettings) {
    const cssVariables: Record<string, string> = {};
    Object.keys(themeSettings).forEach((key) => {
      const themeSettingsKey = key as keyof ThemeSettings;
      const themeSettingValue = themeSettings[themeSettingsKey];
      const isSettingsKeyValid =
        themeSettingValue !== undefined &&
        themeSettingValue !== '' &&
        Object.prototype.hasOwnProperty.call(THEME_VARIABLES_MAPPING, themeSettingsKey);

      if (isSettingsKeyValid) {
        cssVariables[THEME_VARIABLES_MAPPING[themeSettingsKey]] = themeSettingValue as string;
      }
    });
    return cssVariables;
  }

  public static getRawThemeConfigFromThemeSettings(themeSettings: ThemeSettings): ThemeConfig {
    return {
      raw: this.getCSSVariablesFromThemeSettings(themeSettings)
    };
  }

  public static updateThemeFromThemeSettings(updateThemeSettings: Partial<ThemeSettings>) {
    const themeConfig = this.getRawThemeConfigFromThemeSettings(updateThemeSettings);
    extendTheme(themeConfig);
  }
}
