/* eslint-disable no-param-reassign */
import { Tier } from '@trueloyal-engineering/ui-api-sdk';
import { EUDSettings, MerchantConfig } from '../config';
import { LabelHelpers } from './label';
import { formatNumber } from '../utils/textUtils';
import { TIER_QUALIFICATION_SPEND_BASED } from '../constants/tier.constants';

export class TierHelper {
  public static getNextTier(currentTierId: string, tiers: Tier[] | undefined) {
    if (!tiers || !currentTierId) return undefined;
    const filteredTiers = tiers.filter((tier) => tier.level_program_type !== 'conditional');
    const sortedTiers = filteredTiers.slice().sort((a, b) => a.minimum_points - b.minimum_points);
    const currentTierIndex = sortedTiers.findIndex((tier) => tier.tier_id === currentTierId);
    return currentTierIndex >= 0 ? sortedTiers?.[currentTierIndex + 1] : undefined;
  }

  public static getBenefitDescription(
    nextTier: Tier | undefined,
    nextTierRequiredUnits: number
  ): string {
    const {
      tier_benefits_page_description_if_next_tier_present: remainingForNextTierText,
      tier_benefits_page_description_if_next_tier_not_present: enjoyTierBenefitsText
    } = EUDSettings.getInstance().content_settings;

    const hasNextTierAvailable = nextTier;

    // If the tier is downgraded manually the next tier required points will go negative
    // in that case we will show the top tier benefits only
    const hasRequiredUnitsForNextTier = nextTierRequiredUnits > 0;

    const benefitDescriptionText =
      hasNextTierAvailable && hasRequiredUnitsForNextTier
        ? remainingForNextTierText
        : enjoyTierBenefitsText;

    return LabelHelpers.replaceTierBenefitDescriptionText(
      benefitDescriptionText,
      nextTierRequiredUnits,
      nextTier?.name
    );
  }

  public static getTierTilesSubTitle(nextTierUnits: number | undefined, minimumUnits: number) {
    const { storeCurrencySymbol, tierQualificationCriteria } = MerchantConfig.getInstance();
    const { tier_qualification_units_label: tierText } = EUDSettings.getInstance().content_settings;
    if (minimumUnits === null) {
      return '';
    }
    const currencySymbol =
      tierQualificationCriteria === TIER_QUALIFICATION_SPEND_BASED ? storeCurrencySymbol : '';
    const subTitle = nextTierUnits
      ? `${currencySymbol}${formatNumber(minimumUnits)} - ${currencySymbol}${formatNumber(
          nextTierUnits - 1
        )} ${tierText}`
      : `> ${currencySymbol}${formatNumber(minimumUnits)} ${tierText}`;
    return subTitle;
  }

  public static getTierValidityText(currentTier: string, expiryDate: string): string {
    const { tier_benefits_page_conditional_tier_expiry_text: conditionalTierExpiryText } =
      EUDSettings.getInstance().content_settings;

    return LabelHelpers.replaceTierValidityExpiryText(
      conditionalTierExpiryText,
      currentTier,
      expiryDate
    );
  }
}
