* {
  font-family: var(--zrl-global-body-font-family);
}

html {
  font-size: var(--zrl-text-base-font-size);
}

.material-icons {
  display: inline-flex;
  vertical-align: top;
}

.material-symbols-rounded {
  font-variation-settings:
    'FILL' 0,
    'wght' 400,
    'GRAD' 0,
    'opsz' 24
}

#zrl-frame-root {
  font-size: 14px;
  height: 100%;
  overflow: hidden;
  position: relative;
}

#zrl-frame-container {
  height: 100%;
  overflow: scroll;
  
  container-type: inline-size;
  container-name: zrl-frame;
}

#zrl-frame-container::-webkit-scrollbar{
  display: none;
}

@container zrl-frame (min-width: 48em) {
  .zrl-card__collapsible-section-footer {
    display: none;
  }

  .zrl-container_base {
    max-width: 1024px;
  }
}

.zrl-typography--titled {
  text-align: left;
}

@media (min-width: 54rem) {
  .zrl-container_base {
    width: var(--zrl-container-width);
  }
}

@container zrl-frame (min-width: 48em) {
  
  .zrl-button--full-width-on-sm {
    width: -webkit-fit-content;
    width: -moz-fit-content;
    width: fit-content;
  }

  
  .zrl-carousel__controls {
    position: absolute;
    inset-inline-end: 0;
    top: 0;
  }

  .zrl-carousel__slides--contained {
    justify-content: center;
    width: 100%;
  }

  
  .zrl-image-carousel__control-prev,
  .zrl-image-carousel__control-next {
    position: static;
    position: initial;
  }

  
  .zrl-layout__content {
    flex: 0 1;
    margin-bottom: 2rem;
  }

  .zrl-layout__footer {
    all: unset;
  }

  .zrl-layout {
    display: flex;
    min-height: auto;
    flex-direction: column;
    gap: 1rem;
  }
}

/* Fix: Footer should be positioned relative to shadow root, not viewport */
.zrl-layout__footer {
  position: -webkit-sticky;
  position: sticky;
  bottom: 0;
  left: 0;
  right: 0;
}

@container zrl-frame (min-width: 48em) {
  .zrl-layout__footer {
    position: static;
  }

  
  .zrl-page__body {
    border: var(--zrl-page-border);
    border-radius: var(--zrl-page-border-radius);
    padding: var(--zrl-page-padding-desktop);
    margin-top: 1.5em;
  }

  .zrl-page__header {
    display: none;
  }

  .zrl-page_base {
    max-width: 60em;
    border: none;
    margin: auto;
  }
}

@container zrl-frame (min-width: 48rem) {
  .zrl-basic-table__row__cell {
    padding: var(--basic-table-row-cell-px-desktop) var(--basic-table-row-cell-py-desktop);
  }

  .zrl-image-carousel--stretch-to-page-body {
    margin-left: calc(-1 * var(--zrl-page-pl-desktop));
    margin-right: 0;
    width: calc(100% + var(--zrl-page-pl-desktop) + var(--zrl-page-pr-desktop));
  }
}

:dir(rtl) {
  .zrl-icons,
  .zrl-icon--flip-on-rtl,
  .material-symbols-rounded {
    transform: scaleX(-1);
  }
}

.zrl-button_base:focus-visible,
.zrl-card_base:focus-visible,
.zrl-accordion-header button:focus-visible,
.zrl-option-list__toggle:focus-visible,
.zrl-input-field__input:focus-visible,
.navigation-card:focus-visible,
a:focus-visible,
[role="button"]:focus-visible,
[tabindex]:focus-visible {
  outline: 2px solid #3A70E2;
  outline: 2px solid var(--zrl-global-primary-color, #3A70E2);
  outline-offset: 2px;
}

.zrl-progress__image {
  background-color: var(--zrl-global-color-bg);
}

.zrl-page_base {
  min-height: auto;
}
