import { configureStore } from '@reduxjs/toolkit';
import { TypedUseSelectorHook, useDispatch, useSelector } from 'react-redux';
import memberReducer from './slices/memberSlice';
import activityReducer from './slices/activitySlice';
import rewardReducer from './slices/rewardSlice';
import tierReducer from './slices/tierSlice';
import streakReducer from './slices/streakSlice';
import transactionReducer from './slices/transactionSlice';
import streakUserProgressReducer from './slices/streakUserProgressSlice';
import streakPerksReducer from './slices/streakPerkSlice';
import perkLogReducer from './slices/perkLogSlice';

// Factory function to create a new store instance (for multiple web components)
export const createStore = (memberInfo?: any) => {
  const preloadedState = {
    member: {
      memberDetails: memberInfo || undefined,
      status: 'idle' as const,
      errorMessage: ''
    }
  };

  return configureStore({
    reducer: {
      member: memberReducer,
      activity: activityReducer,
      reward: rewardReducer,
      tier: tierReducer,
      transaction: transactionReducer,
      streak: streakReducer,
      streakUserProgress: streakUserProgressReducer,
      streakPerks: streakPerksReducer,
      perkLogs: perkLogReducer
    },
    preloadedState
  });
};

// Default store instance (for backward compatibility)
const store = createStore((window as any).memberInfo);

export type AppDispatch = typeof store.dispatch;
export const useAppDispatch: () => AppDispatch = useDispatch; // Export a hook that can be reused to resolve types

export type RootState = ReturnType<typeof store.getState>;
export const useAppSelector: TypedUseSelectorHook<RootState> = useSelector;

export type AppStore = typeof store;

export default store;

export * from './slices/types';
