import { ActivityHeader } from '@root/components';
import { Stack } from '@trueloyal-engineering/react-ui';
import { Activity } from '@trueloyal-engineering/ui-api-sdk';

export interface GenericActivityProps {
  activity: Activity;
}

export function GenericActivity({ activity }: GenericActivityProps) {
  const {
    enduser_activity_short_description: shortDescription,
    enduser_activity_description_html: descriptionHTML,
    extra_config: extraConfig,
    earnpoints_button_label: tagLabel
  } = activity;

  const description = extraConfig?.reward_instruction_text ?? descriptionHTML;

  return (
    <Stack className="generic-activity">
      <ActivityHeader tagLabel={tagLabel} title={shortDescription} description={description} />
    </Stack>
  );
}
