/* eslint-disable no-param-reassign */
import { PayloadAction, createAsyncThunk, createSlice, isAnyOf } from '@reduxjs/toolkit';
import { ApiClient } from '@root/core/api';
import { RootState } from '@root/store';
import {
  GetAllRewardsQueryParams,
  GetRewardsQueryParams,
  Reward
} from '@trueloyal-engineering/ui-api-sdk';
import { EUDSettings } from '@root/core/config';
import { LabelHelpers } from '@root/core/helpers';
import { CommonThunkError, CommonState } from '../types';

export interface RewardState extends CommonState {
  rewards: Reward[] | undefined;
  eligibleRewards: Reward[] | undefined;
}

export const fetchAllRewards = createAsyncThunk<
  Reward[] | undefined,
  GetAllRewardsQueryParams,
  { rejectValue: CommonThunkError }
>('reward/fetchAllRewards', async (queryParams, { rejectWithValue }) => {
  try {
    const apiClient = ApiClient.getInstance();
    const input = {
      queryParams
    };
    const response = await apiClient.rewards.getRewards(input);
    if (!response.success) {
      return rejectWithValue({
        errorMessage: EUDSettings.getInstance().content_settings.reward_section_error_state_message
      });
    }
    return LabelHelpers.replaceVariables(response.data.rewards, 'reward') as Reward[];
  } catch (error) {
    return rejectWithValue({
      errorMessage: EUDSettings.getInstance().content_settings.reward_section_error_state_message
    });
  }
});

export const fetchEligibleRewards = createAsyncThunk<
  Reward[] | undefined,
  GetRewardsQueryParams,
  { rejectValue: CommonThunkError }
>('reward/fetchEligibleRewards', async (queryParams, { rejectWithValue }) => {
  try {
    const apiClient = ApiClient.getInstance();
    const input = {
      queryParams
    };
    const response = await apiClient.rewards.getEligibleRewards(input);
    if (!response.success) {
      return rejectWithValue({
        errorMessage: EUDSettings.getInstance().content_settings.reward_section_error_state_message
      });
    }
    return LabelHelpers.replaceVariables(response.data.rewards, 'reward') as Reward[];
  } catch (error) {
    return rejectWithValue({
      errorMessage: EUDSettings.getInstance().content_settings.reward_section_error_state_message
    });
  }
});

const initialState: RewardState = {
  rewards: undefined,
  eligibleRewards: undefined,
  status: 'idle',
  errorMessage: ''
};

export const rewardSlice = createSlice({
  name: 'reward',
  initialState,
  reducers: {
    setRewards: (state, action: PayloadAction<Reward[]>) => {
      state.rewards = action.payload;
    }
  },
  extraReducers: (builder) => {
    builder.addCase(fetchAllRewards.fulfilled, (state, action) => {
      state.status = 'succeeded';
      state.rewards = action.payload as Reward[];
    });
    builder.addCase(fetchEligibleRewards.fulfilled, (state, action) => {
      state.status = 'succeeded';
      state.eligibleRewards = action.payload as Reward[];
    });
    builder.addMatcher(
      isAnyOf(fetchAllRewards.pending, fetchEligibleRewards.pending),
      (state, _) => {
        state.status = 'pending';
      }
    );
    builder.addMatcher(
      isAnyOf(fetchAllRewards.rejected, fetchEligibleRewards.rejected),
      (state, action) => {
        state.status = 'failed';
        state.errorMessage = action.payload?.errorMessage ?? 'Unknown Error';
      }
    );
  }
});

// Action creators are generated for each case reducer function
export const { setRewards } = rewardSlice.actions;

export const selectRewards = (state: RootState, from: string | undefined) => {
  switch (from) {
    case 'guest':
      return state.reward.rewards;
    case 'member':
      return state.reward.eligibleRewards;
    default:
      return [];
  }
};

export const selectReward = (state: RootState, rewardId: string | undefined) => {
  if (!rewardId) return null;
  const filteredRewards = state.reward.eligibleRewards?.filter(
    (reward) => reward.reward_id === rewardId
  );
  if (filteredRewards) {
    return filteredRewards[0];
  }
  return null;
};
export default rewardSlice.reducer;
