import { ZinreloApi } from '@root/ZinreloApi'
import { Member, MemberResponse, PerformActivityInputData, UpdateMemberInputData } from './types'
import { CommonResponse, MethodArgsWithoutData, MethodArgsWithoutQueryParams } from '@root/types'
import { isEmpty } from '@root/utils'
import { ZinreloErrors } from '@root/constants'

export class MembersApi {
  private readonly apiClient: ZinreloApi

  constructor(apiClient: ZinreloApi) {
    this.apiClient = apiClient
  }

  private get url(): string {
    return `${this.apiClient.client.getApiUrl()}`
  }

  public async getMember(input?: MethodArgsWithoutData): Promise<MemberResponse> {
    const endpoint = `${this.url}/member`

    return this.apiClient.client.execute({
      method: 'get',
      url: endpoint,
      passToken: true,
      params: input?.queryParams,
    })
  }

  public async updateMember(input: MethodArgsWithoutQueryParams<UpdateMemberInputData>): Promise<Member> {
    const endpoint = `${this.url}/member`

    if (!input?.data || isEmpty(input.data)) {
      ZinreloErrors.throwErrorHelper(ZinreloErrors.INVALID_INPUT)
    }

    return this.apiClient.client.execute({
      method: 'post',
      url: endpoint,
      passToken: true,
      data: input?.data,
    })
  }

  public async performActivity(input: MethodArgsWithoutQueryParams<PerformActivityInputData>): Promise<CommonResponse> {
    const endpoint = `${this.url}/perform-activity`

    if (!input?.data || isEmpty(input.data)) {
      ZinreloErrors.throwErrorHelper(ZinreloErrors.INVALID_INPUT)
    }

    return this.apiClient.client.execute({
      method: 'post',
      url: endpoint,
      passToken: true,
      data: input?.data,
    })
  }
}
