import { ThemeHelpers } from '../../src/core/helpers/theme';
import { THEME_VARIABLE_DEFAULTS } from '../constants/themeDefaults';
import {
  DEFAULT_FONTS,
  MATERIAL_SYMBOLS_URL,
  DEFAULT_FONT_POPPINS,
  DEFAULT_FONT_INTER,
  LINK_ID_FONTS_GLOBAL,
  LINK_ID_FONTS_SHADOW,
  LINK_ID_FONTS,
  LINK_ID_MATERIAL_SYMBOLS_GLOBAL,
  LINK_ID_MATERIAL_SYMBOLS_SHADOW,
  LINK_ID_MATERIAL_SYMBOLS,
  CUSTOM_FONT_WEIGHTS
} from '../constants/fonts';
import { STYLE_ATTRIBUTES } from '../constants/styleConstants';
import {
  extractFontName,
  buildGoogleFontsUrl,
  createOrUpdateLink,
  getTargetRoot
} from './fontHelpers';

interface ThemeSettings {
  global_body_font_family?: string;
  global_header_font_family?: string;
  [key: string]: any;
}

export interface EudSettings {
  theme_settings?: ThemeSettings;
}

const collectFonts = (eudSettings?: EudSettings): string[] => {
  const fonts = [...DEFAULT_FONTS];

  const bodyFont = extractFontName(eudSettings?.theme_settings?.global_body_font_family);
  const headerFont = extractFontName(eudSettings?.theme_settings?.global_header_font_family);

  if (bodyFont && bodyFont !== DEFAULT_FONT_POPPINS && bodyFont !== DEFAULT_FONT_INTER) {
    fonts.push(`${bodyFont.replace(/\s+/g, '+')}:${CUSTOM_FONT_WEIGHTS}`);
  }

  if (
    headerFont &&
    headerFont !== bodyFont &&
    headerFont !== DEFAULT_FONT_POPPINS &&
    headerFont !== DEFAULT_FONT_INTER
  ) {
    fonts.push(`${headerFont.replace(/\s+/g, '+')}:${CUSTOM_FONT_WEIGHTS}`);
  }

  return fonts;
};

export const injectFonts = (
  eudSettings?: EudSettings,
  targetRoot?: ShadowRoot | Document,
  uniqueId?: string
) => {
  const fonts = collectFonts(eudSettings);
  const fontUrl = buildGoogleFontsUrl(fonts);
  const rootElement = getTargetRoot(targetRoot);
  const idSuffix = uniqueId ? `-${uniqueId}` : '';

  if (rootElement instanceof ShadowRoot) {
    createOrUpdateLink(fontUrl, `${LINK_ID_FONTS_GLOBAL}${idSuffix}`, document.head);
    createOrUpdateLink(fontUrl, `${LINK_ID_FONTS_SHADOW}${idSuffix}`, rootElement);
    createOrUpdateLink(
      MATERIAL_SYMBOLS_URL,
      `${LINK_ID_MATERIAL_SYMBOLS_GLOBAL}${idSuffix}`,
      document.head
    );
    createOrUpdateLink(
      MATERIAL_SYMBOLS_URL,
      `${LINK_ID_MATERIAL_SYMBOLS_SHADOW}${idSuffix}`,
      rootElement
    );
  } else {
    const targetHead = rootElement instanceof Document ? document.head : rootElement;
    createOrUpdateLink(fontUrl, `${LINK_ID_FONTS}${idSuffix}`, targetHead);
    createOrUpdateLink(MATERIAL_SYMBOLS_URL, `${LINK_ID_MATERIAL_SYMBOLS}${idSuffix}`, targetHead);
  }
};

export const applyThemeStyles = (eudSettings?: EudSettings, targetElement?: HTMLElement) => {
  if (!eudSettings?.theme_settings) {
    return;
  }

  const themeSettings = eudSettings.theme_settings;
  const cssVariables = ThemeHelpers.getCSSVariablesFromThemeSettings(themeSettings);

  // Find shadow root or document
  let shadowRoot: ShadowRoot | Document;
  if (targetElement) {
    const rootNode = targetElement.getRootNode();
    shadowRoot = rootNode instanceof ShadowRoot ? rootNode : document;
  } else {
    const dashboardRoot = document.querySelector(`[${STYLE_ATTRIBUTES.DASHBOARD_ROOT}]`);
    const rootNode = dashboardRoot?.getRootNode() as Document | ShadowRoot | null;
    shadowRoot = rootNode instanceof ShadowRoot ? rootNode : document;
  }

  // Auto-duplicate and fallback variables
  const VARIABLE_FALLBACKS: Record<string, string> = {
    '--zrl-text-primary-color': '--zrl-global-text-primary-color',
    '--zrl-primary-color': '--zrl-global-primary-color',
    '--zrl-secondary-color': '--zrl-global-secondary-color',
    '--zrl-banner-info-color-bg': '--zrl-global-secondary-color'
  };

  // Merge all variables
  const allVariables: Record<string, string> = { ...cssVariables };

  // Apply fallbacks
  Object.entries(VARIABLE_FALLBACKS).forEach(([targetVar, sourceVar]) => {
    const sourceValue = cssVariables[sourceVar];
    const targetValue = cssVariables[targetVar];
    if (sourceValue && !targetValue) {
      allVariables[targetVar] = sourceValue;
    }
  });

  // Apply defaults
  Object.entries(THEME_VARIABLE_DEFAULTS).forEach(([key, defaultValue]) => {
    const apiValue = allVariables[key];
    if (!apiValue || apiValue === '' || apiValue === 'null') {
      allVariables[key] = defaultValue;
    }
  });

  // Build CSS text
  const cssText = Object.entries(allVariables)
    .map(([key, value]) => `  ${key}: ${value};`)
    .join('\n');

  // Inject or update style tag
  const styleId = 'eud-theme-variables';
  let styleTag = shadowRoot.querySelector(`#${styleId}`) as HTMLStyleElement;

  if (!styleTag) {
    styleTag = document.createElement('style');
    styleTag.id = styleId;
    if (shadowRoot instanceof ShadowRoot) {
      shadowRoot.insertBefore(styleTag, shadowRoot.firstChild);
    } else {
      document.head.appendChild(styleTag);
    }
  }

  styleTag.textContent = `:host {\n${cssText}\n}`;
};
