import { ZinreloApiErrorType, ZinreloErrorType } from './types'

export class ZinreloErrors {
  static readonly PARTNER_ID_MISSING: ZinreloErrorType = {
    message: 'Partner ID is required.',
    type: 'PARTNER_ID_MISSING',
  }
  static readonly AUTH_TOKEN_MISSING: ZinreloErrorType = {
    message: "'Auth token' is required",
    type: 'AUTH_TOKEN_MISSING',
  }

  static readonly API_CLIENT_UNEXPECTED_ERROR_MESSAGE: ZinreloErrorType = {
    message: 'An unexpected error occurred while processing your request.',
    type: 'TRANSPORT_ERROR',
  }
  static readonly API_CLIENT_SERVER_UNEXPECTED_ERROR_MESSAGE: ZinreloErrorType = {
    message: 'An unexpected error occurred while processing your request.',
    type: 'SERVER_ERROR',
  }

  static readonly INVALID_INPUT: ZinreloErrorType = {
    message: 'Invalid input',
    type: 'INVALID_INPUT',
  }

  static readonly throwErrorHelper = (error: ZinreloErrorType) => {
    const e = Object.assign(new Error(), {
      cause: {
        error_code: error.type,
        reason: error.message,
        success: false,
      },
      ...this.API_CLIENT_SERVER_UNEXPECTED_ERROR_MESSAGE,
    })
    throw e
  }

  static readonly throwApiErrors = (apiError: ZinreloApiErrorType) => {
    this.throwErrorHelper({
      message: apiError.reason,
      type: apiError.error_code,
    })
  }
}
