import { Button, InputField, InputFieldProps } from '@trueloyal-engineering/react-ui';
import { ContentCopy as ContentCopyIcon } from '@root/icons';
import { forwardRef } from 'react';

export interface CopyToClipboardInputProps extends InputFieldProps {
  value?: string;
  onCopy?: () => void;
}

export const CopyToClipboardInput = forwardRef(
  (
    { value, onCopy = () => {}, ...props }: CopyToClipboardInputProps,
    ref: React.ForwardedRef<HTMLInputElement> | undefined
  ) => {
    const copyToClipboard = () => {
      if (value) {
        navigator.clipboard.writeText(value);
      }
      onCopy();
    };

    const copyButtonMarkup = (
      <Button
        id="copy-btn"
        icon={<ContentCopyIcon className="zrl-icon" fontSize="small" />}
        iconOnly
        onClick={copyToClipboard}
      />
    );

    return (
      <InputField value={value} readOnly connectedRight={copyButtonMarkup} {...props} ref={ref} />
    );
  }
);
