import { Condition, ComplexConditions } from '@root/store';
import { OPERATORS } from '../constants/operator.constants';

export class QueryBuilder {
  public static buildQueryForCondsArrayWithAndOp(conditions: Array<Condition>): ComplexConditions {
    return {
      operator: OPERATORS.AND,
      conditions: [
        {
          operator: OPERATORS.AND,
          conditions
        }
      ]
    };
  }

  public static buildQueryForOneCondWithAndOp(condition: Condition): ComplexConditions {
    return {
      operator: OPERATORS.AND,
      conditions: [
        {
          operator: OPERATORS.AND,
          conditions: [condition]
        }
      ]
    };
  }
}
