import StreaksFlame from '@root/containers/streaks/StreaksFlame/StreaksFlame';
import { Button, Card, Stack, Typography, classNames } from '@trueloyal-engineering/react-ui';
import { ChevronRight } from '@root/icons';
import { Streak } from '@root/store/slices/streakSlice';
import { StreakUserProgress } from '@root/store/slices/streakUserProgressSlice';
import { AuthConfig } from '@root/core/config';
import { StreakHelper } from '@root/core/helpers/streak';
import { ReactComponent as CelebrationStreakIcon } from '@root/assets/images/CelebrationStreakIcon.svg';
import { ReactComponent as SadStreakIcon } from '@root/assets/images/SadStreakIcon.svg';
import { ReactComponent as BrokenStreakIcon } from '@root/assets/images/BrokenStreakIcon.svg';
import { ReactComponent as CompletedStreakIcon } from '@root/assets/images/CompletedStreakIcon.svg';
import { ReactComponent as PauseIcon } from '@root/assets/images/Pause.svg';
import { ReactComponent as PausedStreakIcon } from '@root/assets/images/PausedStreakIcon.svg';
import { formatDateString } from '@root/core/utils/dateUtils';
import styles from './streak-card.module.css';

export interface StreakCardProps {
  streakUserProgress?: StreakUserProgress;
  streak: Streak;
  isGuest?: boolean;
  className?: string;
  onAction?: () => void;
}

export function StreakCard({
  streakUserProgress,
  streak,
  isGuest = true,
  onAction,
  className,
  ...cardProps
}: StreakCardProps) {
  const isPreview = AuthConfig.isPreview();
  let userProgress = streakUserProgress?.progress ?? 0;
  if (isPreview && !isGuest) {
    userProgress = 2;
  }
  const classes = classNames(!isGuest && styles['streak-card--clickable'], className);
  const { nameHeader, streakValidity, userProgressText, streakBrokenText, streakCompletionText } =
    StreakHelper.getStreakLabels(streak, userProgress);

  const isStreakPaused = streak?.status === 'manual_paused';

  return (
    <Card
      role="region"
      aria-label="Streak Information"
      className={classes}
      onClick={!isGuest ? onAction : undefined}
      data-streak_id={streak.id}
      {...cardProps}
    >
      <Stack gap={0}>
        <Stack gap={0.7} padding={0.7} align="start" orientation="horizontal">
          <div className={styles['streak-card__image-container']}>
            {isStreakPaused ? (
              <PausedStreakIcon className={styles['streak-details__image-container']} />
            ) : (
              <>
                {(!streakUserProgress || streakUserProgress?.progress_status === 'in_progress') && (
                  <StreaksFlame digit={userProgress} />
                )}
                {streakUserProgress?.progress_status === 'completed' && (
                  <CompletedStreakIcon className={styles['streak-details__image-container']} />
                )}
                {streakUserProgress?.progress_status === 'broken' && (
                  <BrokenStreakIcon className={styles['streak-details__image-container']} />
                )}
              </>
            )}
          </div>
          <Stack gap={0.2}>
            <Typography title={nameHeader} trunc={2}>
              {nameHeader}
            </Typography>
            <Typography
              muted
              title={streak.eud_message}
              trunc={2}
              fontWeight="thin"
              variant="bodySm"
            >
              {streak.eud_message}
            </Typography>
          </Stack>
        </Stack>

        {isStreakPaused || userProgress !== 0 ? (
          <Stack gap={0} padding={0.7} align="start" orientation="horizontal">
            {isStreakPaused ? (
              <div className={styles['streak-card__chip']}>
                <Stack gap={0.7} align="center" orientation="horizontal">
                  <div className={styles['streak-card__chip-image-container']}>
                    <PauseIcon width={18} height={18} />
                    <Typography muted fontWeight="thin" variant="bodySm">
                      {streak.eud_manual_paused_text}
                    </Typography>
                  </div>
                </Stack>
              </div>
            ) : (
              userProgress !== 0 && (
                <div className={styles['streak-card__chip']}>
                  <Stack gap={0.7} align="center" orientation="horizontal">
                    {(!streakUserProgress ||
                      streakUserProgress?.progress_status === 'in_progress') && (
                      <div className={styles['streak-card__chip-image-container']}>
                        <CelebrationStreakIcon />
                        <Typography muted fontWeight="thin" variant="bodySm">
                          {userProgressText}
                        </Typography>
                      </div>
                    )}
                    {streakUserProgress?.progress_status === 'completed' && (
                      <div className={styles['streak-card__chip-image-container']}>
                        <CelebrationStreakIcon />
                        <Typography muted fontWeight="thin" variant="bodySm">
                          {streakCompletionText}
                        </Typography>
                      </div>
                    )}
                    {streakUserProgress?.progress_status === 'broken' && (
                      <div className={styles['streak-card__chip-image-container']}>
                        <SadStreakIcon />
                        <Typography muted fontWeight="thin" variant="bodySm">
                          {streakBrokenText}
                        </Typography>
                      </div>
                    )}
                  </Stack>
                </div>
              )
            )}
          </Stack>
        ) : undefined}

        {!isGuest && (
          <Stack
            padding={0.7}
            align="center"
            justify="space-between"
            className={styles['streak-card__footer']}
            orientation="horizontal"
          >
            <Typography fontWeight="thin" variant="bodySm">
              {streak?.status !== 'scheduled' && streak?.status !== 'auto_paused'
                ? streakValidity
                : `Starts ${formatDateString(streak.start_at, 'MMM d, yyyy')}`}
            </Typography>
            <Typography fontWeight="thin" variant="bodySm">
              |
            </Typography>
            <Button
              link
              className={styles['streak-card__view-streak-details-btn']}
              id="view-streak-details-btn"
              btnSize="small"
              icon={<ChevronRight className="zrl-icon zrl-icon--flip-on-rtl" fontSize="small" />}
              iconAlignment="right"
              aria-label="Go to Streak Details"
            >
              {streak.eud_call_to_action}
            </Button>
          </Stack>
        )}
        {isGuest && (
          <Stack
            padding={0.7}
            align="center"
            justify="space-between"
            className={styles['streak-card__footer']}
            orientation="horizontal"
          >
            <Typography fontWeight="thin" variant="bodySm">
              {streak?.status !== 'scheduled' && streak?.status !== 'auto_paused'
                ? streakValidity
                : `Starts ${formatDateString(streak.start_at, 'MMM d, yyyy')}`}
            </Typography>
          </Stack>
        )}
      </Stack>
    </Card>
  );
}
