import { Button, Carousel, CarouselProps, Typography } from '@trueloyal-engineering/react-ui';
import { AuthConfig, EUDSettings } from '@root/core/config';
import { StreakHelper } from '@root/core/helpers/streak';
import { SkeletonCarouselSlides } from '@root/components';
import { useAppSelector } from '@root/store';
import { StreakCard } from '@root/core/presets';
import { useAppNavigation } from '@root/hooks';
import styles from './streak-carousel.module.css';

export interface StreakCarouselProps extends CarouselProps {
  isGuest: boolean;
}

export function StreakCarousel({ isGuest, ...carouselProps }: StreakCarouselProps) {
  const streaks = useAppSelector((state) => state.streak.streaks);
  const status = useAppSelector((state) => state.streak.status);
  const isPreview = AuthConfig.isPreview();

  const streakUserProgress = useAppSelector((state) => state.streakUserProgress.streakUserProgress);
  const streakUserProgressStatus = useAppSelector((state) => state.streakUserProgress.status);

  const {
    streak_section_pagination_label: carouselViewAllButtonText,
    streak_section_loggedin_empty_state_message: noLoggedInMessage,
    streak_section_guest_empty_state_message: noGuestMessage,
    streak_section_header_text: header
  } = EUDSettings.getInstance().content_settings;

  const noStreaksMessage = isGuest ? noGuestMessage : noLoggedInMessage;

  const loading = ['pending', 'idle'].includes(status);

  const loadingStreakUserProgress =
    isGuest || isPreview || (!loading && (!streaks || streaks.length === 0))
      ? false
      : ['pending', 'idle'].includes(streakUserProgressStatus);
  const { gotoMemberStreakDetails, gotoGuestStreakDetails, gotoMemberStreaks, gotoGuestStreaks } =
    useAppNavigation();
  const gotoStreaksList = isGuest ? gotoGuestStreaks : gotoMemberStreaks;
  const gotoStreak = isGuest ? gotoGuestStreakDetails : gotoMemberStreakDetails;

  return (
    <Carousel className="streak-carousel" aria-label={`${'header'} Carousel`} {...carouselProps}>
      <Carousel.Header>
        <Typography variant="headerXl" fontWeight="bold" titled trunc={1} title={header}>
          {header}
        </Typography>
      </Carousel.Header>
      {(loading || loadingStreakUserProgress) && <SkeletonCarouselSlides />}
      {!loading && !loadingStreakUserProgress && streaks && streaks?.length > 0 && (
        <>
          <Carousel.Slides>
            {streaks.map((streak) => {
              return (
                <StreakCard
                  key={streak.id}
                  streakUserProgress={StreakHelper.currentRun(streakUserProgress?.[streak.id])}
                  streak={streak}
                  isGuest={isGuest}
                  className={styles['streak-carousel__streak-card']}
                  onAction={() => gotoStreak(streak.id)}
                />
              );
            })}
          </Carousel.Slides>
          <Carousel.Footer>
            <Button
              relaxed
              fullWidthOnDeviceType="sm"
              onClick={gotoStreaksList}
              id="view-streaks-btn"
            >
              {`${carouselViewAllButtonText} (${streaks.length})`}
            </Button>
          </Carousel.Footer>
        </>
      )}
      {!loading && (!streaks || !streaks.length) && (
        <Typography muted align="center">
          {noStreaksMessage}
        </Typography>
      )}
    </Carousel>
  );
}
