import { CalendarDateInput } from '@root/components/StyledCalendar/types';
import { formatCalenderDates, getDaysInMonth } from '@root/core/utils/dateUtils';
import { useAppDispatch, useAppSelector } from '@root/store';
import { updateMember } from '@root/store/slices/memberSlice';
import { Member, Activity } from '@trueloyal-engineering/ui-api-sdk';
import { useState } from 'react';
import { toast } from 'react-toastify';

export interface UseDateActivityProps {
  dateFormat: string;
  eligibleFieldKey: keyof Pick<Member, 'anniversary_date' | 'birthdate'>;
  activity: Activity;
}

export function useDateActivity({ dateFormat, eligibleFieldKey, activity }: UseDateActivityProps) {
  const dispatch = useAppDispatch();
  const memberDateField = useAppSelector((state) => state.member.memberDetails?.[eligibleFieldKey]);
  const status = useAppSelector((state) => state.member.status);
  const isYearRequired = activity.extra_config?.is_year_required;

  const [date, setDate] = useState<CalendarDateInput>(
    memberDateField ? new Date(memberDateField) : null
  );

  const [month, setMonth] = useState<number | undefined>(
    date instanceof Date ? date.getMonth() + 1 : undefined
  );

  const [day, setDay] = useState<number | undefined>(
    date instanceof Date ? date.getDate() : undefined
  );

  const addDate = () => {
    let newDate = date;
    if (!isYearRequired) {
      if (!month || !day) {
        toast.error('Invalid Date Provided');
        return;
      }
      try {
        // When year is not required we will have to store 1904 as the year on the backend
        // Ideally the api should automatically store 1904 but that's not the case currently
        newDate = new Date(1904, month - 1, day);
      } catch (error) {
        toast.error('Invalid Date Provided');
        return;
      }
    }
    dispatch(
      updateMember({
        updateParams: { [eligibleFieldKey]: formatCalenderDates(newDate, dateFormat) }
      })
    );
  };

  const onMonthChange = (value: number | string) => {
    const monthValue = typeof value === 'number' ? value : parseInt(value, 10);
    setMonth(monthValue);
    setDay(undefined);
  };

  const onDayChange = (value: number | string) => {
    const dayValue = typeof value === 'number' ? value : parseInt(value, 10);
    setDay(dayValue);
  };

  const getDaysOptions = () => {
    if (!month) return [];
    const daysInMonth = getDaysInMonth(month - 1, 1904);
    return Array.from(Array(daysInMonth).keys()).map((currDay) => {
      return {
        label: (currDay + 1).toString(),
        value: currDay + 1
      };
    });
  };

  return {
    isActivityCompleted: Boolean(memberDateField),
    date,
    setDate,
    addDate,
    loading: status === 'pending',
    month,
    day,
    onMonthChange,
    onDayChange,
    getDaysOptions
  };
}
