import { ActivitiesApi } from './activities'
import { ApiClient, ApiClientType } from './apiClient'
import { MembersApi } from './members'
import { RewardsApi } from './rewards'
import { TiersApi } from './tiers'
import { TransactionsApi } from './transactions'
import { HelperUtils } from './utils/HelperUtils'

export class ZinreloApi {
  private readonly _client: ApiClient
  private _activities?: ActivitiesApi
  private _rewards?: RewardsApi
  private _members?: MembersApi
  private _tiers?: TiersApi
  private _transactions?: TransactionsApi

  constructor(config: ApiClientType) {
    this._client = new ApiClient(config)
  }

  public get client() {
    return this._client
  }

  public get activities() {
    if (!this._activities) {
      this._activities = new ActivitiesApi(this)
    }
    return this._activities
  }

  public get tiers() {
    if (!this._tiers) {
      this._tiers = new TiersApi(this)
    }
    return this._tiers
  }

  public get rewards() {
    if (!this._rewards) {
      this._rewards = new RewardsApi(this)
    }
    return this._rewards
  }

  public get members() {
    if (!this._members) {
      this._members = new MembersApi(this)
    }
    return this._members
  }

  public get transactions() {
    if (!this._transactions) {
      this._transactions = new TransactionsApi(this)
    }
    return this._transactions
  }

  public get utils() {
    return HelperUtils
  }
}
