import React, { useState } from 'react';
import { Stack, Typography } from '@trueloyal-engineering/react-ui';
import { ReactComponent as BrokenStreakIcon } from '@root/assets/images/BrokenStreakIcon.svg';
import { ReactComponent as CompletedStreakIcon } from '@root/assets/images/CompletedStreakIcon.svg';
import { StreakUserProgress } from '@root/store/slices/streakUserProgressSlice';
import { PerkLog } from '@root/store/slices/perkLogSlice';
import { Perk } from '@root/store/slices/streakPerkSlice';
import { PerkList } from '@root/containers/perk/PerkList';
import { Divider } from '@root/components/Divider';
import { ChevronDown, ChevronUp } from '@root/icons';
import { StreakHelper } from '@root/core/helpers/streak';
import { formatDateString } from '@root/core/utils/dateUtils';
import styles from './streak-details.module.css';

export interface StreakPreviousRunsProps {
  streakId: string;
  runs: StreakUserProgress[];
  streakPerks: Perk[];
  allPerkLogs: Record<string, PerkLog[]> | undefined;
  isGuest: boolean;
}

export function StreakPreviousRuns({
  streakId,
  runs,
  streakPerks,
  allPerkLogs,
  isGuest
}: StreakPreviousRunsProps) {
  const [isExpanded, setIsExpanded] = useState(false);
  const previousRuns = runs.slice(1);

  if (previousRuns.length === 0) return null;

  const earnedPerksFor = (run: StreakUserProgress): Perk[] =>
    streakPerks.flatMap((perk) =>
      StreakHelper.perkLogsForRun(allPerkLogs?.[perk.id], runs, run).map((perkLog) => ({
        ...perk,
        reward_log_id: perkLog.id,
        reward_log_status: perkLog.reward_log_status,
        coupon_code: perkLog.coupon_code,
        linked_schema_record_id: perkLog.linked_schema_record_id,
        linked_schema_slug: perkLog.linked_schema_slug
      }))
    );

  return (
    <div className={styles['streak-details__previous-runs']}>
      <Stack gap={0.6} padding={0.7} align="start" orientation="vertical">
        <Divider />
      </Stack>
      <button
        type="button"
        className={styles['streak-details__previous-runs-toggle']}
        aria-expanded={isExpanded}
        onClick={() => setIsExpanded((expanded) => !expanded)}
      >
        <Typography fontWeight="bold" variant="bodyMd">
          {`Previous streaks (${previousRuns.length})`}
        </Typography>
        {isExpanded ? (
          <ChevronUp aria-hidden width={24} height={24} />
        ) : (
          <ChevronDown aria-hidden width={24} height={24} />
        )}
      </button>

      {isExpanded &&
        previousRuns.map((run) => {
          const { endedAt } = StreakHelper.runWindow(runs, run);
          const earnedPerks = earnedPerksFor(run);
          return (
            <div
              key={run.id}
              className={styles['streak-details__previous-run']}
              data-run_id={run.id}
            >
              <Stack gap={0.7} padding={0.7} align="center" orientation="horizontal">
                <div className={styles['streak-details__chip-image-container']}>
                  {run.progress_status === 'completed' ? (
                    <CompletedStreakIcon width={24} height={24} />
                  ) : (
                    <BrokenStreakIcon width={24} height={24} />
                  )}
                </div>
                <Stack gap={0.2} align="start" orientation="vertical">
                  <Typography variant="bodySm" fontWeight="bold">
                    {run.progress_status === 'completed' ? 'Completed' : 'Broken'}
                  </Typography>
                  <Typography variant="bodySm" muted fontWeight="thin">
                    {`${formatDateString(run.created_at, 'MMM d, yyyy')} – ${
                      endedAt
                        ? formatDateString(new Date(endedAt).toISOString(), 'MMM d, yyyy')
                        : ''
                    } · reached ${run.progress}`}
                  </Typography>
                </Stack>
              </Stack>
              {earnedPerks.length > 0 ? (
                <PerkList isGuest={isGuest} linkedSchemaRecordId={streakId} perks={earnedPerks} />
              ) : (
                <Stack gap={0.6} padding={0.7} align="start" orientation="vertical">
                  <Typography variant="bodySm" muted fontWeight="thin">
                    No rewards earned in this streak
                  </Typography>
                </Stack>
              )}
            </div>
          );
        })}
    </div>
  );
}
