import { Button, Carousel, CarouselProps, Typography } from '@trueloyal-engineering/react-ui';
import { EUDSettings } from '@root/core/config';
import { SkeletonCarouselSlides } from '@root/components';
import { useAppSelector } from '@root/store';
import { selectActivities } from '@root/store/slices/activitySlice';
import { useAppNavigation } from '@root/hooks';
import { ActivityCard } from '@root/core/presets';
import { replaceLabels } from '@root/core/utils/textUtils';
import styles from './activity-carousel.module.css';

export interface ActivityCarouselProps extends CarouselProps {
  isGuest: boolean;
}

export function ActivityCarousel({ isGuest, ...carouselProps }: ActivityCarouselProps) {
  const requestActivitiesFor = isGuest ? 'guest' : 'member';

  const activities = useAppSelector((state) => selectActivities(state, requestActivitiesFor));
  const status = useAppSelector((state) => state.activity.status);

  const { gotoGuestActivities, gotoMemberActivities, gotoMemberActivity } = useAppNavigation();
  const gotoActivityList = isGuest ? gotoGuestActivities : gotoMemberActivities;

  const {
    activity_section_loggedin_empty_state_message: noActivitiesLoggedInMessage,
    activity_section_guest_empty_state_message: noActivitiesGuestMessage,
    activity_section_header_text: activityHeaderText,
    activity_section_pagination_label: carouselViewAllButtonText,
    program_details_currency_plural_text: currencyPlural
  } = EUDSettings.getInstance().content_settings;

  const noActivitiesMessage = isGuest ? noActivitiesGuestMessage : noActivitiesLoggedInMessage;

  const loading = ['pending', 'idle'].includes(status);
  const activityHeader = replaceLabels(activityHeaderText, {
    '{{POINTS_LABEL}}': currencyPlural
  });

  return (
    <Carousel
      className="activity-carousel"
      aria-label={`${activityHeader} Carousel`}
      {...carouselProps}
    >
      <Carousel.Header>
        <Typography variant="headerXl" fontWeight="bold" titled trunc={1} title={activityHeader}>
          {activityHeader}
        </Typography>
      </Carousel.Header>
      {loading && <SkeletonCarouselSlides />}
      {!loading && (!activities || !activities.length) && (
        <Typography muted align="center">
          {noActivitiesMessage}
        </Typography>
      )}
      {!loading && activities && activities?.length > 0 && (
        <>
          <Carousel.Slides>
            {activities.map((activity) => {
              return (
                <ActivityCard
                  key={activity.activity_id}
                  activity={activity}
                  className={styles['activity-carousel__activity-card']}
                  readOnly={isGuest}
                  onAction={() => gotoMemberActivity(activity.activity_id)}
                />
              );
            })}
          </Carousel.Slides>
          <Carousel.Footer>
            <Button
              relaxed
              fullWidthOnDeviceType="sm"
              onClick={gotoActivityList}
              id="view-activities-btn"
            >
              {`${carouselViewAllButtonText} (${activities.length})`}
            </Button>
          </Carousel.Footer>
        </>
      )}
    </Carousel>
  );
}
