import { Stack, Typography } from '@trueloyal-engineering/react-ui';
import { TierCarousel } from '@root/containers/tier';
import { useAppSelector } from '@root/store';
import { EUDSettings } from '@root/core/config';
import { MemberTierInfo, MemberTierUpgradeActivities } from '@root/containers';

export function MemberTierBenefits() {
  const {
    tier_benefits_page_carousal_header: carouselHeader,
    tier_benefits_page_header: headerText
  } = EUDSettings.getInstance().content_settings;

  const { memberDetails: member, nextTier } = useAppSelector((state) => state.member);
  if (!member) {
    return null;
  }
  const { eligibleActivities } = useAppSelector((state) => state.activity);
  const tierUpgradeActivities = eligibleActivities?.filter(
    (activity) => activity.is_qualified_for_tier_upgrade
  );

  const {
    tier_info: { loyalty_tier_id: tierId, loyalty_tier_name: tierName }
  } = member;

  const header = headerText.replace('{{CURRENT_TIER_NAME}}', tierName);
  const memberTierBenefitHeaderMarkup = (
    <Typography variant="headerLg" muted uppercase>
      {carouselHeader}
    </Typography>
  );

  return (
    <Stack gap={2} className="member-tier-benefits">
      <Stack gap={0.2}>
        <Typography variant="headerXl" fontWeight="bold">
          {header}
        </Typography>
        <MemberTierInfo
          memberCurrentTierInfo={member.tier_info}
          nextTier={nextTier}
          showViewBenefits={false}
        />
      </Stack>
      {tierUpgradeActivities && tierUpgradeActivities.length > 0 && (
        <MemberTierUpgradeActivities activityList={tierUpgradeActivities} />
      )}
      <TierCarousel customHeader={memberTierBenefitHeaderMarkup} highlightedTierId={tierId} />
    </Stack>
  );
}
