import { useAppSelector } from '@root/store';
import { Navigate, useParams } from 'react-router-dom';
import { Button, Page } from '@trueloyal-engineering/react-ui';
import { selectReward } from '@root/store/slices/rewardSlice';
import { EUDSettings } from '@root/core/config';
import { RewardDetails } from '@root/containers';
import { useAppNavigation, usePage } from '@root/hooks';
import { UIHelpers } from '@root/core/helpers/ui';
import { MEMBER_BASE_PATH, REWARDS_BASE_PATH } from '@root/router/paths';

export function DefaultRewardDetailsPage() {
  const { back } = useAppNavigation();
  const { id } = useParams();
  const {
    embed_page_url_patterns: embedURLPatterns,
    content_settings: {
      navigation_home_text: navigationHomeText,
      navigation_back_text: navigationBackText
    }
  } = EUDSettings.getInstance();
  const reward = useAppSelector((state) => selectReward(state, id));
  const { getBreadcrumbs } = usePage();
  // TODO : Should Have a separate resource not found page
  if (!reward) {
    return <Navigate to={`${MEMBER_BASE_PATH}/${REWARDS_BASE_PATH}`} replace />;
  }

  const rewardName = UIHelpers.convertHtmlEntityToCharacter(reward?.reward_name ?? 'Reward');
  const showAppBar = embedURLPatterns.length < 1;
  const breadcrumbs = [
    ...getBreadcrumbs(),
    <Button mono disabled>
      {rewardName}
    </Button>
  ];
  return (
    <Page showAppBar={showAppBar} className="reward-details-page">
      <Page.Header
        title={rewardName}
        prevPageTitle={navigationHomeText}
        onBack={back}
        breadcrumbs={breadcrumbs}
        backBtnLabel={navigationBackText}
      />
      <Page.Body>
        <RewardDetails reward={reward} />
      </Page.Body>
    </Page>
  );
}
