import { ZinreloApi } from '@root/ZinreloApi'
import { TiersDataResponse } from './types'
import { MethodArgsWithoutData } from '@root/types'

export class TiersApi {
  private readonly apiClient: ZinreloApi

  constructor(apiClient: ZinreloApi) {
    this.apiClient = apiClient
  }

  private get url(): string {
    return `${this.apiClient.client.getApiUrl()}`
  }

  public async getTiers(input?: MethodArgsWithoutData): Promise<TiersDataResponse> {
    const endpoint = `${this.url}/tiers`

    return this.apiClient.client.execute({
      method: 'get',
      url: endpoint,
      params: input?.queryParams,
    })
  }
}
