import { Button, Card, CardProps, classNames } from '@trueloyal-engineering/react-ui';
import { Cancel as CancelIcon } from '@root/icons';
import React from 'react';
import styles from './image-preview.module.css';

export interface ImagePreviewProps extends CardProps {
  children?: React.ReactNode;
  className?: string;
  onRemove: () => void;
}

export function ImagePreview({ children, className, onRemove, ...props }: ImagePreviewProps) {
  const classes = classNames(styles['image-preview'], className);
  return (
    <Card className={classes} {...props}>
      <Card.Section className={styles['image-preview__content']}>{children}</Card.Section>
      <Button
        id="remove-image-btn"
        icon={<CancelIcon className="zrl-icon" />}
        iconOnly
        onClick={onRemove}
        className={styles['image-preview__remove']}
      />
    </Card>
  );
}
