import { Button, Image, Stack, Tag, Typography } from '@trueloyal-engineering/react-ui';
import { Reward, RewardTransaction } from '@trueloyal-engineering/ui-api-sdk';
import { RewardHelper } from '@root/core/helpers/reward';
import { useState } from 'react';
import { LoadMask } from '@root/components';
import { toast } from 'react-toastify';
import { ErrorHandler } from '@root/core/helpers/error';
import { AuthConfig, MerchantConfig } from '@root/core/config';
import { replaceLabels } from '@root/core/utils/textUtils';
import { fetchMember } from '@root/store/slices/memberSlice';
import { useAppDispatch, useAppSelector } from '@root/store';
import { calculateRemainingPointsPercentage } from '@root/core/utils/getPercentageForProgressbarUtils';
import { sanitizeHTML } from '@root/core/utils/htmlUtils';
import {
  DEFAULT_IMAGE_URL,
  LOYALTY_REDEMPTION_FLEXIBLE_POINTS_REWARD
} from '@root/core/constants/reward.constants';
import styles from './reward-details.module.css';
import { RewardSuccess } from '../RewardSuccess';
import { TintRewardForm } from '../FormBuilder/TintRewardForm';

export function RewardDetails({ reward }: { reward: Reward }) {
  const [redeemResponse, setRedeemResponse] = useState<RewardTransaction | undefined>();
  const [loading, setLoading] = useState(false);
  const [showTintForm, setShowTintForm] = useState(false);
  const dispatch = useAppDispatch();
  const { enableFormBuilderPoweredRewards, tintTeamId } = MerchantConfig.getInstance();

  const availablePoints =
    useAppSelector((state) => state.member.memberDetails?.available_points) ?? 0;

  const shouldShowTintForm =
    enableFormBuilderPoweredRewards && Boolean(tintTeamId && reward.tint_form_id);

  const handleRedeem = async () => {
    try {
      setLoading(true);
      if (shouldShowTintForm) {
        setShowTintForm(true);
      } else {
        const response = await RewardHelper.redeem(reward.reward_id);
        if (response.success) {
          dispatch(fetchMember());
          setRedeemResponse(response.data);
        }
      }
    } catch (error) {
      toast.error(ErrorHandler.resolveErrorMessage(error));
    } finally {
      setLoading(false);
    }
  };

  if (showTintForm) {
    return <TintRewardForm reward={reward} />;
  }

  if (redeemResponse) {
    // Show congratulation screen for after reward success
    return <RewardSuccess rewardTransaction={redeemResponse} reward={reward} />;
  }
  const isPreview = AuthConfig.isPreview();

  const {
    reward_card_background_image_url: imageURL,
    enduser_reward_short_description: shortDescription,
    points_to_be_redeemed: points,
    reward_name: name,
    extra_parameters: extraParameters,
    enable_auto_redemption: enableAutoRedemption
  } = reward;

  const hasEnoughPointsAvailable = availablePoints >= points;

  const remainingPointsPercentage = calculateRemainingPointsPercentage(availablePoints, points);

  const confirmButtonText = extraParameters?.redemption_confirm_button_text;
  const pointsToUnlockReward = points - availablePoints;
  const ineligibleRewardProgressText = replaceLabels(
    extraParameters?.ineligible_rewards_progress_text,
    { '{{POINTS_TO_UNLOCK_REWARD}}': pointsToUnlockReward }
  );

  const isFlexiblePointsReward =
    reward.reward_sub_type === LOYALTY_REDEMPTION_FLEXIBLE_POINTS_REWARD;
  const showConfirmButton =
    !enableAutoRedemption && hasEnoughPointsAvailable && !isFlexiblePointsReward;

  const tagLabelText = RewardHelper.getTagLabelText(reward, points);

  const imageSrc = imageURL || DEFAULT_IMAGE_URL;
  return (
    <div className={styles['reward-details']} data-redemption_id={reward.reward_id}>
      {loading && <LoadMask />}
      <Image className={styles['reward-details__image']} src={imageSrc} fit="contain" />
      <main>
        <section>
          <Stack gap={0.6}>
            <Tag
              primary
              label={tagLabelText}
              className={styles['reward-details__points-tag']}
              progress={remainingPointsPercentage}
            />
            <Typography
              trunc={2}
              title={name}
              variant="header2xl"
              fontWeight="bold"
              dangerouslySetInnerHTML={{ __html: sanitizeHTML(name) }}
            />

            {hasEnoughPointsAvailable ? (
              <Typography
                fontWeight="thin"
                dangerouslySetInnerHTML={{ __html: sanitizeHTML(shortDescription) }}
                muted
              />
            ) : (
              <Typography
                fontWeight="thin"
                muted
                dangerouslySetInnerHTML={{ __html: sanitizeHTML(ineligibleRewardProgressText) }}
              />
            )}
          </Stack>
        </section>
        {showConfirmButton && (
          <section className={styles['reward-details__footer']}>
            <Button
              id="reward-confirm-btn"
              fullWidthOnDeviceType="sm"
              primary
              onClick={!isPreview ? handleRedeem : undefined}
              btnSize="large"
            >
              {confirmButtonText}
            </Button>
          </section>
        )}
      </main>
    </div>
  );
}
