import { Replaceable } from '@root/core/types';
import { MerchantConfig } from '../config';

export function pluralize(value: number | undefined, singular: string, plural: string) {
  return (value ?? 0) > 1 ? plural : singular;
}

export function replaceLabels<T>(text: T, replaceable: Replaceable): T {
  if (!text || typeof text !== 'string') return text;
  let replacedText: string = text;
  Object.entries(replaceable).forEach(([key, value]) => {
    replacedText = replacedText.replaceAll(key, value as string);
  });

  return replacedText as T;
}

export function validateEmail(email: string): boolean {
  return Boolean(
    email.match(
      // eslint-disable-next-line no-useless-escape
      /^(([^<>()[\]\\.,;:\s@\"]+(\.[^<>()[\]\\.,;:\s@\"]+)*)|(\".+\"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/
    )
  );
}

export function validateEmailList(emails: string[]): boolean {
  // Split the input email list by commas
  return emails.every((email) => validateEmail(email));
}

export function formatEmails(emailList: string): string[] {
  return emailList.split(',').map((email) => email.trim());
}

export function formatNumber(number: number | undefined, locale?: string, options?: any) {
  if (!number) return number;
  if (!options) {
    // eslint-disable-next-line no-param-reassign
    options = { maximumFractionDigits: MerchantConfig.getInstance().decimalPlacesCount };
  }
  // if locale is not specified explicitly browsers locale will be picked
  return number.toLocaleString(locale, options);
}
