import { Carousel, CarouselProps, Typography } from '@trueloyal-engineering/react-ui';
import { EUDSettings, AuthConfig } from '@root/core/config';
import { TierCard } from '@root/core/presets';
import { useAppSelector } from '@root/store';
import React, { useRef } from 'react';
import styles from './tier-carousel.module.css';

export interface TierCarouselProps extends CarouselProps {
  highlightedTierId?: string;
  customHeader?: React.ReactNode;
}

export function TierCarousel({
  highlightedTierId,
  customHeader,
  ...carouselProps
}: TierCarouselProps) {
  const tiers = useAppSelector((state) => state.tier.tiers);
  const highlightedTierRef = useRef<HTMLDivElement>(null);

  if (!tiers) {
    return null;
  }

  const { tier_section_header: header } = EUDSettings.getInstance().content_settings;

  if (!tiers || tiers.length < 1) {
    return null;
  }
  const isPreview = AuthConfig.isPreview();

  return (
    <Carousel
      className={styles['tier-carousel']}
      title={header}
      aria-label={`${header} Carousel`}
      {...carouselProps}
    >
      <Carousel.Header>
        {customHeader || (
          <Typography variant="headerXl" fontWeight="bold" titled trunc={1}>
            {header}
          </Typography>
        )}
      </Carousel.Header>
      {tiers && (
        <Carousel.Slides highlightedRef={highlightedTierRef}>
          {tiers.map((tier, index) => {
            const nextTier = tiers?.[index + 1];
            const nextTierPoints = nextTier?.minimum_points;
            const isHighlightedTier = tier.tier_id === highlightedTierId;
            return (
              <TierCard
                key={tier.tier_id}
                tier={tier}
                className={styles['tier-carousel__tier-card']}
                highlighted={!isPreview && isHighlightedTier}
                nextTierPoints={nextTierPoints}
                ref={isHighlightedTier ? highlightedTierRef : null}
              />
            );
          })}
        </Carousel.Slides>
      )}
    </Carousel>
  );
}
