import { STYLE_ATTRIBUTES } from '../constants/styleConstants';
import { injectStylesIntoShadowRoot } from './shadowDomStyles';

export const convertMediaToContainer = (root: ShadowRoot | Document) => {
  const styleSheets = Array.from(root.querySelectorAll('style'));

  styleSheets.forEach((styleTag) => {
    // eslint-disable-next-line no-param-reassign
    let cssText = styleTag.textContent || '';

    // 1. Handle comma-separated lists with print
    // For now, just strip "print, " and convert the width part
    // @media print, (max-width: X) → @container (max-width: X)
    cssText = cssText.replace(
      /@media\s+print\s*,\s*(?=\((?:min-width|max-width))/gi,
      '@container '
    );

    // 2. Convert range syntax: (width < 768px) → (max-width: 767px)
    cssText = cssText.replace(
      /@media\s+\(width\s*<\s*(\d+(?:\.\d+)?)(px|em|rem)\)/g,
      (match, value, unit) => {
        const numValue = parseFloat(value);
        return `@media (max-width: ${numValue - 1}${unit})`;
      }
    );
    cssText = cssText.replace(
      /@media\s+\(width\s*>=\s*(\d+(?:\.\d+)?)(px|em|rem)\)/g,
      (match, value, unit) => {
        return `@media (min-width: ${value}${unit})`;
      }
    );

    // 3. Strip "screen and", "only screen and" to normalize
    cssText = cssText.replace(/@media\s+only\s+screen\s+and\s+/gi, '@media ');
    cssText = cssText.replace(/@media\s+screen\s+and\s+/gi, '@media ');

    // 4. Handle "not all and (min-width: X)" → (max-width: X-1)
    cssText = cssText.replace(
      /@media\s+not\s+all\s+and\s+\(min-width:\s*(\d+(?:\.\d+)?)(px|em|rem)\)/gi,
      (match, value, unit) => {
        const numValue = parseFloat(value);
        return `@media (max-width: ${numValue - 1}${unit})`;
      }
    );
    cssText = cssText.replace(
      /@media\s+not\s+all\s+and\s+\(max-width:\s*(\d+(?:\.\d+)?)(px|em|rem)\)/gi,
      (match, value, unit) => {
        const numValue = parseFloat(value);
        return `@media (min-width: ${numValue + 1}${unit})`;
      }
    );

    // 5. Convert width-based @media to @container
    // Single: @media (max-width: X)
    // Comma-separated: @media (max-width: X), (min-width: Y)
    // Inside @supports: works because we just replace @media
    cssText = cssText.replace(/@media\s+(?=\((?:min-width|max-width))/gi, '@container ');

    if (cssText !== styleTag.textContent) {
      // eslint-disable-next-line no-param-reassign
      styleTag.textContent = cssText;
    }
  });
};

export const getMountContainer = (
  element: HTMLElement | ShadowRoot,
  indexCssString: string,
  customCss?: string
): HTMLElement => {
  const isShadowRoot = element instanceof ShadowRoot;

  if (isShadowRoot) {
    injectStylesIntoShadowRoot(element as ShadowRoot, indexCssString, customCss);
  }

  let container = element.querySelector(`[${STYLE_ATTRIBUTES.DASHBOARD_ROOT}]`) as HTMLElement;

  if (!container) {
    container = document.createElement('div');
    container.setAttribute(STYLE_ATTRIBUTES.DASHBOARD_ROOT, 'true');
    container.id = 'zrl-frame-root';

    container.style.backgroundColor = 'var(--zrl-global-color-bg)';
    container.style.color = 'var(--zrl-text-primary-color)';
    container.style.fontSize = '14px';
    container.style.height = '100%';
    container.style.margin = '0';
    container.style.padding = '0';
    container.style.width = '100%';

    element.appendChild(container);
  }

  return container;
};

const VIEWPORT_WIDTH_UNIT = /(?<=[\s:(,])(-?\d*\.?\d+)vw(?=[\s;),!}])/g;

export const convertViewportWidthToContainer = (shadowRoot: ShadowRoot) => {
  shadowRoot.querySelectorAll('style').forEach((styleTag) => {
    const cssText = styleTag.textContent || '';
    const converted = cssText.replace(VIEWPORT_WIDTH_UNIT, '$1cqw');
    if (converted !== cssText) {
      // eslint-disable-next-line no-param-reassign
      styleTag.textContent = converted;
    }
  });
};
