import { Stack, Image, Typography, Button, Layout } from '@trueloyal-engineering/react-ui';
import { EUDSettings } from '@root/core/config';
import { useAppDispatch, useAppSelector } from '@root/store';
import { useAppNavigation } from '@root/hooks';
import { MEMBER_STATUS_ACTIVE } from '@root/core/constants/member.constants';
import { UpdateMemberInputData } from '@trueloyal-engineering/ui-api-sdk';
import { updateMember } from '@root/store/slices/memberSlice';
import { LoadMask } from '@root/components';
import { replaceLabels } from '@root/core/utils/textUtils';
import styles from './member-optin.module.css';

export function MemberOptIn() {
  const dispatch = useAppDispatch();
  const status = useAppSelector((state) => state.member.status);

  const { reloadPage } = useAppNavigation();

  const handleOptIn = () => {
    const updateParams: UpdateMemberInputData = {
      member_status: MEMBER_STATUS_ACTIVE
    };
    dispatch(updateMember({ updateParams })).then((response) => {
      if (response.meta.requestStatus === 'fulfilled') {
        reloadPage();
      }
    });
  };

  const {
    content_settings: {
      membership_opt_in_page_header: headerText,
      membership_opt_in_page_description: descriptionText,
      membership_opt_in_page_confirm_button_label: confirmButtonLabel,
      program_details_program_name: programName,
      program_details_currency_plural_text: currencyPlural
    },
    membership_opt_in_page_image_url: imageURL
  } = EUDSettings.getInstance();

  const loading = status === 'pending';

  const header = replaceLabels(headerText, { '{{PROGRAM_NAME}}': programName });
  const description = replaceLabels(descriptionText, { '{{POINTS_LABEL}}': currencyPlural });

  return (
    <Layout className="member-optin">
      {loading && <LoadMask />}
      <Layout.Content>
        <Stack align="center" justify="center">
          <Image className={styles['member-optin__image']} src={imageURL} />
          <Stack align="center">
            <Typography variant="header2xl" fontWeight="bold">
              {header}
            </Typography>
            <Typography fontWeight="thin" align="center" muted>
              {description}
            </Typography>
          </Stack>
        </Stack>
      </Layout.Content>
      <Layout.Footer>
        <Stack orientation="horizontal" justify="center" align="center" wrapped>
          <Button
            id="opt-in-btn"
            primary
            fullWidthOnDeviceType="sm"
            onClick={handleOptIn}
            btnSize="large"
          >
            {confirmButtonLabel}
          </Button>
        </Stack>
      </Layout.Footer>
    </Layout>
  );
}
