import { Stack, Typography, List, Image } from '@trueloyal-engineering/react-ui';
import { EUDSettings } from '@root/core/config';
import { useAppNavigation } from '@root/hooks';
import { Activity } from '@trueloyal-engineering/ui-api-sdk';
import styles from './member-tier-upgrade-activities.module.css';

export interface MemberTierUpgradeActivitiesProps {
  activityList: Activity[];
}

export function MemberTierUpgradeActivities({ activityList }: MemberTierUpgradeActivitiesProps) {
  const { gotoMemberActivity } = useAppNavigation();

  const { tier_benefits_page_qualified_activities_header_text: listHeaderText } =
    EUDSettings.getInstance().content_settings;

  return (
    <Stack className={styles['member-tier-upgrade-activities']}>
      <Typography className={styles['member-tier-upgrade-activities__label']} variant="bodyLg">
        {listHeaderText}
      </Typography>
      <List className={styles['member-tier-upgrade-activities__list']}>
        {activityList.map((activity) => (
          <List.Item onAction={() => gotoMemberActivity(activity.activity_id)}>
            <Stack gap={0.7} orientation="horizontal" align="center">
              <Image
                alt="Activity icon"
                className={styles['member-tier-upgrade-activities__image']}
                src={activity.icon_image_url}
              />
              <Typography trunc={2} align="start" title={activity.activity_name}>
                {activity.activity_name}
              </Typography>
            </Stack>
          </List.Item>
        ))}
      </List>
    </Stack>
  );
}
