import { ApiClient } from '@root/core/api';
import { MerchantConfig } from '@root/core/config';
import { getGamificationBaseUrl } from '@root/utils/baseurl';
import { ListQueryParams } from '../types';

export const fetchStreakChallengeUserProgress = async <T>(
  queryParams: ListQueryParams
): Promise<T | null> => {
  try {
    const apiClient = ApiClient.getInstance();
    const authToken = await apiClient.client.authToken;
    const merchantClient = MerchantConfig.getInstance();
    const partnerId = await merchantClient?.partnerId;

    const response = await fetch(
      `${getGamificationBaseUrl()}/builder/api/v1.0/schema/streak_and_challenge_status/record?${new URLSearchParams(
        Object.entries(queryParams).reduce(
          (acc, [key, value]) => {
            acc[key] = typeof value === 'string' ? value : JSON.stringify(value);
            return acc;
          },
          {} as Record<string, string>
        )
      )}`,
      {
        method: 'GET',
        headers: {
          'partner-id': partnerId,
          'access-token': authToken || ''
        }
      }
    );
    if (!response.ok) {
      throw new Error(`HTTP error! Status: ${response.status}`);
    }
    const data: T = await response.json();
    return data;
  } catch (error) {
    return null;
  }
};
