import { useState, useEffect } from 'react';
import { useAppDispatch, useAppSelector } from '@root/store';
import { updateMember } from '@root/store/slices/memberSlice';
import { Member, Activity } from '@trueloyal-engineering/ui-api-sdk';
import { toast } from 'react-toastify';
import { ErrorHandler } from '@root/core/helpers/error';
import { ACTIVITY_IDS } from '@root/core/constants/activity.constants';

export interface UseEnterHandleActivityProps {
  activity: Activity;
  eligibleFieldKey: keyof Pick<Member, 'instagram_handle' | 'tiktok_handle'>;
}

export function useEnterHandleActivity({
  activity,
  eligibleFieldKey
}: UseEnterHandleActivityProps) {
  const dispatch = useAppDispatch();
  const [loading, setLoading] = useState(false);
  const [handle, setHandle] = useState('');
  const [showCongratulation, setShowCongratulation] = useState(false);
  const [isSaved, setIsSaved] = useState(false);
  const [isModified, setIsModified] = useState(false);
  const memberDetails = useAppSelector((state) => state.member.memberDetails);
  const { activity_id: activityId, extra_config: extraConfig } = activity;

  useEffect(() => {
    if (!memberDetails) {
      return;
    }
    const currentHandle = memberDetails[eligibleFieldKey] || '';
    setHandle(currentHandle);
    setIsSaved(currentHandle !== '');
    setIsModified(false);
  }, [memberDetails, eligibleFieldKey]);

  const blockedHandleErrorText = extraConfig?.blocked_handle_error_text;
  const duplicateHandleErrorText = extraConfig?.duplicate_handle_error_text;
  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newHandle = e.target.value;
    setHandle(newHandle);
    setIsModified(newHandle !== '' && newHandle !== (memberDetails?.[eligibleFieldKey] || ''));
    setIsModified(
      newHandle.trim() !== '' &&
        newHandle.trim() !== (memberDetails?.[eligibleFieldKey]?.trim() || '')
    );
  };

  const submitHandle = async () => {
    try {
      const errorMapping = {
        BLOCKED_SOCIAL_HANDLE: blockedHandleErrorText || '',
        DUPLICATE_SOCIAL_HANDLE: duplicateHandleErrorText || ''
      };
      setLoading(true);
      const response = await dispatch(
        updateMember({ updateParams: { [eligibleFieldKey]: handle }, errorMapping })
      );

      if (response.meta.requestStatus === 'rejected') {
        return;
      }

      setIsSaved(true);

      if (
        activityId === ACTIVITY_IDS.ZRL_ENTER_INSTAGRAM_HANDLE ||
        activityId === ACTIVITY_IDS.ZRL_ENTER_TIKTOK_HANDLE
      ) {
        setShowCongratulation(true);
      }
    } catch (error) {
      const errorMessage = ErrorHandler.resolveActivityErrorMessage(activity, error);
      toast.error(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  return {
    loading,
    handle,
    setHandle,
    showCongratulation,
    handleChange,
    submitHandle,
    isSaved,
    isModified
  };
}
