import React from 'react';
import { Card, CardProps, classNames } from '@trueloyal-engineering/react-ui';
import { Link } from 'react-router-dom';
import { ACTIVITIES_BASE_PATH, REWARDS_BASE_PATH, STREAKS_BASE_PATH } from '@root/router/paths';
import { MerchantConfig, EUDSettings } from '@root/core/config';
import { replaceLabels } from '@root/core/utils/textUtils';
import {
  FlameIcon,
  GobletIcon,
  RewardIcon,
  TargetIcon
} from '@root/components/QuickActionList/icons';
import styles from './quick-action-list.module.css';

export function QuickActionList(props: CardProps) {
  const classes = classNames(styles['member-action-list'], props?.className);

  const { enableStreaks, enableChallenges } = MerchantConfig.getInstance();
  const {
    activity_section_header_text: activitySectionHeaderText,
    reward_section_header_text: rewardSectionHeaderText,
    streak_section_header_text: streakSectionHeaderText,
    program_details_currency_plural_text: currencyPlural
  } = EUDSettings.getInstance().content_settings;
  const activityHeader = replaceLabels(activitySectionHeaderText, {
    '{{POINTS_LABEL}}': currencyPlural
  });
  const actions = [
    {
      title: activityHeader,
      icon: <GobletIcon />,
      link: ACTIVITIES_BASE_PATH
    },
    {
      title: rewardSectionHeaderText,
      icon: <RewardIcon />,
      link: REWARDS_BASE_PATH
    },
    ...(enableChallenges
      ? [
          {
            title: 'Challenges',
            icon: <TargetIcon />,
            link: ''
          }
        ]
      : []),
    ...(enableStreaks
      ? [
          {
            title: streakSectionHeaderText,
            icon: <FlameIcon />,
            link: STREAKS_BASE_PATH
          }
        ]
      : [])
  ];

  return (
    <div className={classes}>
      {actions.map((item) => (
        <Link to={item.link} key={item.title} className={styles.link}>
          <Card className={styles['member-action-list__card']}>
            <div className={styles['member-action-list__thumb']}>{item.icon}</div>
            {item.title}
          </Card>
        </Link>
      ))}
    </div>
  );
}
