import { EUDSettings } from '@root/core/config';
import { TierHelper } from '@root/core/helpers';
import { useAppSelector } from '@root/store';
import { Button, ProgressBar, Typography, Card } from '@trueloyal-engineering/react-ui';
import { Tier, TierInfo } from '@trueloyal-engineering/ui-api-sdk';
import styles from './member-tier-info.module.css';

export interface MemberTierInfoProps {
  memberCurrentTierInfo: TierInfo;
  nextTier: Tier | undefined;
  onViewBenefits?: () => void;
  showViewBenefits?: boolean;
}

export function MemberTierInfo({
  memberCurrentTierInfo,
  nextTier,
  onViewBenefits,
  showViewBenefits = true
}: MemberTierInfoProps) {
  const { dashboard_header_section_view_benefits_link_label: viewBenefitsButtonLabel } =
    EUDSettings.getInstance().content_settings;
  const { qualified_points: qualifiedPoints } = memberCurrentTierInfo;
  const minimumPoints = nextTier?.minimum_points ?? qualifiedPoints;

  const progressValue = (qualifiedPoints / minimumPoints) * 100;
  const requiredPoints = minimumPoints - qualifiedPoints;

  const benefitDescriptionText = TierHelper.getBenefitDescription(nextTier, requiredPoints);
  const tiers = useAppSelector((state) => state.tier.tiers);
  const tier = tiers?.find((t) => t.tier_id === memberCurrentTierInfo.loyalty_tier_id);
  const tierProgramType = tier?.level_program_type ?? 'units_based';
  const tierValidtyText = TierHelper.getTierValidityText(
    memberCurrentTierInfo.loyalty_tier_name,
    memberCurrentTierInfo.conditional_tier_end_date
  );
  const showProgressBar = tierProgramType !== 'conditional';

  // FIXME: This should come from tier api
  const imageURL = 'https://d1qbqkkh49kht1.cloudfront.net/57611553f77cf73834e2440254a7cbc9.png';

  const tierValidityMarkup = (
    <Card aria-label="Member Tier Validity" className="member-tier-info__tier-validity">
      <Card.Section>
        <Typography>{tierValidtyText}</Typography>
      </Card.Section>
    </Card>
  );

  return (
    <div className={styles['member-tier-info']}>
      {!showProgressBar && tierValidityMarkup}
      {showProgressBar && (
        <ProgressBar value={progressValue} imageURL={imageURL} role="progressbar" />
      )}
      <Typography variant="bodyMd" fontWeight="thin" muted>
        {benefitDescriptionText}{' '}
        {showViewBenefits && (
          <Button link onClick={onViewBenefits} role="navigation" id="view-tier-benefits-btn">
            {viewBenefitsButtonLabel}
          </Button>
        )}
      </Typography>
    </div>
  );
}
