import { Card, Stack, Typography } from '@trueloyal-engineering/react-ui';
import { Tier, TierInfo } from '@trueloyal-engineering/ui-api-sdk';
import { MemberTierInfo } from '@root/containers/member/MemberTierInfo';
import { Icon } from '@root/components';

export interface TierSectionProps {
  currentTierInfo: TierInfo;
  nextTier: Tier | undefined;
  gotoTierBenefits?: () => void;
}

export function MemberTierSection({
  currentTierInfo,
  nextTier,
  gotoTierBenefits
}: TierSectionProps) {
  const headerMarkup = (
    <Typography fontWeight="bold" variant="headerLg">
      <Stack orientation="horizontal" align="center" gap={0.3}>
        <Icon name="verified" size={19.7} />
        {currentTierInfo.loyalty_tier_name}
      </Stack>
    </Typography>
  );

  return (
    <Card.Section data-tier_id={currentTierInfo.loyalty_tier_id}>
      <Stack gap={0}>
        {headerMarkup}
        <MemberTierInfo
          memberCurrentTierInfo={currentTierInfo}
          nextTier={nextTier}
          onViewBenefits={gotoTierBenefits}
        />
      </Stack>
    </Card.Section>
  );
}
