import type { MerchantConfig } from '@root/core/config';

const DEFAULT_TINT_APP_URL = 'https://app.tintup.com/';
const DEFAULT_TINT_API_URL = 'https://api.tintup.com';

export type TintUrls = {
  /** Advocacy app host, with a trailing slash, e.g. `https://app.tintup.com/`. */
  appUrl: string;
  /** Advocacy API host, without a trailing slash, e.g. `https://api.tintup.com`. */
  apiUrl: string;
  jsUrl: string;
};

/**
 * Advocacy (TINT) hosts for the current environment. The backend sends them in the merchant
 * config; older backends don't, so production stays the fallback.
 */
export function getTintUrls(merchantConfig?: Partial<MerchantConfig>): TintUrls {
  const appUrl = `${(merchantConfig?.tintAppUrl || DEFAULT_TINT_APP_URL).replace(/\/+$/, '')}/`;
  const apiUrl = (merchantConfig?.tintApiUrl || DEFAULT_TINT_API_URL).replace(/\/+$/, '');
  const jsUrl = merchantConfig?.tintJsUrl || `${appUrl}dist/tint.js`;

  return { appUrl, apiUrl, jsUrl };
}
