import { EUDSettings } from '@root/core/config';
import { useAppSelector } from '@root/store';
import { BasicTable, Button, Layout, Stack, Typography } from '@trueloyal-engineering/react-ui';
import { LabelHelpers } from '@root/core/helpers';
import { replaceLabels } from '@root/core/utils/textUtils';
import {
  selectMemberPointsExpirationSchedule,
  selectFormattedPointsExpirationSchedule
} from '@root/store/slices/memberSlice';
import { useAppNavigation } from '@root/hooks';
import styles from './member-points-expiration-details.module.css';
import { usePointsExpirationTableColumnConfig } from './hooks/usePointsExpirationTableColumnConfig';

export function MemberPointsExpirationDetails() {
  const pointsExpirationSchedule = useAppSelector(selectMemberPointsExpirationSchedule);
  const formattedPointsExpirationSchedule = useAppSelector(selectFormattedPointsExpirationSchedule);

  const { gotoMemberRewards } = useAppNavigation();
  const {
    points_expiry_page_cta_button_text: ctaBtnText,
    points_expiry_page_expiration_date_text: tableExpirationDateColumnText,
    program_details_currency_plural_text: currencyPluralText,
    points_expiry_page_description: pointsExpirationDescriptionText
  } = EUDSettings.getInstance().content_settings;

  const pointsExpirationTableColumnConfig = usePointsExpirationTableColumnConfig({
    expirationDateColumnTitle: tableExpirationDateColumnText,
    pointsColumnTitle: currencyPluralText
  });

  if (!pointsExpirationSchedule) {
    return null;
  }

  const pointsExpiryReplaceables =
    LabelHelpers.getPointsExpirationReplaceable(pointsExpirationSchedule);

  const description = replaceLabels(pointsExpirationDescriptionText, pointsExpiryReplaceables);
  return (
    <Layout>
      <Layout.Content>
        <Stack className={styles['member-points-expiration-details']}>
          <Typography variant="bodyMd" fontWeight="thin" muted>
            {description}
          </Typography>
          {pointsExpirationSchedule?.length ? (
            <Stack orientation="vertical" className={styles['expiration-schedule-table']}>
              <BasicTable
                columnConfig={pointsExpirationTableColumnConfig}
                data={formattedPointsExpirationSchedule}
              >
                <BasicTable.THead />
                <BasicTable.TBody />
              </BasicTable>
            </Stack>
          ) : null}
        </Stack>
      </Layout.Content>
      <Layout.Footer>
        <Button fullWidthOnDeviceType="sm" primary onClick={gotoMemberRewards}>
          {ctaBtnText}
        </Button>
      </Layout.Footer>
    </Layout>
  );
}
