import { Card, CardProps, classNames } from '@trueloyal-engineering/react-ui';
import { useAppSelector } from '@root/store';
import { useAppNavigation } from '@root/hooks';
import { Main, MemberTierSection } from './components';
import styles from './member-card.module.css';

export function MemberCard(props: CardProps) {
  const { memberDetails: member, nextTier } = useAppSelector((state) => state.member);
  const { gotoMemberPointsHistory, gotoMemberTier } = useAppNavigation();
  if (!member) {
    return null;
  }

  const classes = classNames(styles['member-card'], props?.className);

  return (
    <Card className={classes} {...props}>
      <Main
        points={member.available_points}
        pointsExpirationSchedule={member.points_expiration_schedule}
        gotoPointsHistory={gotoMemberPointsHistory}
      />
      {member?.tier_info?.loyalty_tier_id && (
        <MemberTierSection
          currentTierInfo={member.tier_info}
          nextTier={nextTier}
          gotoTierBenefits={gotoMemberTier}
        />
      )}
    </Card>
  );
}
