/* eslint-disable no-param-reassign */
import { PayloadAction, createAsyncThunk, createSlice } from '@reduxjs/toolkit';
import { ApiClient } from '@root/core/api';
import {
  CommonQueryParams,
  GetTransactionsQueryParams,
  Transaction,
  TransactionsData
} from '@trueloyal-engineering/ui-api-sdk';
import { EUDSettings } from '@root/core/config';
import { CommonThunkError, CommonState } from '../types';

export interface TransactionState extends CommonState {
  transactions: Transaction[] | undefined;
  totalTransactions: number;
  more: boolean;
  nextCursor: number;
}

export const fetchTransactions = createAsyncThunk<
  TransactionsData | undefined,
  CommonQueryParams<GetTransactionsQueryParams>,
  { rejectValue: CommonThunkError }
>('transaction/fetchTransactions', async (queryParams, { rejectWithValue }) => {
  try {
    const apiClient = ApiClient.getInstance();
    const input = {
      queryParams
    };
    const response = await apiClient.transactions.getTransactions(input);
    if (!response.success) {
      return rejectWithValue({
        errorMessage:
          EUDSettings.getInstance().content_settings.points_history_page_error_state_message
      });
    }
    return response.data;
  } catch (error) {
    return rejectWithValue({
      errorMessage:
        EUDSettings.getInstance().content_settings.points_history_page_error_state_message
    });
  }
});

type FetchTransactionInput = {
  id: string;
  queryParams?: CommonQueryParams;
};

export const fetchTransaction = createAsyncThunk<
  Transaction | undefined,
  FetchTransactionInput,
  { rejectValue: CommonThunkError }
>('transaction/fetchTransaction', async ({ id, queryParams }, { rejectWithValue }) => {
  try {
    const apiClient = ApiClient.getInstance();
    const input = {
      queryParams
    };
    const response = await apiClient.transactions.getTransactionById(id, input);
    if (!response.success) {
      return rejectWithValue({
        errorMessage:
          EUDSettings.getInstance().content_settings.points_history_page_error_state_message
      });
    }
    return response.data;
  } catch (error) {
    return rejectWithValue({
      errorMessage:
        EUDSettings.getInstance().content_settings.points_history_page_error_state_message
    });
  }
});

const initialState: TransactionState = {
  transactions: undefined,
  totalTransactions: 0,
  more: false,
  nextCursor: 0,
  status: 'idle',
  errorMessage: ''
};

export const transactionSlice = createSlice({
  name: 'transaction',
  initialState,
  reducers: {
    setTransactions: (state, action: PayloadAction<Transaction[]>) => {
      state.transactions = action.payload;
    },
    resetTransactionState: () => {
      return initialState;
    }
  },
  extraReducers: (builder) => {
    builder.addCase(fetchTransactions.fulfilled, (state, action) => {
      state.status = 'succeeded';
      if (action.payload?.transactions) {
        if (!state.transactions) {
          state.transactions = action.payload.transactions;
        } else {
          state.transactions = [...state.transactions, ...action.payload.transactions];
        }
      }
      state.more = action.payload?.more ?? false;
      state.nextCursor = action.payload?.next_cursor ?? 0;
      state.totalTransactions = action.payload?.total ?? 0;
    });
    builder.addCase(fetchTransactions.rejected, (state, action) => {
      state.status = 'failed';
      state.errorMessage = action.payload?.errorMessage ?? 'Unknown Error';
    });
    builder.addCase(fetchTransactions.pending, (state, _) => {
      state.status = 'pending';
    });
  }
});

// Action creators are generated for each case reducer function
export const { setTransactions, resetTransactionState } = transactionSlice.actions;

export default transactionSlice.reducer;
