import { EUDSettings } from '@root/core/config';
import { Button } from '@trueloyal-engineering/react-ui';
import { useLocation } from 'react-router-dom';
import { replaceLabels } from '@root/core/utils/textUtils';
import { useAppNavigation } from './useAppNavigation';

export function usePage() {
  const location = useLocation();
  const isGuest = location.pathname.includes('/guest');

  const {
    gotoGuestActivities,
    gotoMemberActivities,
    gotoGuestRewards,
    gotoMemberRewards,
    gotoMemberPointsHistory,
    gotoMemberPointsExpiry,
    gotoMemberOptOut,
    gotoMemberProfile,
    gotoMemberTier,
    gotoHome,
    gotoTermsPage,
    gotoGuestTerms,
    gotoMemberStreaks,
    gotoGuestStreaks
  } = useAppNavigation();
  const {
    content_settings: {
      program_details_currency_plural_text: currencyPlural,
      navigation_home_text: navigationHomeText,
      activity_section_header_text: activityListPageTitle,
      membership_opt_out_page_title: cancelMembershipPageTitle,
      points_expiry_page_title: pointsExpiryPageTitle,
      member_profile_page_title: memberProfilePageTitle,
      tier_benefits_page_title: tierBenefitsPageTitle,
      points_history_page_title: pointsHistoryPageTitle,
      reward_section_header_text: rewardPageTitle,
      terms_label: termsLabel,
      streak_section_header_text: streakPageTitle
    }
  } = EUDSettings.getInstance();

  const PATHS_MAPPING = {
    activities: {
      name: replaceLabels(activityListPageTitle, { '{{POINTS_LABEL}}': currencyPlural }),
      onClick: isGuest ? gotoGuestActivities : gotoMemberActivities
    },
    rewards: {
      name: rewardPageTitle,
      onClick: isGuest ? gotoGuestRewards : gotoMemberRewards
    },
    streaks: {
      name: streakPageTitle,
      onClick: isGuest ? gotoGuestStreaks : gotoMemberStreaks
    },
    'points-history': {
      name: replaceLabels(pointsHistoryPageTitle, { '{{POINTS_LABEL}}': currencyPlural }),
      onClick: gotoMemberPointsHistory
    },
    profile: {
      name: memberProfilePageTitle,
      onClick: gotoMemberProfile
    },
    'opt-out': {
      name: cancelMembershipPageTitle,
      onClick: gotoMemberOptOut
    },
    'terms-page': {
      name: termsLabel,
      onClick: gotoTermsPage
    },
    'guest-terms-page': {
      name: termsLabel,
      onClick: gotoGuestTerms
    },
    'points-expiry': {
      name: replaceLabels(pointsExpiryPageTitle, { '{{POINTS_LABEL}}': currencyPlural }),
      onClick: gotoMemberPointsExpiry
    },
    tier: {
      name: tierBenefitsPageTitle,
      onClick: gotoMemberTier
    }
  };

  const getBreadcrumbs = () => {
    /**
     * Generates breadcrumb buttons based on the current location path.
     * @returns {React.ReactNode[]} An array of breadcrumb buttons.
     *
     * Example:
     * If the pathname is "/profile/points-expiry", the function splits the path using "/".
     * For each segment, it creates a breadcrumb button if the path is available in PATHS_MAPPING.
     * Additionally, it adds a "Home" button at the beginning.
     */
    const paths = location.pathname.split('/');
    const breadcrumbs = paths
      .map((path, index) => {
        if (!Object.prototype.hasOwnProperty.call(PATHS_MAPPING, path)) {
          return null;
        }
        const pathMapping = PATHS_MAPPING[path as keyof typeof PATHS_MAPPING];
        const isLastPath = index === paths.length - 1;
        return (
          <Button mono onClick={pathMapping.onClick} capitalize disabled={isLastPath}>
            {pathMapping.name}
          </Button>
        );
      })
      .filter((element) => element !== null);
    return [
      <Button mono onClick={gotoHome} capitalize>
        {navigationHomeText}
      </Button>,
      ...breadcrumbs
    ];
  };

  return {
    getBreadcrumbs
  };
}
