import React from 'react';
import { useOverlayTriggerState } from 'react-stately';
import { OverlayTriggerProps } from '@react-types/overlays';

import { PopoverCommonProps } from './types';
import { PopoverBody, PopoverTrigger } from './components';

export interface PopoverProps extends OverlayTriggerProps {
  children: React.ReactNode;
}

export function Popover({ children, ...props }: PopoverProps) {
  const state = useOverlayTriggerState(props);
  const ref = React.useRef(null);
  const commonProps: PopoverCommonProps = {
    _state: state,
    _triggerRef: ref
  };
  return (
    <>
      {React.Children.map(children, (child, _) =>
        React.cloneElement(child as React.ReactElement, {
          ...commonProps
        })
      )}
    </>
  );
}

Popover.Trigger = PopoverTrigger;
Popover.Body = PopoverBody;
