/**
 * This component is built on external library
 * But styled according to design
 */
import Calendar, { CalendarProps } from 'react-calendar';
import 'react-calendar/dist/Calendar.css';
import { Card, classNames } from '@trueloyal-engineering/react-ui';
import './override.css';

export interface StyledCalendarProps extends CalendarProps {
  className?: string;
}

export function StyledCalendar({ className, ...props }: CalendarProps) {
  const classes = classNames('styled-calendar', className);
  return (
    <Card className={classes} role="application" aria-label="Calendar">
      <Card.Section>
        <Calendar {...props} />
      </Card.Section>
    </Card>
  );
}
