import React from 'react';
import { Container } from '@trueloyal-engineering/react-ui';
import styles from './hero.module.css';

export interface HeroProps {
  bgImg: string;
  children?: React.ReactNode;
  fillImage?: boolean;
}

export function Hero({ bgImg, children, fillImage = true }: HeroProps) {
  const inlineStyles = {
    '--bg-img': bgImg ? `url(${bgImg})` : 'none',
    '--bg-size': fillImage ? `100% 100%` : `100% 14rem`
  } as React.CSSProperties;

  return (
    <div className={styles.hero} style={inlineStyles} role="region" aria-label="Hero">
      <Container className={styles.hero__wrapper}>{children}</Container>
    </div>
  );
}
