import {
  Button,
  Card,
  CardProps,
  Image,
  Stack,
  Tag,
  Typography,
  classNames
} from '@trueloyal-engineering/react-ui';
import { Reward } from '@trueloyal-engineering/ui-api-sdk';
import { replaceLabels } from '@root/core/utils/textUtils';
import { calculateRemainingPointsPercentage } from '@root/core/utils/getPercentageForProgressbarUtils';
import { sanitizeHTML } from '@root/core/utils/htmlUtils';
import { DEFAULT_IMAGE_URL } from '@root/core/constants/reward.constants';
import { RewardHelper } from '@root/core/helpers/reward';
import { Icon } from '@root/components';
import styles from './reward-card.module.css';

export interface RewardCardProps extends CardProps {
  reward: Reward;
  availablePoints?: number;
  onAction?: () => void;
  readOnly?: boolean;
  className?: string;
}

export function RewardCard({
  reward,
  availablePoints = 0,
  onAction,
  className,
  readOnly = true,
  ...cardProps
}: RewardCardProps) {
  const {
    reward_card_background_image_url: imageUrl,
    points_to_be_redeemed: points,
    enduser_reward_short_description: description,
    reward_name: name,
    extra_parameters: extraParameters
  } = reward;

  const hasEnoughPointsAvailable = availablePoints >= points;
  const remainingPointsPercentage = readOnly
    ? 0
    : calculateRemainingPointsPercentage(availablePoints, points);

  const tagLabelText = RewardHelper.getTagLabelText(reward, points);

  const redeemButtonText = extraParameters?.redeem_button_text;
  const imageSrc = imageUrl || DEFAULT_IMAGE_URL;

  const pointsToUnlockReward = points - availablePoints;
  const ineligibleRewardProgressText = replaceLabels(
    extraParameters?.ineligible_rewards_progress_text,
    { '{{POINTS_TO_UNLOCK_REWARD}}': pointsToUnlockReward }
  );

  const baseClasses = classNames(!readOnly && styles['reward-card--clickable'], className);

  return (
    <Card
      role="region"
      aria-labelledby="Reward Information"
      onClick={!readOnly ? onAction : undefined}
      className={baseClasses}
      data-redemption_id={reward.reward_id}
      {...cardProps}
    >
      <Stack gap={0.8} padding={0.7} align="start">
        <Stack className={styles['reward-card__image-container']}>
          <Image
            loading="lazy"
            className={styles['reward-card__image']}
            src={imageSrc}
            fit="cover"
            fillWidth
          />
          <Tag
            primary
            label={tagLabelText}
            className={styles['reward-card__points-tag']}
            progress={remainingPointsPercentage}
          />
        </Stack>
        <Stack gap={0.2}>
          <Typography
            trunc={2}
            title={name}
            dangerouslySetInnerHTML={{ __html: sanitizeHTML(name) }}
          />
          {readOnly || hasEnoughPointsAvailable ? (
            <Typography
              muted
              trunc={2}
              title={description}
              fontWeight="thin"
              variant="bodySm"
              dangerouslySetInnerHTML={{ __html: sanitizeHTML(description) }}
            />
          ) : (
            <Typography
              fontWeight="thin"
              trunc={2}
              muted
              title={ineligibleRewardProgressText}
              dangerouslySetInnerHTML={{ __html: sanitizeHTML(ineligibleRewardProgressText) }}
              variant="bodySm"
            />
          )}
        </Stack>
        {!readOnly && (
          <Button
            id="view-reward-btn"
            primary
            fullWidthOnDeviceType="all"
            icon={
              !hasEnoughPointsAvailable && (
                <Icon className={styles['reward-card__locked-icon']} name="lock" size={14} />
              )
            }
          >
            {redeemButtonText}
          </Button>
        )}
      </Stack>
    </Card>
  );
}
