import { Modal } from '@root/components';
import { Button, InputField, Stack, Typography } from '@trueloyal-engineering/react-ui';
import { ChangeEvent, useState } from 'react';
import { formatEmails, validateEmailList } from '@root/core/utils/textUtils';
import { toast } from 'react-toastify';
import styles from './email-modal.module.css';

export interface EmailModalProps {
  isOpen: boolean;
  className?: string;
  closeModal: () => void;
  description?: string;
  placeholder?: string;
  buttonText?: string;
  cancelText?: string;
  errorText?: string;
  onSubmit: (emails: string) => void;
}

export function EmailModal({
  isOpen,
  className,
  closeModal,
  description,
  placeholder,
  buttonText,
  cancelText,
  errorText,
  onSubmit
}: EmailModalProps) {
  const [emails, setEmails] = useState('');

  const handleSubmit = () => {
    const formattedEmails = formatEmails(emails);
    if (!validateEmailList(formattedEmails)) {
      toast.error(errorText);
      return;
    }
    onSubmit(emails);
    closeModal();
  };

  const handleInputChange = (event: ChangeEvent<HTMLInputElement>) => {
    // Update the state with the new input value
    setEmails(event.target.value);
  };

  return (
    <Modal isOpen={isOpen}>
      <Modal.Body isDismissable>
        <Stack className={className}>
          <Typography variant="bodyMd" fontWeight="thin" muted>
            {description}
          </Typography>
          <InputField
            className={styles['referral-activity__input']}
            placeholder={placeholder}
            value={emails}
            onChange={handleInputChange}
          />
          <Stack orientation="horizontal" wrapped>
            <Button id="submit-emails-tbn" primary onClick={handleSubmit}>
              {buttonText}
            </Button>
            <Button id="close-email-modal-btn" onClick={closeModal}>
              {cancelText}
            </Button>
          </Stack>
        </Stack>
      </Modal.Body>
    </Modal>
  );
}
