import { Button, Image, Stack, Typography } from '@trueloyal-engineering/react-ui';
import { LoadMask } from '@root/components';
import { AuthConfig } from '@root/core/config';
import { DEFAULT_IMAGE_URL } from '@root/core/constants/reward.constants';
import { Perk } from '@root/store/slices/streakPerkSlice';
import { claimPerk } from '@root/store/slices/mockApi/perkLog.api';
import { useState } from 'react';
import { toast } from 'react-toastify';
import { ErrorHandler } from '@root/core/helpers/error';
import { PerkLog, setPerkLog } from '@root/store/slices/perkLogSlice';
import { useAppDispatch } from '@root/store';
import { PerkSuccess } from '../PerkSuccess';
import styles from './perk-details.module.css';

type ApiResponse<T> = {
  data: T;
};

export function PerkDetails({ perk }: { perk: Perk }) {
  const isPreview = AuthConfig.isPreview();
  const imageSrc = perk.eud_image || DEFAULT_IMAGE_URL;
  const [loading, setLoading] = useState(false);
  const [perkLogResponse, setPerkLogResponse] = useState<PerkLog | undefined>();
  const dispatch = useAppDispatch();

  if (perk.reward_log_status === 'claimed') {
    return <PerkSuccess perk={perk} />;
  }

  const claimPerkCoupon = async () => {
    try {
      setLoading(true);
      const response = await claimPerk<ApiResponse<PerkLog>>(perk.reward_log_id);
      if (response?.data) {
        dispatch(setPerkLog(response?.data));
      }
      setPerkLogResponse(response?.data);
    } catch (error) {
      toast.error(ErrorHandler.resolveErrorMessage(error));
    } finally {
      setLoading(false);
    }
  };

  if (perkLogResponse) {
    const updatedPerk = {
      ...perk,
      reward_log_id: perkLogResponse.id,
      coupon_code: perkLogResponse.coupon_code,
      reward_log_status: perkLogResponse.reward_log_status,
      linked_schema_record_id: perkLogResponse.linked_schema_record_id,
      linked_schema_slug: perkLogResponse.linked_schema_slug
    };
    return <PerkSuccess perk={updatedPerk} />;
  }

  return (
    <div className={styles['perk-details']} data-perk_id={perk.id}>
      {loading && <LoadMask />}
      <Image className={styles['perk-details__image']} src={imageSrc} fit="contain" />
      <main>
        <section>
          <Stack gap={0.6}>
            <Typography trunc={2} title={perk.eud_title} variant="header2xl" fontWeight="bold">
              {perk.eud_title}
            </Typography>
            <Typography fontWeight="thin" muted>
              {perk.eud_description}
            </Typography>
          </Stack>
        </section>
        <section className={styles['perk-details__footer']}>
          {!isPreview && perk.reward_log_status === 'unlocked' && (
            <Button
              id="perk-confirm-btn"
              fullWidthOnDeviceType="sm"
              primary
              onClick={claimPerkCoupon}
              btnSize="large"
            >
              {perk.eud_claim_button_label}
            </Button>
          )}
        </section>
      </main>
    </div>
  );
}
