import { Button, Stack, Image, Typography, Layout } from '@trueloyal-engineering/react-ui';
import { EUDSettings } from '@root/core/config';
import { CopyToClipboardInput } from '@root/components';
import { useAppNavigation } from '@root/hooks';
import { toast } from 'react-toastify';
import { Perk } from '@root/store/slices/streakPerkSlice';
import styles from './perk-success.module.css';

export interface PerkSuccessProps {
  perk: Perk;
}

export function PerkSuccess({ perk }: PerkSuccessProps) {
  const { gotoHome, gotoMemberStreakDetails } = useAppNavigation();

  const {
    content_settings: {
      commons_copy_text_successful_text: copiedToastText,
      reward_details_page_congratulation_text: congratulationText,
      reward_details_page_redeem_more_button_label: redeemMoreButtonLabel,
      reward_details_page_goto_home_button_label: gotoHomeButtonLabel
    },
    reward_details_page_congratulations_image_url: imageURL,
    congratulations_confetti_url: confettiURL
  } = EUDSettings.getInstance();

  const handleCopy = () => {
    toast.success(copiedToastText, { hideProgressBar: true, autoClose: 1000 });
  };

  return (
    <Layout
      className={styles['perk-success']}
      data-perk_id={perk.id}
      data-perk_log_id={perk.reward_log_id}
    >
      <Layout.Content centered className={styles['perk-success__content']}>
        <Stack justify="center" align="center" gap={2}>
          <Stack justify="center" align="center" gap={0.5}>
            <Image src={imageURL} role="presentation" className={styles['perk-success__image']} />
            <Typography as="h1" variant="header3xl" fontWeight="bold" align="center">
              {congratulationText}
            </Typography>
          </Stack>
          {perk.coupon_code && (
            <CopyToClipboardInput
              label={perk.eud_post_claim_message}
              value={perk.coupon_code}
              textAlign="center"
              borderStyle="dotted"
              onCopy={handleCopy}
            />
          )}
        </Stack>
        <img
          className={styles['perk-success__confetti']}
          src={confettiURL}
          alt="confetti"
          role="presentation"
        />
      </Layout.Content>
      <Layout.Footer>
        <Stack justify="center" align="center">
          <Button
            id="redeem-more-btn"
            fullWidthOnDeviceType="sm"
            primary
            relaxed
            onClick={() => gotoMemberStreakDetails(perk.linked_schema_record_id)}
            btnSize="large"
          >
            {redeemMoreButtonLabel}
          </Button>
          <Button
            id="goto-home-btn"
            fullWidthOnDeviceType="sm"
            relaxed
            onClick={gotoHome}
            btnSize="large"
          >
            {gotoHomeButtonLabel}
          </Button>
        </Stack>
      </Layout.Footer>
    </Layout>
  );
}
