import { Button, InputField, Stack, Typography, Layout } from '@trueloyal-engineering/react-ui';
import { Email as EmailIcon, X as XIcon, Facebook as FacebookIcon } from '@root/icons';
import { Activity } from '@trueloyal-engineering/ui-api-sdk';
import { useState } from 'react';
import { toast } from 'react-toastify';
import { UIHelpers } from '@root/core/helpers/ui';
import { ActivityHeader, LoadMask } from '@root/components';
import { useReferralActivity } from '@root/hooks';
import { AuthConfig, EUDSettings } from '@root/core/config';
import styles from './referral-activity.module.css';
import { EmailModal } from './components';
import { ActivitySuccess } from '../ActivitySuccess';

export interface ReferralActivityProps {
  activity: Activity;
}

export function ReferralActivity({ activity }: ReferralActivityProps) {
  const { commons_copy_text_successful_text: copiedToastText } =
    EUDSettings.getInstance().content_settings;
  const {
    enduser_activity_short_description: shortDescription,
    earnpoints_button_label: tagLabel,
    extra_config: extraConfig
  } = activity;

  const [isModalOpen, setModalOpen] = useState(false);

  const { loading, referralURL, showCongratulation, referViaEmail, referViaSocials } =
    useReferralActivity({
      activity
    });

  const handleCopy = () => {
    UIHelpers.copyToClipboard(referralURL, () => {
      toast.success(copiedToastText, { hideProgressBar: true, autoClose: 1000 });
    });
  };

  const copyButtonText = extraConfig?.copy_button_text;
  const invalidEmailText = extraConfig?.email_validation_error_text;
  const emailPlaceholderText = extraConfig?.email_placeholder_text;
  const emailShareText = extraConfig?.email_share_text;
  const emailShareButtonText = extraConfig?.email_share_button_text;
  const description = extraConfig?.referral_award_description_text;
  const emailCancelButtonText = extraConfig?.email_cancel_button_text;

  if (showCongratulation) {
    return <ActivitySuccess activity={activity} />;
  }

  const isPreview = AuthConfig.isPreview();

  return (
    <Layout className="referral-activity">
      {loading && <LoadMask />}
      <Layout.Content>
        <Stack gap={2}>
          <Stack>
            <ActivityHeader
              tagLabel={tagLabel}
              title={shortDescription}
              description={description}
            />
            <InputField
              className={styles['referral-activity__input']}
              defaultValue={referralURL}
              readOnly
            />
            <Button
              id="referral-copy-url-btn"
              primary
              fullWidthOnDeviceType="sm"
              relaxed
              onClick={handleCopy}
              btnSize="large"
            >
              {copyButtonText}
            </Button>
          </Stack>

          <Typography className={styles['referral-activity__divider']}>Or Share Via</Typography>
          <div className={styles['referral-activity__share-options']}>
            <Button
              id="refer-via-email-btn"
              iconOnly
              icon={<EmailIcon width="24" height="24" />}
              onClick={() => !isPreview && setModalOpen(true)}
              aria-label="Share Via Email"
            />
            <Button
              id="refer-via-twitter-btn"
              onClick={() => !isPreview && referViaSocials('twitter')}
              iconOnly
              icon={<XIcon width="24" height="24" />}
              aria-label="Share Via Twitter"
            />
            <Button
              id="refer-via-facebook-btn"
              onClick={() => !isPreview && referViaSocials('facebook')}
              iconOnly
              icon={<FacebookIcon width="24" height="24" />}
              aria-label="Share Via Facebook"
            />
          </div>
        </Stack>

        <EmailModal
          description={emailShareText}
          placeholder={emailPlaceholderText}
          buttonText={emailShareButtonText}
          cancelText={emailCancelButtonText}
          errorText={invalidEmailText}
          className={styles['referral-activity__email-modal']}
          isOpen={isModalOpen}
          closeModal={() => setModalOpen(false)}
          onSubmit={referViaEmail}
        />
      </Layout.Content>
    </Layout>
  );
}
