import { ActivityHelper } from '@root/core/helpers';
import { ErrorHandler } from '@root/core/helpers/error';
import { useAppDispatch } from '@root/store';
import { fetchMember } from '@root/store/slices/memberSlice';
import { Activity } from '@trueloyal-engineering/ui-api-sdk';
import { useState } from 'react';
import { toast } from 'react-toastify';

export interface UseEnterCodeActivityProps {
  activity: Activity;
}

export function useEnterCodeActivity({ activity }: UseEnterCodeActivityProps) {
  const [loading, setLoading] = useState(false);
  const [code, setCode] = useState('');
  const [showCongratulation, setShowCongratulation] = useState(false);
  const dispatch = useAppDispatch();

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setCode(e.target.value);
  };

  const submitCode = async () => {
    try {
      setLoading(true);
      const response = await ActivityHelper.performCodeSubmission(code);
      if (response.success) {
        dispatch(fetchMember());
        setShowCongratulation(true);
      }
    } catch (error) {
      const errorMessage = ErrorHandler.resolveActivityErrorMessage(activity, error);
      toast.error(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  return {
    loading,
    showCongratulation,
    handleChange,
    submitCode,
    code
  };
}
