import { getShareUrlArgsType, getShareUrlForReferralArgsType } from '@root/types'

/**
 * There are the exposed utilities out of sdk
 */
export class HelperUtils {
  /**
   * Helper function to read file
   * @param file
   * @returns
   */
  private static readonly readFile = (file: File, returnAsText = false): Promise<string> => {
    return new Promise((resolve, reject) => {
      if (file) {
        const reader = new FileReader()
        reader.onload = (event: ProgressEvent<FileReader>) => {
          const contents = (event?.target?.result || '') as string
          resolve(contents)
        }

        reader.onerror = error => {
          reject(error)
        }

        if (!returnAsText) {
          reader.readAsDataURL(file)
        } else {
          reader.readAsText(file)
        }
      } else {
        reject()
      }
    })
  }

  /**
   * Read file as a base64 string
   * @param file
   * @returns
   */
  static readonly readFileAsBase64 = (file: File): Promise<string> => {
    return this.readFile(file, false)
  }

  /**
   * Read file as a plain string
   * @param file
   * @returns
   */
  static readonly readFileAsText = (file: File): Promise<string> => {
    return this.readFile(file, true)
  }

  static readonly getShareUrl = (activity: getShareUrlArgsType): string => {
    let returnValue = ''

    const trackCode = encodeURIComponent(activity.track_code)
    const shareUrl = `${activity.base_share_url}?zrl_id=${trackCode}&ls=zrl_share`
    const encodedUrl = encodeURIComponent(shareUrl)

    switch (activity.activity_id) {
      case 'share_on_facebook':
        {
          returnValue = `https://www.facebook.com/sharer/sharer.php?u=${encodedUrl}`
        }
        break
      case 'share_on_twitter':
        {
          const tweetMessage = activity?.extra_config?.tweet_message
          const encodedText = encodeURIComponent(`${tweetMessage} ${shareUrl}`)
          returnValue = `https://twitter.com/intent/tweet?text=${encodedText}`
        }
        break
      case 'share_on_pinterest':
        {
          const pinPostImage = activity?.extra_config?.pin_post_image || ''
          const pinPostDescription = activity?.extra_config?.pin_post_description || ''
          const encodedImage = encodeURIComponent(pinPostImage)
          const encodedDescription = encodeURIComponent(pinPostDescription)
          returnValue = `https://pinterest.com/pin/create/button/?url=${encodedUrl}&media=${encodedImage}&description=${encodedDescription}`
        }
        break
      default:
        break
    }

    return returnValue
  }

  public static getShareURLForReferral({ shareNetwork, shareURL, extraConfig }: getShareUrlForReferralArgsType) {
    switch (shareNetwork) {
      case 'facebook': {
        const encodedText = encodeURIComponent(shareURL)
        return `https://www.facebook.com/sharer/sharer.php?u=${encodedText}`
      }
      case 'twitter': {
        const tweetMessage = extraConfig?.tweet_message ?? ''

        const encodedText = encodeURIComponent(`${tweetMessage} ${shareURL}`)
        return `https://twitter.com/intent/tweet?text=${encodedText}`
      }
      default:
        return ''
    }
  }

  public static getInstagramProfileURL(instagramHandle: string) {
    const encodedHandle = encodeURIComponent(instagramHandle)
    return `https://www.instagram.com/${encodedHandle}/`
  }
}
