import { GTM_PATHS_MAPPING } from '@root/router/paths';
import { matchPath } from 'react-router-dom';

export function getPageName(path: string): string {
  // Check if the path is exactly matched in the mapping
  if (GTM_PATHS_MAPPING[path as keyof typeof GTM_PATHS_MAPPING]) {
    return GTM_PATHS_MAPPING[path as keyof typeof GTM_PATHS_MAPPING];
  }

  // Check if there's a partial match (e.g., '/activities/123')
  const matchedPath = Object.keys(GTM_PATHS_MAPPING).find((key) => {
    const match = matchPath(key, path);
    return match !== null;
  });
  // Default to a generic name if no match found
  return matchedPath
    ? GTM_PATHS_MAPPING[matchedPath as keyof typeof GTM_PATHS_MAPPING]
    : 'Unknown Page';
}
