import { NestedPartial } from '@root/core/types';

export function overrideObject<T>(original: T, overrides: NestedPartial<T>): T {
  const merged: any = { ...original };

  Object.keys(overrides).forEach((key) => {
    if (Object.prototype.hasOwnProperty.call(overrides, key)) {
      if (
        typeof overrides[key as keyof T] === 'object' &&
        overrides[key as keyof T] !== null &&
        !Array.isArray(overrides[key as keyof T])
      ) {
        if (key && overrides[key as keyof T]) {
          merged[key] = overrideObject(
            original[key as keyof T],
            overrides[key as keyof T] as Partial<T[keyof T]>
          );
        }
      } else {
        merged[key] = overrides[key as keyof T];
      }
    }
  });

  return merged;
}
