import { useRef, useState } from 'react';
import { Reward, RewardTransaction, Transaction } from '@trueloyal-engineering/ui-api-sdk';
import { useTintForm } from '@root/hooks/useTintForm';
import { AuthConfig, MerchantConfig } from '@root/core/config';
import { TintForm } from '@root/components';
import { RewardSuccess } from '../RewardSuccess';

type TintRewardFormProps = {
  reward: Reward;
};

export function TintRewardForm({ reward }: TintRewardFormProps): JSX.Element | null {
  const formRef = useRef<any>(null);
  const [redeemResponse, setRedeemResponse] = useState<
    RewardTransaction | Transaction | undefined
  >();

  useTintForm({
    formRef,
    onSuccess: (transaction) => {
      setRedeemResponse(transaction);
    }
  });

  if (redeemResponse) {
    return <RewardSuccess rewardTransaction={redeemResponse} reward={reward} />;
  }

  return (
    <div ref={formRef} data-reward-id={reward.reward_id}>
      <TintForm
        teamId={MerchantConfig.getInstance().tintTeamId}
        formId={reward.tint_form_id}
        accessToken={AuthConfig.getInstance().accessToken}
        metadata={`reward_id=${reward.reward_id}`}
      />
    </div>
  );
}
