import { ActivityHeader, LoadMask } from '@root/components';
import { Layout, Stack } from '@trueloyal-engineering/react-ui';
import { Activity } from '@trueloyal-engineering/ui-api-sdk';
import { MerchantConfig } from '@root/core/config';
import { useState } from 'react';
import { ActivitySuccess } from '../ActivitySuccess';
import { TintActivityForm } from './TintActivityForm';

export interface FormActivityProps {
  activity: Activity;
}

export function FormActivity({ activity }: FormActivityProps) {
  const { enduser_activity_short_description: title, earnpoints_button_label: tagLabel } = activity;

  const { enableFormBuilderPoweredActivities, tintTeamId } = MerchantConfig.getInstance();

  const [loading] = useState(false);
  const [showCongratulation, setShowCongratulation] = useState(false);

  const shouldShowTintForm =
    enableFormBuilderPoweredActivities && Boolean(tintTeamId) && activity.tint_form_id;

  if (showCongratulation) {
    return <ActivitySuccess activity={activity} />;
  }

  return (
    <Layout className="form-activity">
      {loading && <LoadMask />}
      <Layout.Content>
        <Stack>
          <ActivityHeader tagLabel={tagLabel} title={title} />
          {shouldShowTintForm && (
            <TintActivityForm activity={activity} onSuccess={() => setShowCongratulation(true)} />
          )}
        </Stack>
      </Layout.Content>
    </Layout>
  );
}
