import { ActivityHeader, LoadMask } from '@root/components';
import { Button, Stack, Layout, InputField, Typography } from '@trueloyal-engineering/react-ui';
import { useEnterHandleActivity } from '@root/hooks/useEnterHandleActivity';
import {
  ACTIVITY_IDS,
  HANDLE_TYPE_INSTAGRAM,
  HANDLE_TYPE_TIKTOK
} from '@root/core/constants/activity.constants';
import { AuthConfig } from '@root/core/config';
import { Activity } from '@trueloyal-engineering/ui-api-sdk';
import styles from './enter-handle-activity.module.css';
import { ActivitySuccess } from '../ActivitySuccess';

export interface EnterHandleActivityProps {
  activity: Activity;
}

export function EnterHandleActivity({ activity }: EnterHandleActivityProps) {
  const {
    earnpoints_button_label: tagLabel,
    extra_config: extraConfig,
    enduser_activity_short_description: earnPointsDescription,
    activity_id: activityId
  } = activity;
  const activityStartButtonText = extraConfig?.activity_start_button_text;
  const enterHandlePlaceholderText = extraConfig?.enter_handle_placeholder_text;
  const rewardInstructionText = extraConfig?.reward_instruction_text;
  let handleType: 'instagram_handle' | 'tiktok_handle';

  const activityHandleMap: { [key: string]: 'instagram_handle' | 'tiktok_handle' } = {
    [ACTIVITY_IDS.ZRL_ENTER_INSTAGRAM_HANDLE]: HANDLE_TYPE_INSTAGRAM,
    [ACTIVITY_IDS.ZRL_ENTER_TIKTOK_HANDLE]: HANDLE_TYPE_TIKTOK
  };

  const handleTypeValue = activityHandleMap[activityId];
  if (handleTypeValue) {
    handleType = handleTypeValue;
  } else {
    throw new Error('Unsupported activity_id');
  }

  const { loading, handle, isSaved, showCongratulation, handleChange, submitHandle } =
    useEnterHandleActivity({
      activity,
      eligibleFieldKey: handleType
    });

  const isPreview = AuthConfig.isPreview();

  if (showCongratulation) {
    return <ActivitySuccess activity={activity} />;
  }

  return (
    <Layout className="enter-handle-activity">
      {loading && <LoadMask />}
      <Layout.Content>
        <Stack>
          <ActivityHeader
            tagLabel={tagLabel}
            title={earnPointsDescription}
            description={rewardInstructionText}
          />
          <Stack
            orientation="horizontal"
            gap={0.4}
            className={styles['enter-handle-symbol__wrapper']}
          >
            <Typography variant="bodyXl" fontWeight="thin" muted>
              @
            </Typography>
            <InputField
              placeholder={enterHandlePlaceholderText}
              value={handle}
              onChange={handleChange}
              disabled={isSaved}
            />
          </Stack>
        </Stack>
      </Layout.Content>
      <Layout.Footer>
        <Button
          id="add-handle-btn"
          fullWidthOnDeviceType="sm"
          primary
          onClick={!isPreview ? submitHandle : undefined}
          btnSize="large"
          disabled={isSaved || !handle}
        >
          {activityStartButtonText}
        </Button>
      </Layout.Footer>
    </Layout>
  );
}
