import { Stack, Button, Layout } from '@trueloyal-engineering/react-ui';
import { Activity } from '@trueloyal-engineering/ui-api-sdk';
import { ActivityHeader, LoadMask } from '@root/components';
import { Instagram as InstagramIcon } from '@root/icons';
import { useInstagramActivity } from '@root/hooks';
import { AuthConfig } from '@root/core/config';
import { ActivitySuccess } from '../ActivitySuccess';

export interface InstagramFollowActivityProps {
  activity: Activity;
}

export function InstagramFollowActivity({ activity }: InstagramFollowActivityProps) {
  const {
    enduser_activity_short_description: title,
    earnpoints_button_label: tagLabel,
    extra_config: extraConfig
  } = activity;

  const { loading, showCongratulation, onFollow } = useInstagramActivity({
    activity
  });

  if (showCongratulation) {
    return <ActivitySuccess activity={activity} />;
  }

  const isPreview = AuthConfig.isPreview();
  const description = extraConfig?.reward_instruction_text;
  const followButtonText = extraConfig?.follow_button_text;

  return (
    <Layout className="instagram-activity">
      {loading && <LoadMask />}
      <Layout.Content>
        <Stack>
          <ActivityHeader tagLabel={tagLabel} title={title} description={description} />
        </Stack>
      </Layout.Content>
      <Layout.Footer>
        <Button
          id="instagram-follow-btn"
          fullWidthOnDeviceType="sm"
          primary
          icon={<InstagramIcon />}
          onClick={!isPreview ? onFollow : undefined}
          btnSize="large"
        >
          {followButtonText}
        </Button>
      </Layout.Footer>
    </Layout>
  );
}
